INSERT INTO meta (key, value) VALUES ('coauthor_reply_2026_11_14', 'Bhaskar relayed a ChatGPT review of the findings memo. It recommends keeping the submitted arXiv v2 and making five edits at the next revision (F3, F4, F5, F8, and F10 with sigma^2 > 0), leaving the other findings and the 17 unproved assertions as written with Lean supplying the arguments, giving every point a disposition, recording a per-result completion record (label, Lean theorem, hypotheses, what is still assumed, axioms), and putting the field-to-curve derivation (C17.b, C18) and completing the square (C5) ahead of the small remarks.');
INSERT INTO meta (key, value) VALUES ('decision_two_homes', '2026-11-14 (Scott, after the co-author''s reply): a proof has one of two homes. Where the paper proves a claim, Lean mirrors the paper''s proof step for step. Where the paper gives no proof or skips an argument, Lean mirrors a written argument kept in the ledger (a supplement proof or a supplied step) and the claim is reported as verified with supplied steps, never as following the paper. Paper edits are asked for only at statement level: hypotheses, definitions, and what is claimed. Every point raised gets a disposition.');
INSERT INTO meta (key, value) VALUES ('decision_unproved_claims', 'SUPERSEDED on 2026-11-14 by decision_two_homes. 2026-11-13 (Scott): claims the paper asserts without proof get short proofs added to an appendix through tracked edits, and those proofs are then formalized.');
INSERT INTO meta (key, value) VALUES ('decisions_2026_11_18', '2026-11-18 (Scott), on realigning to arXiv v3, in which Bhaskar carried out every agreed edit (F3, F4, F5 with C8.b, F8, F10.2, F10.3, F18) and settled F9 by assuming innovations with mean zero conditional on the past states. (1) C8 cites C7''s steps: the corollary''s new proof uses Eq. innovation_split and Eq. innovation_energy, which are steps 3 and 4 of the proof of C7, so step C8/p2/s2 lists C7/p1/s3 and C7/p1/s4 in step_deps and the Lean file imports C7''s proof file; check and audit allow exactly the listed steps. No sub-claims. (2) C8.b is merged into C8: the claim and its draft Lean statement are removed, the fact is stated and proved by the step lemmas of C8/a2, and the decision row C8.b/d1 is kept, pointed at C8. (3) The directory is renamed papers/arxiv-v3/lean; the Lean namespace TinaV2 stays, because renaming it would change every frozen hash. (4) Findings F3, F4, F5, F8, F9, F10 and F18 are closed.');
INSERT INTO meta (key, value) VALUES ('decisions_2026_11_19', '2026-11-19 (Scott), when the statement review resumed. (1) F11 closed. (2) The header comments of the ten draft statement files cite main-v3.tex; frozen files keep main-v2.tex. (3) C10: the equality case is an equivalence (C10/f2, difference C10/f2/d3), so that the statement gives the strict advantage of stale-global below the threshold; the eta_S(0) = 1 clause stays at the paper''s wording. (4) The two sentences after the crossover theorem (main-v3.tex 516-519) are the new remark claim C10.b, with a supplement proof from C10. (5) C8/f1 approved and frozen. (6) C10/f2 and C10.b/f1 approved and frozen. (7) sigma^2 > 0 stays a hypothesis of C18 and C19 and is not moved into CanonicalField; Defs/Canonical.lean is not refrozen (C17/f1/d3). (8) C18/f1, C19/f2, C14/f1, C16/f1, C15/f1, C15.b/f1, C15.c/f1, C11/f1, C4.b/f2 and C19.b/f2 approved and frozen: the statement review is complete, 35 statements frozen. (9) ledger.py check warns when a verified claim cites a claim whose statement is not frozen. (10) Whether to suggest simplifications (unused hypotheses) is parked; examples are in future-tasks.md.');
INSERT INTO meta (key, value) VALUES ('paper', 'arXiv v3 (submissions/arxiv-v3/main-v3.tex and technical-appendices-v3.tex, upstream commit 12a9b32, 2026-11-18). Until then the ledger tracked arXiv v2 (submissions/arxiv-v2/main-v2.tex and technical-appendices-v2.tex, which stay in the repository; called tina-v2-alt, main-alt.tex and technical-appendices-alt.tex until upstream commit 2821560). The Lean package and namespace keep the name TinaV2.');
INSERT INTO meta (key, value) VALUES ('review_ledger', 'submissions/arxiv-v2/alt-review/claim-ledger.md');
INSERT INTO meta (key, value) VALUES ('schema_version', '3');
INSERT INTO meta (key, value) VALUES ('toolchain', 'Lean 4.33.1, Mathlib v4.33.1 (0df444a). Packages were cloned from an existing local checkout to avoid a slow download; a fresh machine runs ''lake exe cache get''.');
INSERT INTO sources (id, path, git_commit, sha256) VALUES ('APP', 'submissions/arxiv-v3/technical-appendices-v3.tex', '12a9b3265fec20d55c9e630fbeee1016f3fca3c1', '32ded68b597fba6fd5868f27b2136920111785f138b057c7875519697fa147c7');
INSERT INTO sources (id, path, git_commit, sha256) VALUES ('MAIN', 'submissions/arxiv-v3/main-v3.tex', '12a9b3265fec20d55c9e630fbeee1016f3fca3c1', 'd7995f2ae29a9cf8fe75c861cac270a7c480045900182460b017ab5de2384a7d');
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C1', NULL, 'lemma', 'Fixed-architecture quadratic projection', 'The admissible policy set S(A) is a closed linear subspace of L2; the unique optimal policy is the Q-weighted orthogonal projection of x* onto S(A); R(A) = (1/2)||x* - Pi x*||_Q^2.', 'APP', 'lem:radner_projection', 147, 214, 'lean', 'C', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C1.b', 'C1', 'remark', 'Q-orthogonality and Pythagorean form', 'The projection error is Q-orthogonal to every admissible policy; 2R(A) = ||x*||_Q^2 - ||u*_A||_Q^2.', 'APP', NULL, 216, 218, 'lean', 'C', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C1.c', 'C1', 'remark', 'Information inclusion', 'If G_i is contained in G''_i for all i then S(A) is contained in S(A'') and R(A'') <= R(A).', 'APP', 'eq:info_inclusion', 111, 119, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C10', NULL, 'theorem', 'Fresh-local versus stale-global crossover', 'Under the composition theorem, let R_inf > 0. If 0 <= eta_S(0) < 1, fresh-local is strictly better exactly when tau/T > rho* = (1/2) log(1/(1 - eta_S(0))); equality gives equal regret. If eta_S(0) = 1, no finite delay gives a strict local advantage (rho* = +infinity).', 'MAIN', 'thm:local_global_crossover', 497, 515, 'lean', 'A', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C10.b', 'C10', 'remark', 'Zero threshold at eta_S(0) = 0 and a single crossing', 'When eta_S(0) = 0 the local view already determines the desired action, and every positive global delay makes local information preferable. For an omission share strictly between zero and one, the two losses cross once.', 'MAIN', NULL, 516, 519, 'lean', 'A', 'Added 2026-11-19 at Scott''s review of C10. The third sentence of the paragraph (main-v3.tex 519-520, ''The threshold concerns prediction of the desired action, rather than raw state correlation alone'') is commentary and is not part of the claim.', 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C11', NULL, 'example', 'Two-sensor example', 'Two independent signals, each with mean zero and variance sigma^2 > 0: one fresh sensor has MSE sigma^2/4; both old readings have MSE (sigma^2/2)(1 - exp(-2 tau/T)); the fresh reading wins iff tau > T log(2)/2.', 'MAIN', NULL, 66, 92, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C12', NULL, 'proposition', 'Local explainability under aggregate coupling', 'For f = sum_i (q/2 x_i^2 - theta_i x_i) + (gamma/2)(sum_i x_i)^2 with independent mean-zero equal-variance theta_i: the optimal fresh-local policy is theta_i/(q+gamma) and eta_S(0) = gamma^2 (n-1) / ((q+gamma)(q+gamma(n-1))); R_inf and R_loc as in APP eq:aggregate_Rinf, eq:aggregate_Rloc.', 'MAIN', 'prop:aggregate_local', 577, 627, 'lean', 'B', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C13', NULL, 'remark', 'Explicit aggregate-coupling threshold', 'rho*(gamma,n) = (1/2) log[(q+gamma)(q+gamma(n-1)) / (q(q+gamma n))], and R_loc < R_glob(tau) iff tau/T > rho*(gamma,n).', 'MAIN', 'eq:aggregate_rho_star', 629, 661, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C13.b', 'C13', 'remark', 'Large-n limit of the threshold', 'rho*(gamma,n) -> (1/2) log(1 + gamma/q) as n -> infinity; local information captures share q/(q+gamma) in the limit.', 'MAIN', 'eq:large_n_threshold', 663, 678, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C13.c', 'C13', 'remark', 'Threshold behaviour in the coupling strength', 'gamma = 0 gives eta_S(0) = 0 and a zero threshold, so any positive global delay favours fresh-local; eta_S(0) and the crossover increase with gamma.', 'MAIN', NULL, 680, 687, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C14', NULL, 'remark', 'Radius objective and one-more-hop criterion', 'Assume R_inf > 0 throughout the section. With G(r) = (1 - eta_S(r)) exp(-2 tau(r)/T): R(r) = R_inf [1 - G(r)]; one more hop improves performance iff G(r+1) > G(r); R(r)/R_inf = (1 - exp(-2 tau(r)/T)) + exp(-2 tau(r)/T) eta_S(r).', 'MAIN', 'eq:snapshot_gain', 698, 731, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C15', NULL, 'proposition', 'Continuous marginal-balance characterization', 'Suppose R(r) = R_inf [1 - G(r)] for real r in [0, D], with G the snapshot gain. With tau, eta_S continuously differentiable on [0,D], tau'' >= 0, eta_S'' <= 0, 0 <= eta_S < 1: every interior optimal radius satisfies d/dr log[1 - eta_S(r)] = 2 tau''(r)/T.', 'MAIN', 'thm:marginal_balance', 733, 753, 'lean', 'A', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C15.b', 'C15', 'remark', 'Single-crossing gives the unique optimum', 'If the difference of the two sides of the balance condition is strictly decreasing in r, its sign identifies the unique optimum (0, D, or the unique interior crossing).', 'MAIN', NULL, 755, 760, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C15.c', 'C15', 'remark', 'Comparative statics in T and latency scale', 'Holding the omission curve fixed under single crossing, increasing T moves the preferred radius weakly outward; increasing alpha in tau = alpha tau_0 moves it weakly inward.', 'MAIN', NULL, 761, 765, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C16', NULL, 'proposition', 'Optimal radius for exponential omission', 'Suppose R(r) = R_inf [1 - G(r)] for real r >= 0, with G the snapshot gain. For eta_S(r) = eta_0 exp(-2r/l_c), 0 < eta_0 < 1, l_c > 0, tau(r) = r/v, v > 0: the unique global optimum is r* = (l_c/2)[log(eta_0 (1 + vT/l_c))]_+, positive iff eta_0 (1 + vT/l_c) > 1; with cap D the optimum is min{D, r*}.', 'MAIN', 'prop:generic_exponential_radius', 773, 801, 'lean', 'A', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C17', NULL, 'definition', 'Canonical line model', 'Zero-mean jointly Gaussian space-time field on the infinite line with variance sigma^2 > 0 and covariance sigma^2 exp(-|z-z''|/l_s) exp(-|t-s|/T); target x*(z,t) = integral of w_{l_c}(u) theta(z+u,t) du with w = exp(-|u|/l_c)/(2 l_c); loss (q/2)[x(z) - x*(z)]^2; observation of all field values within distance r; tau(r) = r/v; regret per unit length.', 'MAIN', 'subsec:canonical_line_model', 809, 852, 'lean', 'D', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C17.b', 'C17', 'remark', 'Composition law holds in the continuum model', 'For the canonical field model, every location z, radius r and delay tau, with a = exp(-tau/T): E[x*(z,t) | O_r(z,t-tau)] = a E[x*(z,t-tau) | O_r(z,t-tau)], and the delayed interval retains a^2 times the gain (over acting without observations) of a fresh interval of the same radius. Equivalently, though the paper does not display it, R(r,tau) = (1 - a^2) R_inf + a^2 R(r,0). Stated and argued in an unlabelled paragraph, not a numbered result.', 'MAIN', NULL, 854, 870, 'lean', 'D', 'Was kind ''implicit'' (used but not stated) when the ledger was aligned at 4a9b87e. Upstream commit 284a0e0 added the paragraph at main-v2.tex 839-855. It has no \label.', 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C18', NULL, 'lemma', 'Exponential omission by self-similarity', 'For the jointly Gaussian field with the canonical covariance and sigma^2 > 0, the canonical decision and the radius-r observation: eta_S(r) = eta_0 exp(-2r/l_c) with eta_0 = l_c/(l_c + 2 l_s).', 'MAIN', 'prop:canonical_eta_S', 872, 896, 'lean', 'D', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C19', NULL, 'theorem', 'Optimal synchronized-snapshot radius in the canonical model', 'Suppose the field is jointly Gaussian with the canonical covariance and sigma^2 > 0, the target and loss are the canonical ones, and tau(r) = r/v. Then r* = (l_c/2)[log((l_c + vT)/(l_c + 2 l_s))]_+ is the unique optimal radius on the infinite line; r* > 0 iff vT > 2 l_s.', 'MAIN', 'thm:canonical_optimal_radius', 899, 939, 'lean', 'A', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C19.b', 'C19', 'remark', 'Comparative statics of the canonical radius', 'In the interior regime r* increases with T, increases with v, decreases with l_s, and increases with l_c.', 'MAIN', NULL, 916, 939, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C2', NULL, 'corollary', 'Coupled conditional normal equations', 'The team optimum satisfies E[(Q u* - b(theta))_i | G_i] = 0 for every i; these equations are necessary and sufficient; agentwise conditional means are not optimal in general.', 'APP', 'cor:conditional_normal_equations', 220, 269, 'lean', 'C', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C20', NULL, 'remark', 'Large decision-range limit', 'With vT > 2 l_s fixed, r* -> (vT - 2 l_s)/2 as l_c -> infinity.', 'MAIN', NULL, 951, 954, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C21', NULL, 'numeric', 'Fig. local-global phase', 'Monte Carlo crossover estimates agree with the exact boundary; what the estimator does and does not check.', 'MAIN', 'fig:local-global-phase', 966, 997, 'numeric', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C22', NULL, 'numeric', 'Fig. radius-regret', 'Three regimes with constrained optima 0, 0.62638, 2 for l_c = 1, D = 2.', 'MAIN', 'fig:radius-regret', 999, 1028, 'numeric', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C23', NULL, 'numeric', 'Fig. decision relevance', '64-node ring, T = 6, latency 0.12/hop, l_c = 0.7, 2, 6 gives optimal radii 1, 2, 5.', 'MAIN', 'fig:decision-relevance', 1030, 1065, 'numeric', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C24', NULL, 'numeric', 'Fig. general graphs', 'Path, ring, grid, random geometric graph: reference optima 2, 2, 3, 2; diameters 63, 32, 14, 8.', 'MAIN', 'fig:general-graphs', 1067, 1108, 'numeric', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C25', NULL, 'prose', 'Abstract and contribution list', 'Abstract: ''Using the classical Marschak--Radner decomposition, we derive the delay threshold beyond which fresh local information outperforms a complete but older global view''; ''This comparison allows non-Gaussian states and nonlinear decision rules''; ''looking beyond the local node pays only when information travels more than twice the spatial correlation length in one coherence time''; ''increasing only the reach of the decision weights from 0.7 to 6 hops shifts the optimal observation radius from one to five hops''. Three contributions posed as questions: the crossover threshold, the optimal synchronized radius, decision-dependent architectures. The introduction attributes the delayed-information decomposition to Marschak and Radner.', 'MAIN', NULL, 46, 181, 'prose', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C26', NULL, 'prose', 'Related-work positioning and attribution', 'Positioning against Radner, Marschak-Radner, Krainak-Speyer-Marcus, Ballotta et al. and age of information, now including Jiang-Zhou and Munari et al. on spatial fields. Attribution: Marschak-Radner Ch. 7 Eq. (6.5) gives the marginal balance of C15, and the group-size-one case of their Eq. (6.6) gives the local information share 1 - eta_S(0) of C12.', 'MAIN', 'sec:related_work', 1110, 1218, 'prose', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C27', NULL, 'prose', 'Discussion: scope, limitations, assumptions per result', 'Which assumptions each result uses (composition law: any fixed Q > 0, non-Gaussian states allowed; canonical radius: infinite line, jointly Gaussian field with separable exponential covariance, exponential decision kernel, uncoupled squared loss, tau(r) = r/v; finite-graph examples: Gaussian states and Q = I). Design implication: under the single-crossing condition an interior optimal radius balances marginal gain against delay loss; with no interior crossing the optimum is at a boundary; on a general finite graph compare all admissible radii.', 'MAIN', 'sec:discussion_conclusions', 1220, 1299, 'prose', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C3', NULL, 'remark', 'Common information: vector conditional mean is optimal', 'If every agent observes the same Z, m = E[x* | Z] is the unique optimum regardless of off-diagonal Q.', 'APP', NULL, 271, 276, 'lean', 'C', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C3.b', 'C3', 'remark', 'Degenerate normalization R_inf = 0', 'In centered coordinates R_inf = 0 and Q > 0 imply x* = 0 a.s.; the zero rule has zero regret under every architecture, so the unnormalized composition law still holds.', 'APP', NULL, 287, 292, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C3.c', 'C3', 'prose', 'Delay monotonicity, stationarity versus ergodicity remarks', 'Under a stationary Markov environment prediction loss from a common old snapshot is nondecreasing in delay; stationarity makes expected snapshot regret time-invariant; sample-path averages additionally need ergodicity.', 'APP', NULL, 277, 296, 'prose', NULL, NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C4', NULL, 'assumption', 'Common temporal prediction rule', 'Stationary state with finite second moments and, for each delay tau, theta_t = a theta_{t-tau} + eps with a = exp(-tau/T), T > 0, and E[eps | theta_{t-tau}] = 0.', 'MAIN', 'eq:state_innovation_decomposition', 328, 350, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C4.b', 'C4', 'remark', 'Stationary AR(1) satisfies the prediction rule', 'A stationary AR(1) process theta_t = c theta_{t-1} + eps_t with 0 < c < 1 and finite-variance innovations, each with mean zero conditional on the past states (E[eps_t | F_{t-1}] = 0, F_{t-1} = sigma(theta_s : s <= t-1)), has prediction coefficient c^k at integer lag k; the composition weights are 1 - c^(2k) and c^(2k).', 'MAIN', NULL, 359, 361, 'lean', 'B', 'Main text 359-361 states the remark; the appendix (technical-appendices-v3.tex 313-320) defines F_{t-1}, states the hypothesis and gives the argument.', 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C4.c', 'C4', 'remark', 'Stationary Gaussian OU satisfies the prediction rule', 'The stationary Gaussian Ornstein-Uhlenbeck process (APP eq:OU_process) has independent Gaussian innovations and Cov(theta_t, theta_s) = exp(-|t-s|/T) Sigma_S, hence satisfies C4.', 'APP', 'app:temporal-special-cases', 298, 322, 'lean', 'D', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C5', NULL, 'definition', 'Quadratic cost and completing the square', 'f(x,theta) = (1/2) x''Qx - b(theta)''x + c(theta), Q symmetric positive definite, x* = Q^{-1} b(theta); f(x,theta) - f(x*,theta) = (1/2)(x-x*)''Q(x-x*).', 'APP', 'eq:complete_square', 25, 68, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C5.b', 'C5', 'remark', 'Centering the affine model is without loss', 'With b affine, translating observations and actions by known means is a bijection of admissible rules that leaves x - x* unchanged; the centered target is K theta^c.', 'APP', NULL, 87, 97, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C6', NULL, 'definition', 'Architectures, admissible rules, regret, R_inf, eta_S', 'Neighborhood N_r(i); observation Z_i^(r,tau) = (theta_{j,t-tau} : j in N_r(i)); admissible rule u_i = g_i(Z_i) with finite second moment; R(A) = inf (1/2) E[(u-x*)''Q(u-x*)]; R_inf; eta_S(r) = R(A_{r,0})/R_inf.', 'MAIN', 'eq:architecture_regret', 204, 326, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C6.b', 'C6', 'remark', 'No-information loss formula', 'The best no-information action is zero in centered coordinates, with loss R_inf = (1/2) E[x*''Q x*] = (1/2) tr(K''QK Sigma_S).', 'MAIN', 'eq:Rinf_general', 311, 316, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C6.c', 'C6', 'remark', 'Omission share is in [0,1], nonincreasing, zero at the diameter', '0 <= eta_S(r) <= 1; larger fresh neighborhoods cannot increase it; at the diameter of a finite connected graph the fresh view is complete and omission is zero.', 'MAIN', 'eq:eta_S_definition', 317, 326, 'lean', 'B', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C7', NULL, 'theorem', 'Spatio-temporal composition', 'R(A_{r,tau}) = (1 - a^2) R_inf + a^2 R(A_{r,0}), a = exp(-tau/T), for every radius r and finite delay tau >= 0, over all admissible finite-second-moment rules and any deterministic Q > 0.', 'MAIN', 'thm:spatiotemporal_composition', 379, 443, 'lean', 'B', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C7.b', 'C7', 'remark', 'Normalized composition law', 'For R_inf > 0: 1 - R(A_{r,tau})/R_inf = exp(-2 tau/T) [1 - eta_S(r)].', 'MAIN', 'eq:regret_composition_normalized', 391, 396, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C8', NULL, 'corollary', 'Exact stale-global regret', 'Under the tracking model and the stationary transition, a complete snapshot of age tau gives R_glob(tau) = (1 - exp(-2 tau/T)) R_inf. (Its proof takes u = a K theta_{t-tau}, the optimal stale-global action; until arXiv v3 that was the separate remark C8.b.)', 'MAIN', 'thm:OU_stale_regret', 453, 467, 'lean', 'B', NULL, 1);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C8.c', 'C8', 'remark', 'Small-delay expansion and large-delay limit', 'R_glob is zero at zero delay, grows as 2 (tau/T) R_inf + o(tau/T), and tends to R_inf as delay grows.', 'MAIN', NULL, 468, 471, 'lean', 'A', NULL, 0);
INSERT INTO claims (id, parent, kind, title, statement, source, label, line_start, line_end, scope, tier, notes, headline) VALUES ('C9', NULL, 'remark', 'Unequal-rate formula for a complete old snapshot', 'Suppose a complete old snapshot reveals independent centered stationary OU modes with coherence times T_k. Write x* = sum_k x_k* with x_k* = K_k theta^(k), and for R_inf > 0 let w_k = E[(x_k*)^T Q x_k*] / E[(x*)^T Q x*] (the weights sum to one). Then 1 - R_glob(tau)/R_inf = sum_k w_k exp(-2 tau/T_k).', 'MAIN', NULL, 473, 495, 'lean', 'D', NULL, 0);
