INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C1.b/p1', 'C1.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C1.b/d1): orthogonality of the projection error is the definition of the projection; Pythagoras for the Q-inner product; then the regret formula of the projection lemma. The paper states both sentences without argument.', '2026-11-15T13:54:41');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C1.c/p1', 'C1.c', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C1.c/d1): a G_i-measurable policy is G''_i-measurable, so the policy space grows; an infimum over a larger set is no larger. The paper states Eq. (info_inclusion) without argument.', '2026-11-15T13:54:41');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C1/p1', 'C1', 1, NULL, 'in_paper', 1, 'Closed subspace plus Hilbert projection.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C10.b/p1', 'C10.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C10.b/d1): at eta_S(0) = 0, R_loc = 0 and rho* = 0, so the crossover theorem gives a strict local advantage at every positive delay; for 0 < eta_S(0) < 1 the threshold is positive; and the theorem''s two equivalences leave only ''stale-global strictly better'' below the threshold. The paper states both sentences without argument.', '2026-11-19T13:13:27');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C10/p1', 'C10', 1, NULL, 'in_paper', 1, 'Normalize both regrets, rearrange for eta_S(0) < 1, and treat the endpoint eta_S(0) = 1.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C11/p1', 'C11', 1, NULL, 'in_paper', 1, 'Direct mean-squared-error comparison.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C12/p1', 'C12', 1, NULL, 'in_paper', 1, 'Main text: centered decomposition and pointwise minimization.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C12/p2', 'C12', 2, NULL, 'in_paper', 0, 'Appendix: coupled normal equations, Sherman-Morrison trace, Pythagorean identity.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C13.b/p1', 'C13.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C13.b/d1): the ratio (q+gamma(n-1))/(q+gamma n) tends to 1, so the argument of the logarithm tends to 1+gamma/q and its reciprocal, the local share, to q/(q+gamma). The paper states both limits without argument.', '2026-11-15T13:35:42');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C13.c/p1', 'C13.c', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C13.c/d1): the values at gamma = 0; the argument A of the logarithm equals 1 + ((n-1)/q) gamma^2/(q+gamma n) and 1 - eta_S(0) = 1/A; gamma^2/(q+gamma n) is strictly increasing; hence A, the threshold and eta_S(0) are strictly increasing for n >= 2. The paper states the behaviour without argument.', '2026-11-15T13:35:42');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C13/p1', 'C13', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C13/d1): the aggregate-coupling proposition gives eta_S(0) and R_inf > 0 in closed form; 1 - eta_S(0) = q(q+gamma n)/((q+gamma)(q+gamma(n-1))) > 0, so eta_S(0) < 1 and the threshold of the crossover theorem is the boxed formula; the first case of that theorem then gives the equivalence. The paper says only that combining the proposition with the theorem gives the threshold.', '2026-11-19T13:44:09');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C14/p1', 'C14', 1, NULL, 'in_paper', 1, 'Direct substitution of the composition law, then the one-more-hop criterion and the loss decomposition read off it.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C15.b/p1', 'C15.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C15.b/d1): G = e^L with L = log(1 - eta_S) - 2 tau/T continuously differentiable on [0, D] and L'' the difference Delta of the two sides of the balance condition (one-sided at the endpoints); the sign of Delta on an open subinterval makes G strictly monotone on its closure; so Delta(0) <= 0 puts the strict maximum at 0, Delta(D) >= 0 at D, and otherwise the intermediate value theorem gives the one zero of Delta, with G increasing before it and decreasing after. The paper states the conclusion without argument.', '2026-11-19T13:49:06');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C15.c/p1', 'C15.c', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C15.c/d1): with tau = alpha tau_0 the difference of the two sides of the balance condition is Delta = (log(1 - eta_S))'' - 2 alpha tau_0''/T, which rises pointwise with T and falls with alpha because tau_0'' >= 0; by the single-crossing remark a maximizer r has Delta(r) >= 0 if r > 0 and Delta(r) <= 0 if r < D; a maximizer that moved the wrong way would contradict these two signs. The paper states the comparative statics without argument.', '2026-11-19T13:49:06');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C15/p1', 'C15', 1, NULL, 'in_paper', 1, 'First-order condition for log G.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C16/p1', 'C16', 1, NULL, 'in_paper', 1, 'Sign analysis of G''.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C17.b/p1', 'C17.b', 1, NULL, 'in_paper', 1, 'Innovation field is uncorrelated with, hence independent of, the whole old field; the conditional mean of the target scales by a; the gain is (q/2) times the variance of the conditional mean; stationarity equates the delayed and fresh variances.', '2026-11-14T13:50:21');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C18/p1', 'C18', 1, NULL, 'in_paper', 1, 'Appendix: variance ratio, tail split, spatial Markov property, shift invariance, covariance integrals.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C18/p2', 'C18', 2, NULL, 'in_paper', 0, 'Main-text sketch of C18/p1.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C19.b/p1', 'C19.b', 1, NULL, 'in_paper', 1, 'Two partial derivatives and an integral representation.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C19/p1', 'C19', 1, NULL, 'in_paper', 1, 'Cite the field calculation for R(r) = R_inf [1 - G(r)], take eta_0 from the lemma, and substitute into the exponential-omission proposition.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C2/p1', 'C2', 1, NULL, 'in_paper', 1, 'First-order condition with one-agent perturbations; converse by expansion.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C20/p1', 'C20', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C20/d1): under the positive-radius condition vT > 2 l_s the positive part in the closed form is inactive for every l_c > 0, so r* = (l_c/2) log(1 + (vT - 2 l_s)/(l_c + 2 l_s)); and x log(1 + c/(x + d)) tends to c. The limit is about the closed form of Eq. (canonical_optimal_radius); no step uses the theorem C19. The paper states the limit without argument.', '2026-11-19T13:44:10');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C3.b/p1', 'C3.b', 1, NULL, 'in_paper', 1, 'Zero target, zero rule.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C3/p1', 'C3', 1, NULL, 'in_paper', 1, 'Orthogonality by conditioning, then error expansion.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C4.b/p1', 'C4.b', 1, NULL, 'in_paper', 1, 'Iterate the recursion k times and use the tower property for each intervening innovation; the weights follow from the composition theorem with a = c^k. In the appendix since arXiv v3.', '2026-11-19T12:45:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C4.c/p1', 'C4.c', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C4.c/d1): for a jointly Gaussian process with mean zero and covariance exp(-|t-s|/T) Sigma_S, the innovation theta_t - a theta_{t-tau}, a = exp(-tau/T), is uncorrelated with every earlier state because exp(-(t-s)/T) = exp(-tau/T) exp(-(t-tau-s)/T); joint Gaussianity turns this into independence from the earlier states; independence and mean zero give the conditional-mean rule; and one-time laws agree because they are Gaussian with the same mean and covariance. The appendix states the result without argument. This is the argument of the paper''s proof for the continuum model (claim C17.b), for a process indexed by time and state coordinate.', '2026-11-19T14:40:30');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C5.b/p1', 'C5.b', 1, NULL, 'in_paper', 1, 'The centered desired action is K theta^c; translation by known means is a bijection of the admissible rules that leaves x - x* unchanged.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C5/p1', 'C5', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C5/d1): the first-order condition Q x* = b, the expansion of f around x*, and positive definiteness for uniqueness. The paper says only ''Completing the square gives''.', '2026-11-14T18:34:55');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C6.b/p1', 'C6.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C6.b/d1): the cost of a constant action is c''Qc plus R_inf because the state is centered; Q > 0 makes zero the best constant; the trace formula from x*''Qx* = tr(K''QK theta theta''). The paper states both without argument.', '2026-11-15T13:54:41');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C6.c/p1', 'C6.c', 1, NULL, 'in_paper', 1, 'The paper''s argument (extra observations can be ignored; complete view at the diameter) with one supplied step: the range of eta_S (C6.c/d1).', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C7.b/p1', 'C7.b', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C7.b/d1): divide the composition law by R_inf and substitute the definition of eta_S, then subtract from one. The paper says only ''equivalently'' and ''normalization is valid when R_inf > 0''.', '2026-11-15T13:35:42');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C7/p1', 'C7', 1, NULL, 'in_paper', 1, 'Innovation split plus rescaling of the joint rule; no projection theorem used.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C8.c/p1', 'C8.c', 1, NULL, 'supplement', 1, 'Supplement, written for the formalization (disposition C8.c/d1): by the stale-global corollary the regret is (1 - e^{-2 tau/T}) R_inf at every delay; the factor is zero at zero delay, equals 2 tau/T + o(tau/T) as tau decreases to 0 because the exponential has derivative 1 at 0, and tends to 1 as tau tends to infinity. The paper states the three facts without argument.', '2026-11-19T13:44:09');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C8/p1', 'C8', 1, NULL, 'superseded', 1, 'Complete fresh snapshot makes x* feasible, so the fresh term vanishes.', '2026-11-13T13:26:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C8/p2', 'C8', 2, 'C8/p1', 'in_paper', 1, 'Direct proof from the innovation split (arXiv v3): with the complete old state take u = a K theta_{t-tau}; the first term of Eq. innovation_split is zero, its minimum, and the regret is half the innovation energy of Eq. innovation_energy. Uses two steps of the proof of C7, not the theorem, so it does not need a radius that reaches every agent.', '2026-11-19T12:45:00');
INSERT INTO proofs (id, claim_id, version, parent, status, is_primary, summary, created) VALUES ('C9/p1', 'C9', 1, NULL, 'in_paper', 1, 'Three sentences added in arXiv v3: independence and centering remove the cross-mode terms; the old snapshot predicts mode k with factor exp(-tau/T_k), so its captured gain scales by exp(-2 tau/T_k); sum over modes.', '2026-11-19T12:45:00');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C1.b/p1/s1', 'C1.b/p1', 1, 'The projection error is Q-orthogonal to the policy space', '$u^\star=\Pi_{\mathcal S(\mathcal A)}x^\star$ is the orthogonal projection for $\langle\cdot,\cdot\rangle_Q$ (Eq. \eqref{eq:optimal_projection}), so by definition $u^\star\in\mathcal S(\mathcal A)$ and the error $x^\star-u^\star$ is $Q$-orthogonal to every member of $\mathcal S(\mathcal A)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C1.b/p1/s2', 'C1.b/p1', 2, 'Pythagoras', 'Taking $h=u^\star$ in step 1 gives $\langle u^\star,x^\star-u^\star\rangle_Q=0$. Expanding $\|x^\star\|_Q^2=\|u^\star+(x^\star-u^\star)\|_Q^2$ then gives $\|x^\star\|_Q^2=\|u^\star\|_Q^2+\|x^\star-u^\star\|_Q^2$ (Pythagoras).', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C1.b/p1/s3', 'C1.b/p1', 3, 'Substitute into the regret formula', 'By Lemma \ref{lem:radner_projection}, applied with $b=Qx^\star$ and $c=0$, $R(\mathcal A)=\tfrac12\|x^\star-u^\star\|_Q^2$ (Eq. \eqref{eq:projection_regret}). With step 2, $2R(\mathcal A)=\|x^\star\|_Q^2-\|u^\star\|_Q^2$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C1.c/p1/s1', 'C1.c/p1', 1, 'The policy space grows with the information', 'If $u\in\mathcal S(\mathcal A)$ then each $u_i$ is $\mathcal G_i$-measurable, hence $\mathcal G_i''$-measurable because $\mathcal G_i\subseteq\mathcal G_i''$; so $\mathcal S(\mathcal A)\subseteq\mathcal S(\mathcal A'')$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C1.c/p1/s2', 'C1.c/p1', 2, 'An infimum over a larger set is no larger', '$R(\mathcal A'')$ is the infimum of the same expected excess cost over the larger set $\mathcal S(\mathcal A'')$, and that cost is bounded below by zero because $Q\succ0$; so $R(\mathcal A'')\le R(\mathcal A)$.', NULL, NULL, NULL, 'supplied');
