INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C10.b/p1/s1', 'C10.b/p1', 1, 'eta_S(0) = 0: zero local regret, zero threshold, local better at every positive delay', 'If $\eta_S(0)=0$, then $R_{\rm loc}=\eta_S(0)R_\infty=0$, and $\rho^\star=\tfrac12\log 1=0$. By Theorem~\ref{thm:local_global_crossover}, fresh-local information is strictly better exactly when $\tau/T>0$, that is, since $T>0$, at every positive delay.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C10.b/p1/s2', 'C10.b/p1', 2, 'The threshold is positive for 0 < eta_S(0) < 1', 'If $0<\eta_S(0)<1$, then $0<1-\eta_S(0)<1$, so $1/(1-\eta_S(0))>1$ and $\rho^\star=\tfrac12\log\frac{1}{1-\eta_S(0)}>0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C10.b/p1/s3', 'C10.b/p1', 3, 'Below, at and above the threshold', 'Let $\eta_S(0)<1$. By Theorem~\ref{thm:local_global_crossover}, fresh-local information is strictly better exactly when $\tau/T>\rho^\star$, and the two regrets are equal exactly when $\tau/T=\rho^\star$. If $\tau/T<\rho^\star$, neither holds, so stale-global information is strictly better. Hence the two losses are equal at one delay only, $\tau=\rho^\star T$, with stale-global strictly better before it and fresh-local strictly better after it.', NULL, NULL, NULL, 'supplied');
