INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C12/p2/s5', 'C12/p2', 5, 'Means vanish, so u_i = theta_i/(q+gamma)', 'Taking expectations yields
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C12/p2/s6', 'C12/p2', 6, 'No-information regret from tr(Q^{-1})', '\emph{No-information regret.} Here $B=I$ and $\Sigma_S=\sigma^2I$, so by \eqref{eq:Rinf_general}, $R_\infty=\tfrac{\sigma^2}2\operatorname{tr}(Q^{-1})$. From the Sherman--Morrison formula above,
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C12/p2/s7', 'C12/p2', 7, 'Local regret from the Pythagorean identity', '\emph{Local regret.} By the Pythagorean form of Lemma~\ref{lem:radner_projection} (the orthogonality identity in Appendix~\ref{app:technical-projection}, with both $x^\star$ and $u^{\rm loc}$ mean zero), $2R_{\rm loc}=\|x^\star\|_Q^2-\|u^{\rm loc}\|_Q^2=2R_\infty-\|u^{\rm loc}\|_Q^2$. Since $u^{\rm loc}=\theta/(q+\gamma)$ and $\operatorname{tr}(Q)=n(q+\gamma)$,
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C12/p2/s8', 'C12/p2', 8, 'Share is the ratio', '\emph{Share.} Dividing \eqref{eq:aggregate_Rloc} by \eqref{eq:aggregate_Rinf}, the factors $n\sigma^2/2$ and $q(q+\gamma n)$ cancel, leaving \eqref{eq:aggregate_eta}.', 'APP', 406, 406, 'paper');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.b/p1/s1', 'C13.b/p1', 1, 'The ratio tends to one', 'For fixed $q>0$ and $\gamma\ge0$, $\dfrac{q+\gamma(n-1)}{q+\gamma n}=1-\dfrac{\gamma}{q+\gamma n}\to1$ as $n\to\infty$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.b/p1/s2', 'C13.b/p1', 2, 'Limit of the threshold', 'Hence the argument of the logarithm in Eq. \eqref{eq:aggregate_rho_star}, $\dfrac{q+\gamma}{q}\cdot\dfrac{q+\gamma(n-1)}{q+\gamma n}$, tends to $(q+\gamma)/q=1+\gamma/q>0$, and continuity of the logarithm there gives Eq. \eqref{eq:large_n_threshold}.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.b/p1/s3', 'C13.b/p1', 3, 'Limit of the local share', 'By Eq. \eqref{eq:aggregate_eta}, $1-\eta_S(0)=\dfrac{q}{q+\gamma}\cdot\dfrac{q+\gamma n}{q+\gamma(n-1)}$ for $n\ge1$, the reciprocal of that argument, so by step 1 it tends to $q/(q+\gamma)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.c/p1/s1', 'C13.c/p1', 1, 'Values at gamma = 0', 'At $\gamma=0$ the numerator of Eq. \eqref{eq:aggregate_eta} is zero, so $\eta_S(0)=0$; and the argument of the logarithm in Eq. \eqref{eq:aggregate_rho_star} is $q\cdot q/(q\cdot q)=1$, so $\rho^\star(0,n)=0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.c/p1/s2', 'C13.c/p1', 2, 'The argument of the logarithm', 'Write $A(\gamma)=\dfrac{(q+\gamma)(q+\gamma(n-1))}{q(q+\gamma n)}$ for the argument of the logarithm in Eq. \eqref{eq:aggregate_rho_star}. Since $(q+\gamma)(q+\gamma(n-1))=q(q+\gamma n)+\gamma^2(n-1)$, $A(\gamma)=1+\dfrac{n-1}{q}\cdot\dfrac{\gamma^2}{q+\gamma n}$; and by Eq. \eqref{eq:aggregate_eta}, $1-\eta_S(0)=1/A(\gamma)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.c/p1/s3', 'C13.c/p1', 3, 'gamma^2/(q+gamma n) is strictly increasing', 'The function $\gamma\mapsto\gamma^2/(q+\gamma n)$ is strictly increasing on $\gamma\ge0$: for $0\le\gamma_1<\gamma_2$, $\gamma_2^2(q+\gamma_1n)-\gamma_1^2(q+\gamma_2n)=(\gamma_2-\gamma_1)[q(\gamma_1+\gamma_2)+n\gamma_1\gamma_2]>0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.c/p1/s4', 'C13.c/p1', 4, 'A is strictly increasing and at least one', 'Since $n\ge2$, the coefficient $(n-1)/q$ is positive, so by steps 2 and 3 $A$ is strictly increasing on $\gamma\ge0$, and $A(\gamma)\ge1$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13.c/p1/s5', 'C13.c/p1', 5, 'The threshold and eta_S(0) are strictly increasing', 'Consequently $\rho^\star(\gamma,n)=\tfrac12\log A(\gamma)$ is strictly increasing on $\gamma\ge0$, because the logarithm is strictly increasing on positive numbers; and $\eta_S(0)=1-1/A(\gamma)$ (step 2) is strictly increasing, because $A$ is positive and strictly increasing.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13/p1/s1', 'C13/p1', 1, 'eta_S(0) and R_inf > 0 from the proposition', 'By Proposition~\ref{prop:aggregate_local}, $\eta_S(0)$ is the right side of Eq.~\eqref{eq:aggregate_eta}, and $R_\infty=\dfrac{n\sigma^2(q+\gamma(n-1))}{2q(q+\gamma n)}$ (Eq.~\eqref{eq:aggregate_Rinf}), which is positive because $n\ge2$, $\sigma>0$, $q>0$ and $\gamma\ge0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13/p1/s2', 'C13/p1', 2, 'eta_S(0) < 1 and the threshold in closed form', 'Write $\eta$ for the right side of Eq.~\eqref{eq:aggregate_eta}. Since $(q+\gamma)(q+\gamma(n-1))-\gamma^2(n-1)=q(q+\gamma n)$, $1-\eta=\dfrac{q(q+\gamma n)}{(q+\gamma)(q+\gamma(n-1))}$, which is positive. So $\eta<1$, and $\tfrac12\log\dfrac{1}{1-\eta}$ is the right side of Eq.~\eqref{eq:aggregate_rho_star}.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C13/p1/s3', 'C13/p1', 3, 'The crossover theorem applies', 'By steps 1 and 2, $R_\infty>0$, $\eta_S(0)<1$ and $\rho^\star=\tfrac12\log\frac{1}{1-\eta_S(0)}=\rho^\star(\gamma,n)$. So the first case of Theorem~\ref{thm:local_global_crossover} applies: $R_{\rm loc}<R_{\rm glob}(\tau)$ exactly when $\tau/T>\rho^\star=\rho^\star(\gamma,n)$, which is Eq.~\eqref{eq:aggregate_crossover}.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C14/p1/s1', 'C14/p1', 1, 'R(r) = R_inf [1 - G(r)] from C7', 'Writing $R(r)=R(\mathcal A_{r,\tau(r)})$,
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C14/p1/s2', 'C14/p1', 2, 'One more hop improves performance exactly when G(r+1) > G(r)', 'On a finite graph, one more hop improves performance exactly when
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C14/p1/s3', 'C14/p1', 3, 'Loss separates into the delay component and the remaining scope component', 'The loss separates into the two components plotted in
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.b/p1/s1', 'C15.b/p1', 1, 'G = e^L, and L is C^1 with derivative Delta', 'Let $L(r)=\log[1-\eta_S(r)]-2\tau(r)/T$ on $[0,D]$. Since $\eta_S<1$, $G(r)=e^{L(r)}$ by Eq.~\eqref{eq:snapshot_gain}. Since $\eta_S$ and $\tau$ are continuously differentiable on $[0,D]$ and $1-\eta_S>0$, $L$ is continuously differentiable on $[0,D]$, and its derivative (one-sided at the two endpoints) is the difference $\Delta(r)$ between the left and right sides of Eq.~\eqref{eq:marginal_balance_condition}. In particular $\Delta$ is continuous on $[0,D]$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.b/p1/s2', 'C15.b/p1', 2, 'The sign of Delta on (a, b) makes G strictly monotone on [a, b]', 'Let $[a,b]\subseteq[0,D]$. If $\Delta>0$ on $(a,b)$, then by the mean value theorem $L$ is strictly increasing on $[a,b]$, and so is $G=e^{L}$. If $\Delta<0$ on $(a,b)$, both are strictly decreasing on $[a,b]$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.b/p1/s3', 'C15.b/p1', 3, 'Delta(0) <= 0: the optimum is radius zero', 'Suppose $\Delta$ is strictly decreasing on $[0,D]$ and $\Delta(0)\le0$. Then $\Delta(r)<\Delta(0)\le0$ for $0<r\le D$, so by step 2 $G$ is strictly decreasing on $[0,D]$: $G(r)<G(0)$ for every $r\in(0,D]$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.b/p1/s4', 'C15.b/p1', 4, 'Delta(D) >= 0: the optimum is radius D', 'Suppose $\Delta$ is strictly decreasing on $[0,D]$ and $\Delta(D)\ge0$. Then $\Delta(r)>\Delta(D)\ge0$ for $0\le r<D$, so by step 2 $G$ is strictly increasing on $[0,D]$: $G(r)<G(D)$ for every $r\in[0,D)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.b/p1/s5', 'C15.b/p1', 5, 'Otherwise: the unique interior crossing', 'Suppose $\Delta$ is strictly decreasing on $[0,D]$, $\Delta(0)>0$ and $\Delta(D)<0$. By step 1 $\Delta$ is continuous, so the intermediate value theorem gives $r_0\in(0,D)$ with $\Delta(r_0)=0$; it is the only zero because $\Delta$ is strictly decreasing. Then $\Delta>0$ on $[0,r_0)$ and $\Delta<0$ on $(r_0,D]$, so by step 2 $G$ is strictly increasing on $[0,r_0]$ and strictly decreasing on $[r_0,D]$: $G(r)<G(r_0)$ for every $r\ne r_0$ in $[0,D]$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.c/p1/s1', 'C15.c/p1', 1, 'The scaled delay satisfies the hypotheses; formula for Delta', 'Let $\alpha>0$ and $\tau=\alpha\tau_0$. Then $\tau$ is continuously differentiable on $[0,D]$ with $\tau''=\alpha\tau_0''\ge0$, so the pair $(\eta_S,\tau)$ satisfies the hypotheses of Proposition~\ref{thm:marginal_balance}; and the difference between the left and right sides of Eq.~\eqref{eq:marginal_balance_condition} is $\Delta_{\alpha,T}(r)=\frac{d}{dr}\log[1-\eta_S(r)]-2\alpha\tau_0''(r)/T$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.c/p1/s2', 'C15.c/p1', 2, 'Delta rises with T and falls with alpha', 'Since $\tau_0''\ge0$ on $[0,D]$, the formula of step 1 shows: if $0<T\le T''$, then $\Delta_{\alpha,T}\le\Delta_{\alpha,T''}$ on $[0,D]$; and if $0<\alpha\le\alpha''$ and $T>0$, then $\Delta_{\alpha'',T}\le\Delta_{\alpha,T}$ on $[0,D]$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.c/p1/s3', 'C15.c/p1', 3, 'Sign of Delta at a maximizer', 'Let $(\eta_S,\tau)$ satisfy the hypotheses of Proposition~\ref{thm:marginal_balance}, let its difference $\Delta$ be strictly decreasing on $[0,D]$, and let $r$ maximize $G$ on $[0,D]$. By the single-crossing statement, the radius it names is strictly better than every other radius, so $r$ is that radius: $0$ if $\Delta(0)\le0$, $D$ if $\Delta(D)\ge0$, and otherwise the zero of $\Delta$ in $(0,D)$. Hence if $r>0$ then $\Delta(r)\ge0$ (the first case is excluded, and $\Delta(r)$ is $\Delta(D)\ge0$ or $0$), and if $r<D$ then $\Delta(r)\le0$ (the second case is excluded, and $\Delta(r)$ is $\Delta(0)\le0$ or $0$).', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.c/p1/s4', 'C15.c/p1', 4, 'Larger T: the optimum moves weakly outward', 'Larger $T$. Let $\alpha>0$ and $0<T\le T''$, with $\Delta_{\alpha,T}$ and $\Delta_{\alpha,T''}$ strictly decreasing on $[0,D]$, and let $r$ and $r''$ maximize $G$ for $T$ and for $T''$. Suppose $r''<r$. Then $r''<D$, so $\Delta_{\alpha,T''}(r'')\le0$ by step 3; and $r>0$, so $\Delta_{\alpha,T}(r)\ge0$ by step 3. Since $\Delta_{\alpha,T}$ is strictly decreasing, $\Delta_{\alpha,T}(r'')>\Delta_{\alpha,T}(r)\ge0$, and by step 2 $\Delta_{\alpha,T''}(r'')\ge\Delta_{\alpha,T}(r'')>0$, a contradiction. Hence $r\le r''$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15.c/p1/s5', 'C15.c/p1', 5, 'Larger latency scale: the optimum moves weakly inward', 'Larger latency scale. Let $T>0$ and $0<\alpha\le\alpha''$, with $\Delta_{\alpha,T}$ and $\Delta_{\alpha'',T}$ strictly decreasing on $[0,D]$, and let $r$ and $r''$ maximize $G$ for $\alpha$ and for $\alpha''$. Suppose $r<r''$. Then $r<D$, so $\Delta_{\alpha,T}(r)\le0$ by step 3; and $r''>0$, so $\Delta_{\alpha'',T}(r'')\ge0$ by step 3. Since $\Delta_{\alpha'',T}$ is strictly decreasing, $\Delta_{\alpha'',T}(r)>\Delta_{\alpha'',T}(r'')\ge0$, and by step 2 $\Delta_{\alpha,T}(r)\ge\Delta_{\alpha'',T}(r)>0$, a contradiction. Hence $r''\le r$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15/p1/s1', 'C15/p1', 1, 'Maximizing G is maximizing log G', 'Since $G(r)>0$, maximizing $G$ is equivalent to maximizing $\log G$.', 'MAIN', 750, 750, 'paper');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C15/p1/s2', 'C15/p1', 2, 'Interior optimum has (log G)'' = 0', 'At an interior optimum, $(\log G)''=0$;', 'MAIN', 751, 751, 'paper');
