INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s1', 'C18/p1', 1, 'Step 0: omission is a conditional-variance ratio', 'By spatial stationarity, take $z=0$ and suppress the time argument. Write $\beta_c\triangleq1/\ell_c$ and $\beta_s\triangleq1/\ell_s$ for the inverse lengths, so $w(u)=\tfrac{\beta_c}{2}e^{-\beta_c|u|}$ and $\operatorname{Cov}(\theta(u),\theta(u''))=\sigma^2e^{-\beta_s|u-u''|}$.
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s2', 'C18/p1', 2, 'Step 1: split target into observed middle and two tails', '\textbf{Step 1 (split into observed middle and two tails).} Write $x^\star(0)=M_r+T_r^++T_r^-$, where
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s3', 'C18/p1', 3, 'Step 2: rewrite the right tail with weight exp(-beta_c r)', '\textbf{Step 2 (rewrite the right tail).} Substituting $u=r+s$,
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s3b', 'C18/p1', 4, 'Residual fields: the proof of the spatial Markov property', 'For $s\ge0$ write $\theta(r+s)=e^{-\beta_s s}\theta(r)+\varepsilon^+(s)$ and $\theta(-r-s)=e^{-\beta_s s}\theta(-r)+\varepsilon^-(s)$. By the exponential covariance, each $\varepsilon^+(s)$ is uncorrelated with every $\theta(u)$, $u\le r$, and each $\varepsilon^-(s)$ with every $\theta(u)$, $u\ge -r$. The families $(\theta(u))_{|u|\le r}$, $(\varepsilon^+(s))_{s\ge0}$ and $(\varepsilon^-(s))_{s\ge0}$ are jointly Gaussian and pairwise uncorrelated, hence independent. Integrating against $e^{-\beta_c s}$ gives $Y_r=\theta(r)/(\beta_c+\beta_s)+E^+$ and, for the left tail, $Y^-_r=\theta(-r)/(\beta_c+\beta_s)+E^-$, where $E^\pm=\int_0^\infty e^{-\beta_c s}\varepsilon^\pm(s)\,ds$ have mean zero, $E^+$ and $E^-$ are independent, and the pair is independent of the observation $\mathcal O_r$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s4', 'C18/p1', 5, 'Step 3: spatial Markov property', '\textbf{Step 3 (spatial Markov property).} By the exponential-covariance model in Section~\ref{subsec:canonical_line_model}, the field is Markov in $z$. Given the observed segment $[-r,r]$, the right tail $\{\theta(u):u>r\}$ and the left tail $\{\theta(u):u<-r\}$ are conditionally independent, and each depends on the segment only through its adjacent endpoint $\theta(r)$ or $\theta(-r)$. Therefore
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s5', 'C18/p1', 6, 'Step 4: tail variance does not depend on r; eta_S(r) = eta_S(0) exp(-2r/l_c)', '\textbf{Step 4 (the tail variance does not depend on $r$).} Define $C\triangleq\operatorname{Var}(Y_0\mid\theta(0))$. Shifting the field by $r$ does not change its law, so $\operatorname{Var}(Y_r\mid\theta(r))=C$ for every $r$. By reflection symmetry (the covariance depends only on $|u-u''|$), the left tail gives the same value. Hence
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s6', 'C18/p1', 7, 'Step 5a: eta_S(0) = 1 - Corr^2', '\textbf{Step 5 (the constant $\eta_S(0)$).} Conditioning on the single Gaussian variable $\theta(0)$ gives $\operatorname{Var}(x^\star(0)\mid\theta(0))=\operatorname{Var}(x^\star(0))\big(1-\operatorname{Corr}(x^\star(0),\theta(0))^2\big)$ (the Gaussian conditional covariance is independent of the observed values), so $\eta_S(0)=1-\operatorname{Corr}^2$. Two moments are needed.', 'APP', 454, 454, 'paper');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s7', 'C18/p1', 8, 'Step 5b: covariance of the target with the local value', '\emph{Covariance with the local value:}
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s8', 'C18/p1', 9, 'Step 5c: variance of the target', '\emph{Variance of the target:} $\operatorname{Var}(x^\star(0))=\frac{\sigma^2\beta_c^2}{4}\,I$, where $I\triangleq\iint e^{-\beta_c(|u|+|v|)-\beta_s|u-v|}\,du\,dv$.
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p1/s9', 'C18/p1', 10, 'Step 5d: combine to eta_S(0) = l_c/(l_c + 2 l_s)', '\emph{Combine.} With $\operatorname{Var}(\theta(0))=\sigma^2$,
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C18/p2/s1', 'C18/p2', 1, 'Sketch: self-similarity of the tails', 'By stationarity, set $z=0$ and suppress time. The observed middle of the
