INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C2/p1/s4', 'C2/p1', 4, 'Positive definiteness gives sufficiency and uniqueness', 'Positive definiteness makes the remaining term positive for any nonzero
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C20/p1/s1', 'C20/p1', 1, 'Under vT > 2 l_s the positive part is inactive for every l_c', 'Let $vT>2\ell_s$, the positive-radius condition Eq.~\eqref{eq:positive_radius_condition}, which does not involve $\ell_c$. Then for every $\ell_c>0$, $\dfrac{\ell_c+vT}{\ell_c+2\ell_s}=1+\dfrac{vT-2\ell_s}{\ell_c+2\ell_s}>1$, so the logarithm in Eq.~\eqref{eq:canonical_optimal_radius} is positive, the positive part is inactive, and $r^\star=\dfrac{\ell_c}{2}\log\!\Big(1+\dfrac{vT-2\ell_s}{\ell_c+2\ell_s}\Big)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C20/p1/s2', 'C20/p1', 2, 'x log(1 + c/(x + d)) tends to c', 'For constants $c$ and $d$: $y\log(1+c/y)\to c$ as $y\to\infty$, because $\log(1+u)/u\to1$ as $u\to0$; and $\log(1+c/y)\to0$. With $y=x+d$, $x\log\!\big(1+\tfrac{c}{x+d}\big)=y\log(1+c/y)-d\log(1+c/y)\to c$ as $x\to\infty$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C20/p1/s3', 'C20/p1', 3, 'Limit of the radius', 'By step 1, for every $\ell_c>0$, $r^\star=\tfrac12\,\ell_c\log\!\Big(1+\dfrac{vT-2\ell_s}{\ell_c+2\ell_s}\Big)$. By step 2 with $c=vT-2\ell_s$ and $d=2\ell_s$, $r^\star\to(vT-2\ell_s)/2$ as $\ell_c\to\infty$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C3.b/p1/s1', 'C3.b/p1', 1, 'R_inf = 0 and Q > 0 force x* = 0 a.s.', 'In centered coordinates, $R_\infty=0$ and $Q\succ0$
