INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C3/p1/s2', 'C3/p1', 2, 'Error expansion makes m the unique optimum', 'The error expansion then proves that
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.b/p1/s1', 'C4.b/p1', 1, 'Iterate the recursion; each intervening innovation has conditional mean zero (tower property)', 'Iterating the recursion
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.b/p1/s2', 'C4.b/p1', 2, 'Composition weights 1 - c^(2k) and c^(2k)', 'The composition weights are $1-c^{2k}$ and $c^{2k}$.', 'APP', 320, 320, 'paper');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.c/p1/s1', 'C4.c/p1', 1, 'The innovation is uncorrelated with every earlier state', 'Let $\tau\ge0$, $a=e^{-\tau/T}$ and $s\le t-\tau$. By Eq.~\eqref{eq:separable_space_time_covariance}, for all coordinates $k,l$, $\mathbb E[(\theta_{t,k}-a\theta_{t-\tau,k})\theta_{s,l}]=e^{-(t-s)/T}(\Sigma_S)_{kl}-e^{-\tau/T}e^{-(t-\tau-s)/T}(\Sigma_S)_{kl}=0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.c/p1/s2', 'C4.c/p1', 2, 'The innovation is Gaussian and independent of the earlier states', 'Each coordinate of the innovation $\theta_t-a\theta_{t-\tau}$ is a linear combination of two values of the process, so the innovation is Gaussian and it is jointly Gaussian with the earlier states $(\theta_s:s\le t-\tau)$. The process has mean zero, so by step 1 every covariance between a coordinate of the innovation and a coordinate of an earlier state vanishes. Jointly Gaussian and uncorrelated families are independent: the innovation is independent of $(\theta_s:s\le t-\tau)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.c/p1/s3', 'C4.c/p1', 3, 'The conditional-mean rule', 'The old state $\theta_{t-\tau}$ is one of the earlier states, so by step 2 the innovation is independent of it. The innovation is integrable with mean zero, hence $\mathbb E[\theta_t-a\theta_{t-\tau}\mid\theta_{t-\tau}]=0$, which is Eq.~\eqref{eq:state_innovation_decomposition} with $\varepsilon_{t,\tau}=\theta_t-a\theta_{t-\tau}$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C4.c/p1/s4', 'C4.c/p1', 4, 'Stationary with finite second moments', 'Every $\theta_t$ is a Gaussian vector, so it has finite second moments. For any two epochs $s,t$ the vectors $\theta_s$ and $\theta_t$ are Gaussian with the same mean, zero, and the same covariance, $\Sigma_S$, by Eq.~\eqref{eq:separable_space_time_covariance} at equal times. A Gaussian law is determined by its mean and covariance, so $\theta_s$ and $\theta_t$ have the same law.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C5.b/p1/s1', 'C5.b/p1', 1, 'Centered desired action is K theta^c', 'Then the centered desired action is
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C5.b/p1/s2', 'C5.b/p1', 2, 'Translating by known means is a bijection leaving x - x* unchanged', 'Translating each observation and
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C5/p1/s1', 'C5/p1', 1, 'First-order condition Q x* = b', 'Since $x^\star=Q^{-1}b$ and $Q$ is invertible, $Qx^\star=b$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C5/p1/s2', 'C5/p1', 2, 'Expand the cost around x*', 'Write $x=x^\star+h$. Because $Q$ is symmetric, $f(x^\star+h)=f(x^\star)+h^\top(Qx^\star-b)+\tfrac12h^\top Qh$, and the middle term vanishes by step 1. With $h=x-x^\star$ this is Eq. \eqref{eq:complete_square}.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C5/p1/s3', 'C5/p1', 3, 'x* is the unique minimizer', 'If $x\ne x^\star$ then $(x-x^\star)^\top Q(x-x^\star)>0$ because $Q$ is positive definite, so $f(x)>f(x^\star)$ by step 2.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.b/p1/s1', 'C6.b/p1', 1, 'Cost of a constant action', 'For a constant action $c$, $\mathbb E[(c-x^\star)^\top Q(c-x^\star)]=c^\top Qc-2c^\top Q\,\mathbb E[x^\star]+\mathbb E[x^{\star\top}Qx^\star]=c^\top Qc+\mathbb E[x^{\star\top}Qx^\star]$, since $\mathbb E[x^\star]=K\,\mathbb E[\theta]=0$ in centered coordinates.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.b/p1/s2', 'C6.b/p1', 2, 'Zero is the best constant action', 'Since $Q\succ0$, $c^\top Qc\ge0$, with equality at $c=0$. So no constant action costs less than $R_\infty=\tfrac12\mathbb E[x^{\star\top}Qx^\star]$, and the zero action costs exactly $R_\infty$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.b/p1/s3', 'C6.b/p1', 3, 'Trace formula', '$x^{\star\top}Qx^\star=\theta^\top K^\top QK\theta=\operatorname{tr}(K^\top QK\,\theta\theta^\top)$. Taking expectations, with $\mathbb E[\theta\theta^\top]=\Sigma_S$ for the centered state, $R_\infty=\tfrac12\operatorname{tr}(K^\top QK\Sigma_S)$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.c/p1/s0a', 'C6.c/p1', 1, 'The range of eta_S', 'Regret is nonnegative because $Q\succ0$. It is at most $R_\infty$ because the zero rule is admissible at every radius and its expected excess cost is $\tfrac12\mathbb E[x^{\star\top}Qx^\star]=R_\infty$. Dividing by $R_\infty>0$ gives $0\le\eta_S(r)\le1$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.c/p1/s1', 'C6.c/p1', 2, 'Larger fresh neighborhoods cannot increase eta_S', 'Larger fresh neighborhoods cannot increase it, since their
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C6.c/p1/s2', 'C6.c/p1', 3, 'At the diameter the fresh view is complete and omission is zero', 'at the diameter of a finite connected
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7.b/p1/s1', 'C7.b/p1', 1, 'Divide the law by R_inf', 'Divide Eq. \eqref{eq:regret_composition_unnormalized} by $R_\infty>0$: $R(\mathcal A_{r,\tau})/R_\infty=(1-a^2)+a^2R(\mathcal A_{r,0})/R_\infty$, and $R(\mathcal A_{r,0})/R_\infty=\eta_S(r)$ by Eq. \eqref{eq:eta_S_definition}.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7.b/p1/s2', 'C7.b/p1', 2, 'Subtract from one', 'Subtract from one: $1-R(\mathcal A_{r,\tau})/R_\infty=a^2[1-\eta_S(r)]$, and $a^2=e^{-2\tau/T}$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7/p1/s1', 'C7/p1', 1, 'Apply K to the transition', 'Applying $K$ to the transition gives
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7/p1/s2', 'C7/p1', 2, 'Rules are functions of the old state; cross term vanishes', 'Every joint admissible rule $u$ is a function of the complete old state,
