INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7/p1/s6', 'C7/p1', 6, 'Fresh problem at the old epoch equals R(A_{r,0}) by stationarity', 'The last equality uses stationarity and the same observation pattern at
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C7/p1/s7', 'C7/p1', 7, 'Combine and divide by two; normalize when R_inf > 0', 'Combining the two errors and dividing by two proves the law;
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C8.c/p1/s1', 'C8.c/p1', 1, 'Closed form at every delay; zero at zero delay', 'By Corollary~\ref{thm:OU_stale_regret}, $R_{\rm glob}(\tau)=(1-e^{-2\tau/T})R_\infty$ for every delay $\tau\ge0$. At $\tau=0$ the factor is $1-e^{0}=0$, so the regret is zero at zero delay.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C8.c/p1/s2', 'C8.c/p1', 2, 'Small-delay expansion', 'The exponential has derivative $1$ at $0$, so $e^{x}=1+x+o(x)$ as $x\to0$. With $x=-2\tau/T$, which tends to $0$ as $\tau\downarrow0$, this gives $1-e^{-2\tau/T}=2\tau/T+o(\tau/T)$. Multiplying by the constant $R_\infty$ and using step 1, $R_{\rm glob}(\tau)=2(\tau/T)R_\infty+o(\tau/T)$ as $\tau\downarrow0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C8.c/p1/s3', 'C8.c/p1', 3, 'Large-delay limit', 'Since $T>0$, $-2\tau/T\to-\infty$ as $\tau\to\infty$, so $e^{-2\tau/T}\to0$ and, by step 1, $R_{\rm glob}(\tau)\to(1-0)R_\infty=R_\infty$.', NULL, NULL, NULL, 'supplied');
