INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C8/p2/s1', 'C8/p2', 1, 'With the complete old state the action a K theta_{t-tau} is admissible', 'With the complete old state, each agent can take its component of
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C8/p2/s2', 'C8/p2', 2, 'First term of the split is zero, its minimum; regret is half the innovation energy', 'This makes the first term in
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C9/p1/s0', 'C9/p1', 1, 'The modes add up to the state and to the desired action', 'Since $\sum_k P_k=I$, the state is the sum of its modes, $\theta_s=\sum_k P_k\theta_s$ at every epoch $s$, and applying $K$ gives $x_s^\star=\sum_k x_{k,s}^\star$ with $x_{k,s}^\star=KP_k\theta_s$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C9/p1/s1', 'C9/p1', 2, 'Cross-mode terms vanish, so the weights sum to one', 'Independence and centering make the cross-mode terms vanish, so $\sum_k w_k=1$.', 'MAIN', 483, 483, 'paper');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C9/p1/s2', 'C9/p1', 4, 'Mode k is predicted with factor exp(-tau/T_k); its captured gain scales by exp(-2 tau/T_k)', 'The complete old snapshot predicts mode $k$''s contribution as
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C9/p1/s2a', 'C9/p1', 3, 'Each mode''s innovation has conditional mean zero given the whole snapshot', 'Fix a mode $k$ and write $a_k=e^{-\tau/T_k}$. By the appendix''s Ornstein--Uhlenbeck remark (claim C4.c) applied to the mode, $\mathbb E[P_k\theta_t-a_kP_k\theta_{t-\tau}\mid P_k\theta_{t-\tau}]=0$. The innovation $P_k\theta_t-a_kP_k\theta_{t-\tau}$ and the old value $P_k\theta_{t-\tau}$ are functions of mode $k$''s path; the old values of the other modes are functions of the other paths, which are independent of it. So conditioning on them in addition changes nothing: the conditional mean of the innovation given all the modes'' old values is zero. The snapshot $\theta_{t-\tau}=\sum_{k''}P_{k''}\theta_{t-\tau}$ is a function of these old values, so by the tower property $\mathbb E[P_k\theta_t-a_kP_k\theta_{t-\tau}\mid\theta_{t-\tau}]=0$.', NULL, NULL, NULL, 'supplied');
INSERT INTO steps (id, proof_id, ordinal, title, tex, source, line_start, line_end, origin) VALUES ('C9/p1/s2b', 'C9/p1', 5, 'The regret of the complete old snapshot is R_inf minus half the captured gain', 'Let $\hat x=\sum_k a_kx_{k,t-\tau}^\star$. By steps 0 and 2, $\hat x=\mathbb E[x_t^\star\mid\theta_{t-\tau}]$. Every admissible rule $u$ of the complete old snapshot is a function of $\theta_{t-\tau}$, and so is $\hat x$, so the cross term $\mathbb E[(\hat x-u)^\top Q(x_t^\star-\hat x)]$ vanishes and $\mathbb E[(u-x_t^\star)^\top Q(u-x_t^\star)]=\mathbb E[(\hat x-u)^\top Q(\hat x-u)]+\mathbb E[(x_t^\star-\hat x)^\top Q(x_t^\star-\hat x)]$. The first term is zero for $u=\hat x$, which is admissible because every agent sees the whole snapshot. The same expansion with $u=0$ gives $\mathbb E[(x_t^\star-\hat x)^\top Q(x_t^\star-\hat x)]=\mathbb E[(x_t^\star)^\top Qx_t^\star]-\mathbb E[\hat x^\top Q\hat x]$. Hence $R_{\rm glob}(\tau)=R_\infty-\tfrac12\mathbb E[\hat x^\top Q\hat x]$.', NULL, NULL, NULL, 'supplied');
