INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C1.b/f1', 'C1.b', 1, NULL, 'TinaV2.C01b.Statement', 'TinaV2/Statements/C01b.lean', 'frozen', 'For any square-integrable target x* (no cost data needed) and any p with IsQProjection. The first conjunct, Q-orthogonality of the error to every admissible policy, is the defining property of IsQProjection restated, as in the paper where it is a reminder. The second is 2 R(A) = ||x*||_Q^2 - ||p||_Q^2 with R(A) = sigmaRegret.', '2026-11-14T16:37:06');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C1.c/f1', 'C1.c', 1, NULL, 'TinaV2.C01c.Statement', 'TinaV2/Statements/C01c.lean', 'frozen', 'Appendix sigma-algebra form (SigmaAdmissible, sigmaRegret), any square-integrable target. Adds G''_i <= F, which the paper has by definition of an architecture. Not yet linked to the function-form regret used elsewhere (F6).', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C1/f1', 'C1', 1, NULL, 'TinaV2.C01.Statement', 'TinaV2/Statements/C01.lean', 'frozen', 'Appendix sigma-algebra form: the architecture is a family G_i <= F and S(A) is policySpace (SigmaAdmissible as a set). Elements of H are functions, identified when almost surely equal. Cost data are the random variables b = b(theta_t) in L2 and c = c(theta_t) in L1, as the appendix assumes; x* = Q^{-1} b. Five parts. (1) ''Closed linear subspace of H'' is IsClosedSubspace: members are square-integrable, 0, sums and scalar multiples stay in S, and an L2 limit (E||u_n - v||^2 -> 0, ordinary Euclidean norm) of members is a.s. equal to a member; the paper''s remark that the Q-norm is equivalent to the L2 norm is what makes this the same as closed in the Q-norm. (2) The projection exists; the lemma takes this for granted. (3)-(5) hold for every p with IsQProjection, i.e. p in S with x* - p Q-orthogonal to S (the defining property of orthogonal projection; the nearest-point property is then part 3). ''Optimal policy under the quadratic cost'' = minimizes expectedCost E[f(u, theta_t)] over S; ''unique up to a.s. equality'' = any member of S that costs no more is a.s. equal to p. R(A) is sigmaRegret (the infimum of the tracking loss, Eq. architecture_regret, in sigma-algebra form). Not linked to the function-form regret of the main text (F6).', '2026-11-14T16:37:06');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C10.b/f1', 'C10.b', 1, NULL, 'TinaV2.C10b.Statement', 'TinaV2/Statements/C10b.lean', 'frozen', 'Same hypotheses as C10 (the temporal assumption at one epoch and one delay, R_inf > 0). First sentence: at eta_S(0) = 0, R_loc = 0 and every tau > 0 gives R_loc < R_glob(tau). Second sentence: for 0 < eta_S(0) < 1, rho* > 0, and tau/T below, at, above rho* gives R_glob < R_loc, equality, R_loc < R_glob.', '2026-11-19T13:13:27');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C10/f1', 'C10', 1, NULL, 'TinaV2.C10.Statement', 'TinaV2/Statements/C10.lean', 'superseded', '0 <= eta_S(0) is not a hypothesis (it always holds). The first conjunct is the branch eta_S(0) < 1, the second the clause for eta_S(0) = 1, as the theorem is worded since arXiv v3. rho* = +infinity is not represented; the clause is stated as ''no tau gives R_loc < R_glob''.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C10/f2', 'C10', 2, 'C10/f1', 'TinaV2.C10.Statement', 'TinaV2/Statements/C10.lean', 'frozen', '0 <= eta_S(0) is not a hypothesis (it always holds, and the proof does not use it). The first conjunct is the branch eta_S(0) < 1: R_loc < R_glob exactly when tau/T > rho*, and R_loc = R_glob exactly when tau/T = rho*. The second conjunct is the clause for eta_S(0) = 1, as the theorem is worded since arXiv v3. rho* = +infinity is not represented; the clause is stated as ''no tau gives R_loc < R_glob''. Replaces C10/f1, whose equality clause was one direction only (''tau/T = rho* gives equal regret''), so that below the threshold it gave R_glob <= R_loc and not the strict inequality.', '2026-11-19T13:13:27');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C11/f1', 'C11', 1, NULL, 'TinaV2.C11.Statement', 'TinaV2/Statements/C11.lean', 'frozen', 'Standalone (bestMSE, not the Model). sigma > 0 is the standard deviation; the paper says ''variance sigma^2 > 0'' since arXiv v3 (main-v3.tex 68), so the former difference C11/f1/d1 was removed on 2026-11-18. ''Independent signals/processes'' is independence of the two whole processes. Mean zero and variance sigma^2 are assumed at every time, so the stationarity hypothesis is redundant but kept. Each of clauses 1, 2 states both the value of the best error and that the named estimate attains it.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C12/f1', 'C12', 1, NULL, 'TinaV2.C12.Statement', 'TinaV2/Statements/C12.lean', 'frozen', 'Model instance: any Model on Fin n with Q = qI + gamma 11'', K = Q^{-1}, one scalar state and action per agent, any graph. sigma > 0, n >= 2, q > 0, gamma >= 0 as in the paper. Optimal local policy stated as existence of an admissible rule with action theta_i/(q+gamma) attaining R_loc (no uniqueness). Regret is the tracking-loss regret; its equality with excess expected f is C5.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C13.b/f1', 'C13.b', 1, NULL, 'TinaV2.C13b.Statement', 'TinaV2/Statements/C13b.lean', 'frozen', 'Pure limits of the closed forms aggRhoStar and aggEta as n -> infinity; gamma = 0 allowed.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C13.c/f1', 'C13.c', 1, NULL, 'TinaV2.C13c.Statement', 'TinaV2/Statements/C13c.lean', 'frozen', '''Increase'' is read as strictly increasing on gamma >= 0, for the closed forms. The gamma = 0 sentence is two clauses: eta_S(0) = 0 and rho*(0,n) = 0 (the second added at the review on 2026-11-15, before any attempt).', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C13/f1', 'C13', 1, NULL, 'TinaV2.C13.Statement', 'TinaV2/Statements/C13.lean', 'frozen', 'Same model as C12, with the temporal assumption at (t, tau) and the aggregate state hypotheses at epoch t. First conjunct identifies rho* of C10 with the closed form.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C14/f1', 'C14', 1, NULL, 'TinaV2.C14.Statement', 'TinaV2/Statements/C14.lean', 'frozen', 'Graph radii in N union {top} with a delay tau(r) per radius; r + 1 at top is top. Assumes only tau(r) >= 0 (inside TemporalAssumption) and R_inf > 0; the paper''s ''tau nondecreasing, tau(0) = 0, r <= D'' are not needed for these identities and are omitted. ''Improves performance'' = strictly lower regret.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C15.b/f1', 'C15.b', 1, NULL, 'TinaV2.C15b.Statement', 'TinaV2/Statements/C15b.lean', 'frozen', 'Same setting as C15 (F8). The gap is balanceGap (one-sided derivatives at endpoints). ''Unique optimum'' is stated as a strict maximum over [0, D].', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C15.c/f1', 'C15.c', 1, NULL, 'TinaV2.C15c.Statement', 'TinaV2/Statements/C15c.lean', 'frozen', 'Same setting as C15 (F8). ''Preserving single crossing'' = the gap is strictly decreasing before and after the change. Stated for any maximizers r, r'' (unique under single crossing). ''The optimum can stay unchanged at a boundary'' is covered by the weak inequalities.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C15/f1', 'C15', 1, NULL, 'TinaV2.C15.Statement', 'TinaV2/Statements/C15.lean', 'frozen', 'Pure real analysis about G = gain eta tau T for given curves on [0, D], the form the proposition has since arXiv v3 (''Suppose R(r)=R_inf[1-G(r)] for real r in [0,D]'', F8). ''Optimal radius'' = maximizer of G on [0, D]. tau'' >= 0, eta'' <= 0, 0 <= eta are kept as in the paper though the conclusion needs only differentiability and eta < 1. Derivative hypotheses are one-sided at the endpoints (derivWithin); the conclusion uses the ordinary derivative at the interior point.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C16/f1', 'C16', 1, NULL, 'TinaV2.C16.Statement', 'TinaV2/Statements/C16.lean', 'frozen', 'Pure real analysis about G with eta(r) = eta_0 exp(-2r/l_c), tau(r) = r/v, the form the proposition has since arXiv v3 (''Suppose R(r)=R_inf[1-G(r)] for real r >= 0'', F8). ''Unique global optimal radius'' = strict maximizer of G over r >= 0. Cap D >= 0.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C17.b/f1', 'C17.b', 1, NULL, 'TinaV2.C17b.Statement', 'TinaV2/Statements/C17b.lean', 'frozen', 'Both sentences of the paragraph, for every location z, time t, radius r >= 0 and delay tau >= 0. (1) The conditional-mean identity, almost surely, conditioning on the sigma-algebra generated by the observed interval. (2) ''Retains a^2 times the gain'' as R_inf - R(r,tau) = a^2 (R_inf - R(r,0)), with R_inf = (q/2) Var x*(z,t) and both regrets taken at the same epoch t. sigma = 0 is allowed (both sides are then zero).', '2026-11-14T19:06:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C17/f1', 'C17', 1, NULL, 'TinaV2.CanonicalField', 'TinaV2/Defs/Canonical.lean', 'frozen', 'Definitions only: CanonicalField (zero-mean jointly Gaussian field theta z t with the covariance of Eq. canonical_space_time_covariance, l_s > 0, T > 0, measurable values, sample paths continuous in the location), lineKernel (w_{l_c}), lineTarget (x*(z,t), the integral of the kernel against the field), lineObs (O_r(z,t), the field on [z-r, z+r] as a random element of [-r,r] -> R with the product sigma-algebra), lineCost (the 1x1 matrix (q)), lineR (regret at a location: the general regret of Defs/Architecture.lean with one agent and one action coordinate, target x*(z,t), observation O_r(z,t-tau)), lineRinf ((q/2) Var x*(z,t)), lineEtaS (lineR at zero delay over lineRinf). tau(r) = r/v and v > 0 are not part of the definitions; statements that use them say so. sigma is the standard deviation; sigma != 0 is a hypothesis of the statements that need it (F18).', '2026-11-14T19:06:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C18/f1', 'C18', 1, NULL, 'TinaV2.C18.Statement', 'TinaV2/Statements/C18.lean', 'frozen', 'eta_S(r) = lineEtaS = R(r,0)/R_inf at every location z and time t and every radius r >= 0, for the canonical field with sigma != 0. The paper sets z = 0 ''by stationarity''; Lean states every z directly. Since arXiv v3 the lemma itself says ''jointly Gaussian'' and sigma^2 > 0 (main-v3.tex 874-875), so the former differences C18/f1/d1 and C18/f1/d2 were removed on 2026-11-18.', '2026-11-14T19:06:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C19.b/f1', 'C19.b', 1, NULL, 'TinaV2.C19b.Statement', 'TinaV2/Statements/C19b.lean', 'superseded', 'About the closed form canonRadius. ''Within the interior regime'' = the base point satisfies vT > 2 l_s; ''increases/decreases'' = strict inequality for any larger value of the parameter.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C19.b/f2', 'C19.b', 2, 'C19.b/f1', 'TinaV2.C19b.Statement', 'TinaV2/Statements/C19b.lean', 'frozen', 'About the closed form canonRadius. ''Within the interior regime'' = the base point satisfies vT > 2 l_s, and in the item on l_s the larger l_s satisfies it too (F11.1). A larger T or v stays in the regime and l_c does not enter the condition, so the other three items need no second condition. ''Increases/decreases'' = strict inequality for any larger value of the parameter. Replaces C19.b/f1, whose item on l_s let the larger value leave the regime.', '2026-11-19T12:45:00');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C19/f1', 'C19', 1, NULL, 'TinaV2.C19.AlgebraicStatement', 'TinaV2/Statements/C19.lean', 'superseded', 'ALGEBRAIC FORM ONLY. States the radius formula, uniqueness and the threshold for the gain function with eta_0 = l_c/(l_c + 2 l_s). It does not mention the Gaussian field, the integral target or regret per unit length: that link is C17, C18, C17.b (tier D, F1). A full statement replaces this one (new formalization version) when tier D definitions exist.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C19/f2', 'C19', 2, 'C19/f1', 'TinaV2.C19.Statement', 'TinaV2/Statements/C19.lean', 'frozen', 'The theorem for the field model of C17: for the canonical field (jointly Gaussian) with sigma != 0, q > 0, v > 0, at every location z and time t, the regret R(r, r/v) = lineR of the radius-r snapshot is strictly smaller at r* = canonRadius than at every other r >= 0, and r* > 0 iff vT > 2 l_s. Replaces C19/f1 (algebraic form), which said nothing about the field. The comparative statics are C19.b. Since arXiv v3 the theorem itself says ''jointly Gaussian'' and sigma^2 > 0 (main-v3.tex 901-902), so the former differences C19/f2/d1 and C19/f2/d2 were removed on 2026-11-18.', '2026-11-14T19:33:03');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C2/f1', 'C2', 1, NULL, 'TinaV2.C02.Statement', 'TinaV2/Statements/C02.lean', 'frozen', 'Same setting as C1/f1. Three conjuncts. (1) Necessity: ''the unique team optimum in the Lemma'' is any p with IsQProjection; it satisfies NormalEquations, which is E[(Q u - b)_c | G_{actor c}] = 0 a.s. for every action coordinate c (agent i''s block is the coordinates with actor c = i). (2) Sufficiency and uniqueness (''strict convexity makes them sufficient for the unique team optimum''): a member of S satisfying the equations minimizes expectedCost over S, and any member that costs no more is a.s. equal to it. (3) The block form Eq. (block_conditional_normal_equations) is equivalent for members of S: coordinates of the same agent enter as u, coordinates of other agents as E[u | G_i]. NOT stated: ''one generally does not have u_i* = E[x_i* | G_i]'' (a statement about what fails in general, with no example in this corollary; the numeric check finds a strict gap in every trial, and C12 is an instance); the last sentence (common information) is C3.', '2026-11-14T16:37:06');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C20/f1', 'C20', 1, NULL, 'TinaV2.C20.Statement', 'TinaV2/Statements/C20.lean', 'frozen', 'About the closed form canonRadius: limit as l_c -> infinity with l_s, v, T fixed and vT > 2 l_s.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C3.b/f1', 'C3.b', 1, NULL, 'TinaV2.C03b.Statement', 'TinaV2/Statements/C03b.lean', 'frozen', 'Three conjuncts: x* = 0 a.s.; zero regret for every observation family (not only radius architectures); composition identity for any weight a. ''Centered coordinates'' is carried by the definition R_inf = (1/2) E[x*''Q x*].', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C3/f1', 'C3', 1, NULL, 'TinaV2.C03.Statement', 'TinaV2/Statements/C03.lean', 'frozen', 'Same cost setting as C1/f1. ''Every agent observes the same Z'': Z is a measurable map into any measurable space and every agent''s sigma-algebra is sigma(Z) (any common sub-sigma-algebra of F has this form, with Z the identity). m = E[x* | Z] is Mathlib''s vector-valued conditional expectation. Three conjuncts: m is in S; m minimizes expectedCost over S; any member of S that costs no more is a.s. equal to m. ''Regardless of the off-diagonal entries of Q'' is the quantifier over every positive definite Q. The regret value is not stated here (the paragraph ''Delayed common snapshots'', C3.c, states it).', '2026-11-14T16:37:06');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C4.b/f1', 'C4.b', 1, NULL, 'TinaV2.C04b.Statement', 'TinaV2/Statements/C04b.lean', 'superseded', 'Integer time. ''Independent innovations'' is read as: each innovation is independent of every earlier state (F9); mutual independence of the innovations is not assumed. Second conjunct states the composition law with weights 1 - c^(2k), c^(2k) for the model.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C4.b/f2', 'C4.b', 2, 'C4.b/f1', 'TinaV2.C04b.Statement', 'TinaV2/Statements/C04b.lean', 'frozen', 'Integer time. theta_{s+1} = c theta_s + eps_{s+1}, 0 < c < 1, theta stationary with finite second moments, innovations with finite second moments and E[eps_{s+1} | F_s] = 0 almost surely, F_s the sigma-algebra generated by theta_u for u <= s (the appendix''s hypothesis since arXiv v3). First conjunct: the prediction rule with coefficient c^k between epochs t - k and t. Second conjunct: the composition law with weights 1 - c^(2k) and c^(2k). Replaces C4.b/f1, which assumed each innovation independent of every earlier state and mean zero.', '2026-11-19T12:45:00');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C4.c/f1', 'C4.c', 1, NULL, 'TinaV2.C04c.Statement', 'TinaV2/Statements/C04c.lean', 'frozen', 'Design chosen by Scott on 2026-11-19 (README, Decisions). Real time. Hypotheses: a jointly Gaussian state process, mean zero, E[theta_t,k theta_s,l] = exp(-|t-s|/T) S_kl, T > 0, each theta_t measurable. Conclusion at every epoch t and delay tau >= 0: the innovation theta_t - exp(-tau/T) theta_{t-tau} is Gaussian; it is independent of the earlier states (theta_s : s <= t - tau); TemporalAssumption mu theta T t tau (stationary one-time laws, finite second moments, the conditional-mean rule). The covariance Eq. (separable_space_time_covariance) is a hypothesis; the differential equation Eq. (OU_process) is not stated.', '2026-11-19T14:34:14');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C4/f1', 'C4', 1, NULL, 'TinaV2.TemporalAssumption', 'TinaV2/Defs/Temporal.lean', 'frozen', 'An assumption, so a predicate, not a Prop to prove: StationaryState + T > 0 + tau >= 0 + PredictionRule at one epoch t and one delay tau (''for every delay analyzed'' = each tau a statement uses). Stationarity is equality of one-time laws only (F7). Disturbance is defined as theta_t - a theta_{t-tau}; conditioning is on the sigma-algebra of the whole old state. Measurability of each theta_t added as routine regularity. Centering is not assumed: it follows from the rule when tau > 0.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C5.b/f1', 'C5.b', 1, NULL, 'TinaV2.C05b.Statement', 'TinaV2/Statements/C05b.lean', 'frozen', 'Two conjuncts: centered target equals K theta^c pointwise; regret of the uncentered problem (target Q^{-1}(B theta + b0), observations of the uncentered snapshot) equals M.R for the centered snapshots. The ''bijection of admissible rules'' is the proof, not part of the statement. Stated for radius architectures.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C5/f1', 'C5', 1, NULL, 'TinaV2.C05.Statement', 'TinaV2/Statements/C05.lean', 'frozen', 'Pointwise in the state: b, c are the values b(theta), c(theta). Second conjunct adds ''x* is the unique minimizer'' (appendix, sentence before Eq. clairvoyant), which the ledger claim text did not list.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C6.b/f1', 'C6.b', 1, NULL, 'TinaV2.C06b.Statement', 'TinaV2/Statements/C06b.lean', 'frozen', 'Centering is an explicit hypothesis (E[theta_k] = 0). ''Best no-information action is zero'' is stated as: no constant action costs less than R_inf, and zero costs R_inf. Sigma_S is the covariance matrix of the snapshot.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C6.c/f1', 'C6.c', 1, NULL, 'TinaV2.C06c.Statement', 'TinaV2/Statements/C06c.lean', 'frozen', 'Needs R_inf > 0 as in the paper. Monotonicity over all radii including top. Diameter clause: finite connected graph, radius = diam. ''eta_S(0) = R_loc/R_inf'' is true by definition and omitted.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C6/f1', 'C6', 1, NULL, 'TinaV2.Model', 'TinaV2/Defs/Architecture.lean', 'frozen', 'Definitions only: Model, nbhd, Scope, obs, target, Rule, Admissible, regret, R, Rloc, Rglob, Rinf, etaS. State and action coordinates are index types with owner/actor maps (the paper''s blocks theta_i, x_i). A rule gives each action coordinate as a function of its agent''s observation; measurability of g added as routine regularity. Regret is a real infimum (well defined: zero rule, cost >= 0). Radius is in N union {top}; stale-global is radius top (F5). etaS divides by R_inf, so statements using it assume R_inf > 0.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C7.b/f1', 'C7.b', 1, NULL, 'TinaV2.C07b.Statement', 'TinaV2/Statements/C07b.lean', 'frozen', 'Snapshot form: R(A_{r,tau}) at epoch t is M.R mu r (theta (t - tau)) (theta t); the paper suppresses t. Radius ranges over N union {top}. Same hypotheses as C7 plus R_inf > 0.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C7/f1', 'C7', 1, NULL, 'TinaV2.C07.Statement', 'TinaV2/Statements/C07.lean', 'frozen', 'Snapshot form: R(A_{r,tau}) at epoch t is M.R mu r (theta (t - tau)) (theta t); the paper suppresses t. Radius ranges over N union {top}. Hypothesis is TemporalAssumption at (t, tau): weaker than the paper''s process-level stationarity (F7). Q > 0 is a field of Model. ''All admissible finite-second-moment rules'' is the infimum in regret.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C8.c/f1', 'C8.c', 1, NULL, 'TinaV2.C08c.Statement', 'TinaV2/Statements/C08c.lean', 'frozen', 'Assumes the temporal assumption for every tau >= 0 at the fixed epoch t. ''Grows initially as'' is little-o as tau decreases to 0 from the right; the limit is as tau -> infinity.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C8/f1', 'C8', 1, NULL, 'TinaV2.C08.Statement', 'TinaV2/Statements/C08.lean', 'frozen', 'R_glob is M.R at radius top, i.e. every agent sees every state coordinate of the old snapshot (F5). No connectivity assumed. ''Under the tracking model and stationary transition'' (arXiv v3) is TemporalAssumption at epoch t and delay tau, the same hypothesis as before v3.', '2026-11-13T14:16:11');
INSERT INTO formalizations (id, claim_id, version, parent, lean_decl, lean_file, status, fidelity, created) VALUES ('C9/f1', 'C9', 1, NULL, 'TinaV2.C09.Statement', 'TinaV2/Statements/C09.lean', 'frozen', 'Design chosen by Scott on 2026-11-19 (README, Decisions). Mode k is the part P_k theta of the state, the matrices P_k sum to the identity, x_k* = K P_k theta_t. Hypotheses: the mode processes are independent (iIndepFun of the paths); each mode satisfies the hypotheses of C4.c/f1 word for word with its own T_k > 0 and S_k (jointly Gaussian, mean zero, covariance exp(-|t-s|/T_k) S_k); R_inf > 0; tau >= 0. Conclusion: x* = sum_k x_k*, sum_k w_k = 1 with w_k = E[x_k*^T Q x_k*] / E[x*^T Q x*], and 1 - R_glob(tau)/R_inf = sum_k w_k exp(-2 tau/T_k), where R_glob(tau) is M.Rglob mu (theta (t - tau)) (theta t).', '2026-11-19T14:34:14');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C1.b/a1', 'C1.b/f1', 'C1.b/p1', NULL, 'TinaV2/Proofs/C01b/A1.lean', 'Mirror the supplement proof C1.b/p1: step 1 unfolds IsQProjection; step 2 expands the squared Q-norm of u* + (x* - u*) with the cross term zero by step 1; step 3 applies C1 with b = Q x* and c = 0 and substitutes step 2.', 'proved', 1, 3.8, 82, '2026-11-15T13:54:41', '2026-11-15T13:54:41');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C1.c/a1', 'C1.c/f1', 'C1.c/p1', NULL, 'TinaV2/Proofs/C01c/A1.lean', 'Mirror the supplement proof C1.c/p1: step 1 is monotonicity of measurability in the sigma-algebra; step 2 bounds the infimum over S(A'') by each member of S(A), using the routine lemmas le_sigmaRegret and sigmaRegret_le.', 'proved', 1, 6.3, 40, '2026-11-15T13:54:41', '2026-11-15T13:54:41');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C1/a1', 'C1/f1', 'C1/p1', NULL, 'TinaV2/Proofs/C01/A1.lean', 'Steps 1-2 on functions: sums and multiples coordinate by coordinate; closedness from Mathlib''s closedness of sub-sigma-algebra-measurable classes in L2 (isClosed_aestronglyMeasurable), one coordinate at a time. Step 3 integrates C5 (hypothesis) state by state. Step 4: existence from Mathlib''s Hilbert projection theorem in L2(Omega; (R^d, <.,.>_Q)) through Routine/QHilbert.lean (exists_isQProjection); optimality, uniqueness and the regret value from the Pythagorean identity for a projection.', 'proved', 1, 4.5, 184, '2026-11-14T17:54:54', '2026-11-14T17:54:54');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C10.b/a1', 'C10.b/f1', 'C10.b/p1', NULL, 'TinaV2/Proofs/C10b/A1.lean', 'Mirror the supplement proof C10.b/p1 with C10 as a hypothesis: step 1 evaluates rho* at eta = 0 and applies the first equivalence of C10; step 2 is the sign of a logarithm; step 3 reads off the two equivalences of C10 and closes the case below the threshold by trichotomy.', 'proved', 1, NULL, 77, '2026-11-19T13:13:27', '2026-11-19T13:13:27');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C10/a1', 'C10/f2', 'C10/p1', NULL, 'TinaV2/Proofs/C10/A1.lean', 'Divide by R_inf using C8 as a hypothesis; rearrange through log. The endpoint eta_S(0) = 1 is step 3, a sentence of the paper''s proof since arXiv v3 (before, one line in main). Re-pointed from C10/f1 to C10/f2 on 2026-11-19: the lemma for step 2 states the equality case as an equivalence (five more lines, the converse through log of the exponential); the other lemmas and main are unchanged.', 'proved', 1, 3.9, 85, '2026-11-14T16:00:50', '2026-11-19T13:13:27');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C11/a1', 'C11/f1', 'C11/p1', NULL, 'TinaV2/Proofs/C11/A1.lean', 'Conditional mean attains the smallest mean squared error (orthogonality by the pull-out property); E[Y_t | X_t] = 0 by independence; conditioning on the pair of old readings reduces to conditioning on one by independence of the whole processes; error formula by orthogonality and stationarity.', 'proved', 1, 3.7, 261, '2026-11-14T16:10:38', '2026-11-14T16:10:38');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C12/a1', 'C12/f1', 'C12/p1', NULL, 'TinaV2/Proofs/C12/A1.lean', 'Main-text proof: split each local rule into mean plus centered part, expand the expected cost using independence, minimize the mean terms and each centered term, compute the full-information cost from the two eigenspaces of Q, and subtract costs; the bridge from cost differences to regret is C5, taken as a hypothesis.', 'proved', 1, 5.2, 461, '2026-11-14T16:11:09', '2026-11-14T16:11:09');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C13.b/a1', 'C13.b/f1', 'C13.b/p1', NULL, 'TinaV2/Proofs/C13b/A1.lean', 'Mirror the supplement proof C13.b/p1: step 1 writes the ratio as 1 - gamma/(q+gamma n) and uses that the denominator tends to infinity (gamma = 0 separately); step 2 composes with continuity of log at 1+gamma/q; step 3 uses the inverse of step 1, for n >= 1.', 'proved', 1, 4.0, 78, '2026-11-15T13:35:42', '2026-11-15T13:35:42');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C13.c/a1', 'C13.c/f1', 'C13.c/p1', NULL, 'TinaV2/Proofs/C13c/A1.lean', 'Mirror the supplement proof C13.c/p1: closed-form algebra by field_simp and ring; strict monotonicity of gamma^2/(q+gamma n) by cross-multiplying and factoring the difference; then log is strictly increasing and inversion is strictly decreasing on positive numbers. n >= 2 is used only for the positive coefficient (n-1)/q.', 'proved', 1, 4.0, 121, '2026-11-15T13:35:42', '2026-11-15T13:35:42');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C13/a1', 'C13/f1', 'C13/p1', NULL, 'TinaV2/Proofs/C13/A1.lean', 'Mirror the supplement proof C13/p1 with C12 and C10 (statement version f2) as hypotheses: step 1 reads eta_S(0) and R_inf off C12 and shows the closed form of R_inf positive; step 2 is algebra on the closed forms (field_simp, ring); step 3 feeds R_inf > 0 and eta_S(0) < 1 to the first clause of C10 and rewrites the threshold.', 'proved', 1, 7.0, 81, '2026-11-19T13:44:09', '2026-11-19T13:44:09');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C14/a1', 'C14/f1', 'C14/p1', NULL, 'TinaV2/Proofs/C14/A1.lean', 'Substitute C7 (hypothesis) and eta_S = R/R_inf; the criterion and the decomposition are arithmetic on step 1.', 'proved', 1, 3.8, 64, '2026-11-14T16:00:50', '2026-11-14T16:00:50');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C15.b/a1', 'C15.b/f1', 'C15.b/p1', NULL, 'TinaV2/Proofs/C15b/A1.lean', 'Mirror the supplement proof C15.b/p1: step 1 gets HasDerivWithinAt for L on Icc 0 D with value balanceGap, and continuity of balanceGap from ContDiffOn.continuousOn_derivWithin; step 2 passes to deriv at interior points and uses Mathlib''s strictMonoOn_of_deriv_pos / strictAntiOn_of_deriv_neg on Icc a b, then exp; steps 3-5 apply step 2 on [0, D], [0, r0], [r0, D], with intermediate_value_Ioo'' for the zero.', 'proved', 1, 9.0, 141, '2026-11-19T13:49:06', '2026-11-19T13:49:06');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C15.c/a1', 'C15.c/f1', 'C15.c/p1', NULL, 'TinaV2/Proofs/C15c/A1.lean', 'Mirror the supplement proof C15.c/p1 with C15.b as a hypothesis: step 1 builds SmoothCurves for alpha tau_0 and unfolds balanceGap with derivWithin_const_mul; step 2 is gcongr on that formula; step 3 reads the three clauses of C15.b and uses that a strict maximizer equals any maximizer; steps 4 and 5 are by contradiction, closed by linarith from the two signs, strict antitonicity and step 2.', 'proved', 1, 6.0, 151, '2026-11-19T13:49:06', '2026-11-19T13:49:06');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C15/a1', 'C15/f1', 'C15/p1', NULL, 'TinaV2/Proofs/C15/A1.lean', 'log is monotone on G > 0; interior maximizer is a local maximizer so deriv (log G) = 0; differentiate log G near the point.', 'proved', 1, 3.8, 70, '2026-11-14T16:00:50', '2026-11-14T16:00:50');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C16/a1', 'C16/f1', 'C16/p1', NULL, 'TinaV2/Proofs/C16/A1.lean', 'HasDerivAt formula for G; bracket strictly decreasing with negative limit; sign of the bracket gives monotonicity of G; crossing by the intermediate value theorem; solve for the crossing; truncate at the cap.', 'proved', 1, 4.8, 211, '2026-11-14T16:00:50', '2026-11-14T16:00:50');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C17.b/a1', 'C17.b/f1', 'C17.b/p1', NULL, 'TinaV2/Proofs/C17b/A1.lean', 's1: covariance equation twice. s2: the innovation field and the old field are jointly Gaussian (linear combinations of field values) and uncorrelated, so independent (Mathlib indepFun_of_covariance_eq_zero). s3: x*(t) = a x*(t-tau) + W almost surely, W the kernel integral of the innovation field; W is measurable for the innovation field, hence independent of the observed interval, and has mean zero. s4: regret = (q/2) E[Var(x* | O)] and total variance, for a general delay. s5: the two spatial slices are Gaussian with the same means and second moments, so they have the same law; the pair (target, observation) is a fixed measurable function of the slice up to a null set. s6: s4 twice, s3, s5.', 'proved', 1, 1.7, 192, '2026-11-14T19:18:58', '2026-11-14T19:18:58');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C18/a1', 'C18/f1', 'C18/p1', NULL, 'TinaV2/Proofs/C18/A1.lean', 's1: regret = (q/2) E[Var(x* | O_r)], so eta_S(r) = E[Var(x* | O_r)] / Var x*. s2: split the target integral at +-r; the middle is O_r-measurable. s3: u = r + s. s3b (supplied): the residual fields beyond the two endpoints are jointly Gaussian with the observed field and uncorrelated with it and with each other, hence independent (Mathlib indepFun_of_covariance_eq_zero, twice); each tail integral is a multiple of its endpoint value plus E+-. s4: both conditional variances of a tail equal the variance of its E term, and the conditional covariance is E[E+ E-] = 0. s5: Var E+- is one double integral of second moments of the residual field, the same for every endpoint and both sides (the paper''s C, never evaluated); condVar of a sum. s6: at r = 0, x* = rho theta(z) + W with W independent of theta(z). s7, s8: expectation under the integral sign and the covariance integrals. s9: combine.', 'proved', 1, 1.8, 554, '2026-11-14T19:33:02', '2026-11-14T19:33:02');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C19.b/a1', 'C19.b/f2', 'C19.b/p1', NULL, 'TinaV2/Proofs/C19b/A1.lean', 'Items 1-3 through HasDerivAt of canonRadius inside the regime and the sign of the derivative; item 4 through the integral representation (fundamental theorem of calculus) and a strict integral inequality. Re-pointed from C19.b/f1 to C19.b/f2 on 2026-11-18: step 2 lost the case in which the larger l_s leaves the regime, which the paper''s step does not cover.', 'proved', 1, 4.4, 145, '2026-11-14T16:00:51', '2026-11-19T12:45:00');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C19/a1', 'C19/f1', 'C19/p1', NULL, 'TinaV2/Proofs/C19/A1.lean', 'Algebraic form: eta_0 is an admissible prefactor; substitute into C16 (hypothesis) and simplify eta_0 (1 + vT/l_c).', 'superseded', 0, 4.2, 58, '2026-11-14T16:00:51', '2026-11-14T19:33:03');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C19/a2', 'C19/f2', 'C19/p1', 'C19/a1', 'TinaV2/Proofs/C19/A2.lean', 'Field form. s0: C17.b gives R(r, r/v) = R_inf [1 - G(r)] for the field''s own omission share (a sentence of the proof since arXiv v3). s1: C18 gives the omission curve and 0 < eta_0 < 1. s2: R_inf > 0 because eta_S(0) = eta_0 is not zero; s0 and s1 give the curve; then C16 with eta_0 = l_c/(l_c + 2 l_s).', 'proved', 1, NULL, 121, '2026-11-14T19:33:03', '2026-11-19T12:45:00');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C2/a1', 'C2/f1', 'C2/p1', NULL, 'TinaV2/Proofs/C02/A1.lean', 'Necessity by the first-order condition: a projection is optimal (C1, hypothesis), the cost along p + t h is t L + (1/2) t^2 ||h||_Q^2 >= 0, so the derivative L at t = 0 vanishes; one-coordinate indicator perturbations and uniqueness of conditional expectation give the equations. Sufficiency: tower property and pull-out remove the linear term of the expansion, positive definiteness does the rest. Block form from a routine lemma (no paper step).', 'proved', 1, 1.9, 185, '2026-11-14T16:50:34', '2026-11-14T16:50:34');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C20/a1', 'C20/f1', 'C20/p1', NULL, 'TinaV2/Proofs/C20/A1.lean', 'Mirror the supplement proof C20/p1: step 1 unfolds canonRadius in the positive-radius regime (Routine/RadiusCalculus) and rewrites the ratio; step 2 shifts Mathlib''s limit of x log(1 + t/x) by d; step 3 combines them on l_c > 0, which holds eventually.', 'proved', 1, 4.0, 69, '2026-11-19T13:44:10', '2026-11-19T13:44:10');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C3.b/a1', 'C3.b/f1', 'C3.b/p1', NULL, 'TinaV2/Proofs/C03b/A1.lean', 'Integral of a nonnegative integrable function is zero iff it vanishes a.e.; zero rule gives regret zero; every term of the law is zero.', 'proved', 1, 3.7, 74, '2026-11-14T16:00:51', '2026-11-14T16:00:51');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C3/a1', 'C3/f1', 'C3/p1', NULL, 'TinaV2/Proofs/C03/A1.lean', 'Step 1: m = E[x* | Z] is in S, and E[h'' Q (x* - m)] = 0 coordinate by coordinate, pulling the sigma(Z)-measurable h_c out of the conditional expectation. Step 2: expansion of the expected cost around m (Routine expectedCost_add); the linear term is -<h, x* - m>_Q = 0 by step 1 and Q x* = b; positive definiteness gives optimality and uniqueness. No use of C5.', 'proved', 1, 2.4, 112, '2026-11-14T16:50:34', '2026-11-14T16:50:34');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C4.b/a1', 'C4.b/f2', 'C4.b/p1', NULL, 'TinaV2/Proofs/C04b/A1.lean', 's1: by induction theta_t - c^k theta_{t-k} is the sum of c^j eps_{t-j} over j < k; each term has conditional mean zero given theta_{t-k} because sigma(theta_{t-k}) is inside F_{t-j-1} (tower property). s2: the composition theorem C7, taken as a hypothesis, read in integer time through s -> theta_floor(s) with T = -1/log c and delay k, so that exp(-k/T) = c^k.', 'proved', 1, NULL, 126, '2026-11-19T12:45:00', '2026-11-19T12:45:00');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C4.c/a1', 'C4.c/f1', 'C4.c/p1', NULL, 'TinaV2/Proofs/C04c/A1.lean', 'Mirror the supplement proof C4.c/p1. Step 1 from the covariance hypothesis and integrability of products of Gaussian coordinates. Step 2: the innovation coordinates together with the earlier states are a Gaussian process (IsGaussianProcess.of_isGaussianProcess), Mathlib''s indepFun_of_covariance_eq_zero with index sets kappa and Iic(t - tau) x kappa, then currying the second family. Step 3: condExp_indep_eq for the vector-valued innovation and eval_integral for its mean. Step 4: identDistrib_of_isGaussianProcess from Routine/Conditioning. No vendoring, no Mathlib bump.', 'proved', 1, 9.5, 175, '2026-11-19T14:40:30', '2026-11-19T14:40:30');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C5.b/a1', 'C5.b/f1', 'C5.b/p1', NULL, 'TinaV2/Proofs/C05b/A1.lean', 'Linearity of expectation for the centered target; explicit Equiv on rules (translate observation and action) preserving admissibility and x - x*; Equiv.iInf_congr.', 'proved', 1, 4.0, 93, '2026-11-14T16:00:51', '2026-11-14T16:00:51');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C5/a1', 'C5/f1', 'C5/p1', NULL, 'TinaV2/Proofs/C05/A1.lean', 'Mirror the supplement proof C5/p1: Q x* = b from the routine inverse lemma, the routine expansion quadCost_add at u = x* with h = x - x*, then Mathlib''s positivity of the quadratic form of a positive definite matrix.', 'proved', 1, 8.0, 48, '2026-11-14T18:35:03', '2026-11-14T18:35:03');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C6.b/a1', 'C6.b/f1', 'C6.b/p1', NULL, 'TinaV2/Proofs/C06b/A1.lean', 'Mirror the supplement proof C6.b/p1: step 1 expands the quadratic form and integrates, the cross term vanishing by the zero means; step 2 uses positivity of the quadratic form; step 3 expands the quadratic form in coordinates, integrates term by term and identifies the second moments with the covariance matrix.', 'proved', 1, 4.1, 105, '2026-11-15T13:54:41', '2026-11-15T13:54:41');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C6.c/a1', 'C6.c/f1', 'C6.c/p1', NULL, 'TinaV2/Proofs/C06c/A1.lean', 'Mirror the paper proof C6.c/p1 with its one supplied step: the range from nonnegativity of regret and admissibility of the zero rule; monotonicity as the paper says it, a rule of the smaller view composed with the restriction of the larger view is a rule of the larger view with the same joint action; at the diameter every scope is the whole state, so the target is feasible. C1.c is not used.', 'proved', 1, 4.1, 99, '2026-11-15T13:54:41', '2026-11-15T13:58:49');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C7.b/a1', 'C7.b/f1', 'C7.b/p1', NULL, 'TinaV2/Proofs/C07b/A1.lean', 'Mirror the supplement proof C7.b/p1: C7 enters as a hypothesis; step 1 divides it by R_inf > 0 and unfolds eta_S (field_simp); step 2 subtracts from one and uses exp(-tau/T)^2 = exp(-2 tau/T).', 'proved', 1, 10.3, 52, '2026-11-15T13:35:42', '2026-11-15T13:35:42');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C7/a1', 'C7/f1', 'C7/p1', NULL, 'TinaV2/Proofs/C07/A1.lean', 'Steps stated for a general weight a and a pair of snapshots; cross term by the conditional-expectation pull-out; rescaling and stationarity as bijections of the admissible rule class (Equiv.iInf_congr).', 'proved', 1, 4.0, 238, '2026-11-14T16:00:49', '2026-11-14T16:00:49');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C8.c/a1', 'C8.c/f1', 'C8.c/p1', NULL, 'TinaV2/Proofs/C08c/A1.lean', 'Mirror the supplement proof C8.c/p1 with C8 as a hypothesis: step 1 applies it at every delay and evaluates at 0; step 2 composes the little-o form of the derivative of exp at 0 with tau -> -2 tau/T on the right neighbourhood of 0; step 3 composes exp -> 0 at -infinity with the same map.', 'proved', 1, 17.0, 89, '2026-11-19T13:44:09', '2026-11-19T13:44:09');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C8/a1', 'C8/f1', 'C8/p1', NULL, 'TinaV2/Proofs/C08/A1.lean', 'Exhibit the rule u = K theta on the complete (radius top) view, so the fresh regret is zero; substitute in C7, taken as a hypothesis.', 'superseded', 0, 4.0, 54, '2026-11-14T16:00:50', '2026-11-19T12:45:00');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C8/a2', 'C8/f1', 'C8/p2', 'C8/a1', 'TinaV2/Proofs/C08/A2.lean', 's1: the rule u = a K theta_old on the complete (radius top) views is admissible. s2: by C7''s step lemmas s3_error_split and s4_disturbance_energy, every admissible rule costs half its first term plus (1 - a^2) R_inf; the first term is nonnegative and is zero for the rule of s1, so the infimum is (1 - a^2) R_inf and that rule attains it. Imports TinaV2.Proofs.C07.A1 for the two step lemmas (the declared cross-proof dependency); main takes no hypothesis.', 'proved', 1, NULL, 120, '2026-11-19T12:45:00', '2026-11-19T12:45:00');
INSERT INTO attempts (id, formalization_id, proof_id, parent, lean_file, strategy, status, selected, build_seconds, lean_lines, created, updated) VALUES ('C9/a1', 'C9/f1', 'C9/p1', NULL, 'TinaV2/Proofs/C09/A1.lean', 'Mirror the paper proof C9/p1 (three sentences) with three supplied steps and C4.c as a hypothesis, used once per mode. Step 1: independence of two modes at one epoch gives E[fg] = E[f]E[g] coordinate by coordinate, and centering makes one factor zero. Step 2a: Routine/Estimation''s condExp_sup_of_indep coordinate by coordinate, then the tower property. Step 2: x*_{k,t} = a_k x*_{k,t-tau} + K eps_k; stationarity of the mode from C4.c. Step 2b: the cross-term argument of the composition theorem for the sigma-algebra of the snapshot (Routine/Modes), and an explicit linear rule of the radius-top views whose action is x-hat. Step 3: expand the quadratic form of the sum, drop cross terms by step 1 at epoch t - tau, divide by 2 R_inf.', 'proved', 1, 6.0, 520, '2026-11-19T14:57:28', '2026-11-19T14:57:28');
