INSERT INTO edits (id, claim_id, target, from_proof, to_proof, reason, status, applied_commit, created) VALUES ('E1', 'C8', 'proof', 'C8/p1', 'C8/p2', 'Finding F5 and the point C8.b/d1. Made upstream by Bhaskar in arXiv v3, not written here; recorded so that the new proof version of C8 traces to the text that changed. The corollary is proved directly from the innovation split, so it no longer needs a radius that reaches every agent, and the sentence about the optimal global action moved into the proof.', 'applied', '12a9b3265fec20d55c9e630fbeee1016f3fca3c1', '2026-11-19T12:45:00');
