INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F1', 'C17.b', NULL, 'medium', 'Continuum model uses the finite-graph composition theorem without a bridge', 'C16 is stated ''Under Theorem C7'' and C19 is proved by substitution into C16, but C7 is stated and proved for a finite-dimensional stacked state with matrices K and Q. The canonical model has a field-valued state, an integral target and continuous radius, and the temporal conditional-mean assumption is not verified for the field (needs joint Gaussianity in space and time). The Lean proof of C19 cannot be closed without a stated bridge, so the paper needs an edit that adds one. Same issue as K2 in the co-author review.', 'resolved', 'Resolved by upstream commit 284a0e0 (confirmed by Scott 2026-11-14): the canonical field is now stated as jointly Gaussian in space and time, and a paragraph at main-v2.tex 839-855 argues the continuum composition law directly from the covariance (C17.b/p1). What is left is in F10.', '2026-11-13T13:26:00');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F10', 'C19', 'C19/p1/s2', 'minor', 'The proof of the canonical radius theorem does not cite the new continuum composition paragraph', 'Upstream 284a0e0 added the continuum composition law as an unlabelled paragraph (main-v2.tex 839-855, claim C17.b). The proof of C19 still reads ''Substitution into Proposition [generic_exponential_radius] gives the radius'', and that proposition still opens ''Under Theorem [spatiotemporal_composition]'', the finite-graph theorem. The proof of C19 does not say that the canonical model satisfies R(r) = R_inf [1 - G(r)], which is what the new paragraph supplies, and the paragraph has no label to cite. The paragraph also ends in words (''retains a^2 times the gain from a fresh interval of the same radius'') and never displays the identity. Separately, ''We measure regret per unit length, equal by stationarity to expected pointwise loss'' (line 824) is still asserted without an argument; it is not needed if regret in this model is defined as the expected pointwise loss. Also, the statements of C18 (''For the field [covariance equation]'') and C19 (''Suppose the field obeys Eq. [covariance equation]'') identify the field only by its covariance; joint Gaussianity is stated in the model paragraph (line 797) and in the limitations, but both proofs need it. Suggested edit: make the paragraph a labelled lemma with the identity displayed, cite it in the proof of C19, and say ''jointly Gaussian field'' in the two statements. This is what remains of F1; related to F8.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): the theorem''s proof opens by citing the field calculation, main-v3.tex 927-929 (F10.2; now the paper step C19/p1/s0), and the lemma (874-875) and the theorem (901-902) say ''jointly Gaussian'' (F10.3). F10.1 was left as written and F10.4 is a reading.', '2026-11-14T13:50:24');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F11', 'C19.b', 'C19.b/p1/s2', 'minor', 'Comparative static in l_s: the Lean statement lets the larger l_s leave the interior regime, where the derivative argument does not apply', 'The theorem says ''Within the interior regime, r* decreases with the spatial correlation length l_s'' and the proof gives the derivative -l_c/(l_c + 2 l_s) < 0 ''in the positive-radius regime''. The draft Lean statement C19.b/f1 starts from a point with vT > 2 l_s and compares it with every l_s'' > l_s, including l_s'' with 2 l_s'' >= vT, where r* = 0 by the positive part. The inequality is still true there (r*(l_s'') = 0 < r*(l_s)), but not by the derivative. In C19.b/a1 that case is closed inside s2_deriv_ls from the definition of canonRadius, in about eight lines marked ''Case not in the paper''s step''. Items 1, 2 and 4 have no such case: raising T or v stays in the regime and the regime does not depend on l_c. Options: (a) restrict item 3 of the Lean statement to 2 l_s'' < vT, which is the paper''s sentence read with both points in the regime; s2 is then exactly the paper''s step and no paper change is needed. (b) Keep the wider statement and add to the paper: ''once 2 l_s >= vT the radius is zero''. Recommendation: (a), as a new formalization version at statement review.', 'resolved', 'Closed 2026-11-19 by Scott. No paper change: the manuscript already restricts the strict decrease in l_s to the interior regime. The Lean statement follows that reading since 2026-11-18: item 3 of C19.b/f2 compares only pairs of l_s that are both inside the regime (difference row C19.b/f2/d1), and step 2 of the attempt is the paper''s derivative step with no extra case. The statement C19.b/f2 itself is still a draft and waits for Scott''s review.', '2026-11-14T16:01:45');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F12', 'C16', 'C16/p1/s4', 'minor', 'Exponential-omission proof: existence of the crossing, the positivity criterion and the link to the positive part are left unsaid', 'Three small things the Lean proof C16/a1 needed that the proof at main 774-786 does not say. (1) ''Otherwise G increases up to its unique crossing'': that the bracket has a zero is not argued. Lean uses continuity of the bracket, its positive value at zero and its negative limit (intermediate value theorem), inside s4_positive_at_zero. (2) ''It is positive exactly when eta_0 (1 + vT/l_c) > 1'' is in the statement and no proof sentence addresses it. Lean reads it off the closed form (Routine/ExpRadius.lean, expRadius_pos_iff), used in main. (3) The proof splits on the sign of the bracket at zero while the boxed formula uses a positive part. The link is the identity vT * bracket(c) = eta_0 (1 + vT/l_c) e^{-2c/l_c} - 1, which the paper does not write; at c = 0 it says the bracket at zero has the sign of eta_0 (1 + vT/l_c) - 1. Lean proves it inside s5_solve_crossing, which therefore also states that the nonpositive case gives r* = 0. Also: the hypothesis eta_0 < 1 is never used; the result holds for every eta_0 > 0. Suggested edit: after ''The bracket decreases strictly to a negative limit'' add ''and at zero it has the sign of eta_0(1 + vT/l_c) - 1''; nothing else is needed.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the existence of the crossing and the link to the positive part (F12.1, F12.2).', '2026-11-14T16:01:45');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F13', 'C11', 'C11/p1/s2', 'minor', 'Two-sensor example: best estimate taken to be the conditional mean, and the use of process independence when conditioning on both old readings is left unsaid', 'What the Lean proof C11/a1 needed that the paragraph at main 66-86 does not say. The hypotheses are all stated (independent, mean-zero, stationary processes; the scalar prediction rule); what is missing is where they are used. (1) ''Our best estimate is X_t/2'' and ''our best estimate today is then ...'' use that the conditional mean attains the smallest mean squared error among square-integrable functions of the observation. The example neither argues nor cites it; the appendix proves the general fact (C3, common information). In Lean it is Routine/Estimation.lean, bestMSE_eq_of_condExp, a judgment call: when C3 has a Lean statement this should become a use of C3. (2) Step 1 does not say why X_t/2 is the conditional mean: E[Y_t | X_t] = 0 by independence and mean zero. (3) Step 2 gives E[X_t | X_{t-tau}] and concludes about the best estimate from both old readings. That needs E[X_t | X_{t-tau}, Y_{t-tau}] = E[X_t | X_{t-tau}], which holds because (X_t, X_{t-tau}) is independent of Y_{t-tau}. This is where ''the two signal processes are independent'' (line 74) is used, and it has to be independence of the processes: independence of X_s and Y_s at each single time would not be enough. Mathlib has no lemma for this; Routine/Estimation.lean proves it (condExp_sup_of_indep, about 70 lines). (4) The error Var(Z_t)(1 - e^{-2 tau/T}) is asserted; Lean derives it from orthogonality, stationarity of each process with their independence, and mean zero. (5) Var(Z_t) = sigma^2/2 uses E[X_t Y_t] = 0. Suggested edit: one sentence after the prediction rule, ''Because the processes are independent, the old reading of one does not help predict the other, so the conditional mean of Z_t given both old readings is e^{-tau/T} Z_{t-tau}.'' Hypothesis 0 <= tau is unused.
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F14', 'C12', 'C12/p1/s7', 'minor', 'Aggregate-coupling proof: ''subtracting'' relies on completing the square, and the full-information cost hides three steps', 'What the Lean proof C12/a1 needed that the proof at main 591-613 does not say. (1) Step 7 ''subtracting'' turns expected-cost differences into regrets. That is the completed-square identity (1/2) E[(u - x*)'' Q (u - x*)] = E f(u, theta) - E f(x*, theta), claim C5, which the step does not cite. In Lean C5 is a hypothesis of steps 6 and 7 and of main; step_deps for step 7 now lists C5. C5 itself has no proof in the paper yet. (2) Step 6 ''therefore'' hides: f(x*, theta) = -(1/2) x*'' Q x* (C5 at x = 0); the explicit x* = Q^{-1} theta (Eq. (shared_resource_xstar), stated before the proposition without proof); and E[(sum theta_i)^2] = n sigma^2, which uses independence, zero means and equal variance. ''Multiplicity n-1'' is used as the eigenspace {v : sum v_i = 0}; the paper presumably intends E[theta'' Q^{-1} theta] = sigma^2 tr Q^{-1}, and Lean reaches the same number by decomposing theta along the two eigenspaces, without a trace. (3) Step 2: the cross terms between means and centered parts vanish because E[u~_i] = 0 (step 1), not for the two reasons named; independence of u~_i and u~_j also needs each u~_i to be a function of theta_i alone. The expansion of the cost at u = mean + centered part is in Routine/Aggregate.lean (aggCost_split) as a ring identity. (4) The statement''s ''the rule attains R_loc'' is proved in step 7, since it needs the bridge in (1); the paper''s steps 4-5 establish optimality in cost terms. (5) As noted under F2, the state assumptions (independent, mean zero, equal variance) are in the paragraph before the proposition, not in its statement. Suggested edit: in the last sentence write ''Subtracting, by Eq. (complete_square), gives ...''.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the three arguments inside the step lemmas, and completing the square is proved from the supplement proof C5/p1 (F14.1 to F14.3).', '2026-11-14T16:11:09');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F15', 'C2', NULL, 'minor', 'Normal equations: the block form is asserted as equivalent without argument, and the justification leaves its conditional-expectation steps unsaid', 'What the Lean proof C2/a1 needed that the corollary and its justification (appendix 220-269) do not say. (1) ''With Q partitioned into action blocks, this is equivalently'' Eq. (block_conditional_normal_equations): the justification has no step for it. It needs linearity of conditional expectation over (Qu)_i, and E[u_i | G_i] = u_i, which uses that u_i is G_i-measurable, i.e. u in S(A); for a u outside S(A) the two forms are not equivalent. In Lean it is Routine/NormalEq.lean, normalEquations_iff_block, used in main, and the statement restricts the equivalence to members of S(A). (2) Step 1 ''differentiating expected quadratic cost at the optimum'' uses the expansion E[f(u*+h) - f(u*)] = E[h''(Qu* - b)] + (1/2) E[h''Qh], which the text displays only two sentences later, and uses that the projection of the lemma is optimal (C1) and that u* + t h is admissible (linearity of S(A)); neither is cited. (3) Step 2 ''conditional expectation then gives'': the content is that E[1_A g] = 0 for every A in G_i characterizes E[g | G_i] = 0. Lean uses indicator perturbations on one coordinate, a special case of ''an arbitrary square-integrable function of its observations''. (4) Step 3 does not say why the equations make the linear term vanish: E[h_i''(Qu - b)_i] = E[h_i'' E[(Qu - b)_i | G_i]], the tower property with h_i pulled out, which uses that h_i is G_i-measurable. In this converse direction u* denotes any admissible solution of the equations, not yet known to be the optimum. (5) Step 3 is listed as using C5 (completing the square); the displayed expansion is a ring identity for f and Lean does not use C5. Decision needed: drop C5 from step_deps of C2/p1/s3. (6) Not in the Lean statement: ''one generally does not have u_i* = E[x_i* | G_i]''. The paper gives no example here; the aggregate-coupling model (C12) is one. Suggested edit: after Eq. (block_conditional_normal_equations) add ''because u_i is G_i-measurable and conditional expectation is linear'', and in step 3 ''by the tower property, since h_i is G_i-measurable''.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the block-form equivalence, the tower-property step and the indicator argument; the order of presentation is left (F15.1 to F15.4). Not sent to the co-author as a request.', '2026-11-14T16:50:34');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F16', 'C3', 'C3/p1/s2', 'minor', 'Common-information paragraph: ''the error expansion'' has no stated referent, and the link to it needs Q x* = b', 'What the Lean proof C3/a1 needed that the paragraph (appendix 271-276) does not say. (1) ''The error expansion then proves'' does not say which expansion. Two readings work: Eq. (complete_square) followed by expanding ||u - x*||_Q^2 around m (uses C5, as the ledger''s step_deps lists), or the display in the justification of the normal equations, E[f(m+h) - f(m)] = E[h''(Qm - b)] + (1/2) E[h''Qh]. Lean uses the second, through the routine lemma expectedCost_add, so C3 does not depend on C5. Decision needed: drop C5 from step_deps of C3/p1/s2 and from the claim''s dependencies, or keep the first reading. (2) Step 1 gives E[h''Q(x* - m)] = 0 while the linear term of the expansion is E[h''(Qm - b)]; they agree up to sign because Q x* = b, which the paragraph does not say. (3) That m is admissible (sigma(Z)-measurable and square-integrable) is not stated; it is the first conjunct of the Lean statement. (4) Uniqueness uses ''positive definiteness makes the remaining term positive'', stated for the corollary and not repeated, and writing a competitor as m + h uses linearity of S(A) from the lemma. Suggested edit: ''The expansion in the justification of Corollary (conditional_normal_equations), with Q x* = b, then proves ...''.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: ''the error expansion'' is read as the display in the justification of the normal equations, and Lean supplies the two unstated links (F16.1 to F16.3). Not sent to the co-author as a request.', '2026-11-14T16:50:34');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F17', 'C1', 'C1/p1/s4', 'minor', 'Projection lemma: the projection step rests on the uncited norm-equivalence remark, existence is implicit, and the lemma is conditional on completing the square', 'What the Lean proof C1/a1 needed that the proof at appendix 181-214 does not say. (1) Step 4, ''the standard Hilbert-space projection problem'', needs S(A) to be closed, hence complete, for the Q-norm, while step 2 argues closedness for the ordinary L2 norm (''an L2 limit ...''). The bridge is the sentence before the lemma, ''Since Q > 0, the induced norm is equivalent to the ordinary L2 norm'' (appendix 145), which is asserted without proof and not cited in the proof. Lean uses one direction, sum_c v_c^2 <= C v''Qv (Routine/QHilbert.lean, exists_sum_sq_le_quad, from finite dimension), and completeness of L2 over R^d with the Q inner product. (2) The lemma says ''the unique optimal policy ... is Pi x*'': existence of the projection, and so of an optimal policy, is part of what the projection theorem delivers and is not stated separately; the Lean statement has it as its own conjunct. (3) Uniqueness up to a.s. equality uses ||u - p||_Q = 0 => u = p a.s. (positive definiteness), and the regret value uses the Pythagorean identity ||u - x*||_Q^2 = ||u - p||_Q^2 + ||p - x*||_Q^2 for u in S(A); both are inside ''standard''. (4) Step 3 cites Eq. (complete_square), claim C5, which has no proof in the paper, so C1 and C2 are conditional on C5 in the assembly. Step 3 also needs E||b||^2 < infinity and E|c| < infinity for the two expected costs to be finite and subtractable; the appendix assumes both at line 39. (5) The orthogonality sentence after the proof (C1.b, first half) is the defining property of the projection in the Lean statement. Suggested edit: in step 4, ''By the norm equivalence above, S(A) is also closed for the Q-norm, so minimizing ...''.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the norm-equivalence step, and existence of the projection is its own part of the Lean statement (F17.1, F17.2). Not sent to the co-author as a request.', '2026-11-14T17:54:55');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F18', 'C19', NULL, 'minor', 'Canonical field: sigma^2 > 0 is not assumed, and the unique-optimum claim fails at sigma^2 = 0', 'Raised by the ChatGPT review that Bhaskar relayed on 2026-11-14, not by the formalization. If sigma^2 = 0 the field and the target vanish, every radius has zero regret, and the theorem''s ''unique'' optimal radius is false as stated. The canonical model should say sigma^2 > 0. The same edit fixes the strict comparison in the two-sensor example (C11), which needs ''variance sigma^2 > 0'' (memo section 5). The Lean statement C19/f1 did not expose this because it is the algebraic form and never mentions the field; C11/f1 already assumes sigma > 0. The tier D statements must carry the hypothesis.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): sigma^2 > 0 is stated in the two-sensor example (main-v3.tex 68), the canonical model paragraph (815), the lemma (875) and the theorem (902).', '2026-11-14T18:28:55');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F19', 'C17', NULL, 'minor', 'Canonical model: the main text does not say which version of the field is integrated and observed; the appendix assumes a continuous one', 'Raised on 2026-11-14 when the tier D definitions were written. The target x*(z,t) is an integral of the field over the line and the observation O_r(z,t) is the field on an interval. Both need more than a covariance: sample paths that can be integrated, and a sigma-algebra for a continuum of values. The appendix proof of the lemma says ''We use a continuous version of the field; observations on an interval can equivalently be generated by a countable dense subset''. The main text (the model paragraph, the composition paragraph, the lemma and the theorem) does not say it. Lean puts ''every sample path is continuous in the location'' into the definition of the canonical field (CanonicalField.continuous), so it is a hypothesis of C17.b, C18 and C19, and takes the observation to be the path on [-r, r] with the product sigma-algebra. Two ways to settle it: leave the paper and record this as the reading, since the hypothesis is in the appendix; or add ''we use a version with continuous sample paths'' to the model paragraph.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: the canonical field is read as a version with continuous sample paths in the location, as the appendix says for the lemma, recorded on the Lean statement (F19.1, C17/f1/d2). A sentence in the model paragraph is an optional suggestion for the co-author.', '2026-11-14T19:06:26');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F2', 'C12', NULL, 'minor', 'Two different derivations of the optimal local rule', 'The main-text proof (C12/p1) finds theta_i/(q+gamma) by a centered decomposition and pointwise minimization; the appendix (C12/p2), introduced as ''the matrix arithmetic'', re-derives it from the coupled normal equations. Under the 1:1 rule one derivation must be the proof Lean mirrors. C12/p1 is marked primary for now; p2 additionally needs C2 and C1.b (tier C). Decision needed: keep both (and formalize both) or reduce the appendix to the arithmetic.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: the appendix derivation is kept as the secondary proof C12/p2 (F2.1) and the state assumptions are read from the paragraph before the proposition (F2.2).', '2026-11-13T13:26:00');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F20', 'C17.b', NULL, 'minor', 'Continuum composition paragraph: two sentences rest on arguments about laws and sigma-algebras that are not written', 'From the Lean proof of C17.b (2026-11-14). (1) Step 3, ''Integrating against the decision kernel and conditioning on the observed interval gives ...'': this needs that the kernel integral of the innovation field is a function of the innovation field (so that step 2 makes it independent of the observed interval), that the observed interval is part of the field at time t - tau, and that the integral has mean zero. (2) Step 5, ''By stationarity, the conditional mean at time t - tau has the same variance as its fresh-snapshot counterpart at time t'': the model gives a covariance, not stationarity of laws. The argument is that the spatial field at each time is Gaussian with the same mean and covariance, hence has the same law, and that the target and the observation are the same function of that field at both times, so their joint law is the same. Both are standard; neither changes what is claimed.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the measurability and independence argument for step 3 and the equality of laws for step 5 as routine lemmas (F20.1, F20.2).', '2026-11-14T19:18:58');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F21', 'C18', 'C18/p1/s4', 'minor', 'Canonical omission lemma: the Markov property and three Gaussian-conditioning facts are cited, not argued', 'From the Lean proof of C18 (2026-11-14). (1) Step 3 takes the spatial Markov property from ''the exponential-covariance model''; the main text cites a reference. Lean needs the argument: beyond each endpoint the field is the endpoint value times e^{-beta_s s} plus a residual field that is uncorrelated with, hence (jointly Gaussian) independent of, everything on the other side. This is written as the supplied step C18/p1/s3b. (2) Step 0 says the conditional variance given O_r is a deterministic number because ''the Gaussian conditional covariance is independent of the observed values''; here the conditioning is on a continuum of values. Lean keeps the expectation E[Var(x* | O_r)] in Step 0 and gets constancy from the supplied step. (3) Step 4 says ''shifting the field by r does not change its law, so Var(Y_r | theta(r)) = C''. Lean does not use an equality of laws: the conditional variance is the variance of the integrated residual field, a double integral of second moments that involve neither the endpoint nor the side. (4) Step 5 applies the two-variable Gaussian conditioning formula to x*(0) and theta(0); that x*(0), an integral of the field, is jointly Gaussian with theta(0) is not argued. Lean uses the supplied step at r = 0: x*(0) = rho theta(0) + W with W independent of theta(0). None of this changes what is claimed.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: Lean supplies the proof of the spatial Markov property as the supplied step C18/p1/s3b and the three Gaussian-conditioning arguments inside the step lemmas (F21.1-F21.4).', '2026-11-14T19:33:03');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F3', 'C9', NULL, 'medium', 'Unequal-rate formula has no proof and an informal hypothesis', 'The formula is asserted without proof, and ''the fraction of the no-information decision loss attributable to mode k'' is not defined (it needs the cross-mode terms of x*''Qx* to vanish, which independence of the modes provides once stated). A Lean statement needs a precise definition of w_k, and the 1:1 rule needs a written proof.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): main-v3.tex 473-490 calls the modes centered, writes x* = sum_k x_k* with x_k* = K_k theta^(k), defines w_k = E[(x_k*)^T Q x_k*] / E[(x*)^T Q x*] for R_inf > 0, and derives the formula in three sentences, recorded as the in-paper proof C9/p1. C9 has no Lean statement yet; that is formalization work, not a point about the paper.', '2026-11-13T13:26:00');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F4', 'C10', 'C10/p1/s2', 'minor', 'Crossover proof does not mention the eta_S(0) = 1 clause', 'The theorem states that for eta_S(0) = 1 no finite delay gives a strict local advantage, but the theorem''s hypothesis is 0 <= eta_S(0) < 1 and the proof (''Rearranging gives the threshold and equality case'') covers only that range. The Lean statement has to either drop the clause or prove it as a separate step, which then needs a sentence in the paper.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): main-v3.tex 499-507 assumes R_inf > 0 and puts 0 <= eta_S(0) < 1 on the finite-threshold branch; the proof (510-514) gains ''For eta_S(0)<1, rearranging ...'' and the endpoint sentence, which is now the paper step C10/p1/s3 with its own lemma (s3_endpoint).', '2026-11-13T13:26:00');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F5', 'C8', NULL, 'minor', 'Stale-global is presented as a case of A_{r,tau}, which needs a radius that reaches every agent', 'Section ''What each agent observes'' lists stale-global among ''the three cases'' of A_{r,tau}, and the proof of C8 substitutes R(A_{r,0}) = 0 into the composition law for A_{r,tau}. On a disconnected graph no finite radius gives the complete view, and the paper only says ''the diameter of a finite connected graph gives a complete stale-global snapshot''. Lean draft: the radius ranges over N union {top}, top being the complete view, so R_glob = R(A_{top,tau}) and C7 covers it. Options for the paper: (a) say the radius may be ''complete'' (r = infinity); (b) assume G connected; (c) state C7 for arbitrary synchronized neighborhoods.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): the corollary is stated ''Under the tracking model and stationary transition'' and proved directly from Eq. innovation_split and Eq. innovation_energy with u = a K theta_{t-tau} (main-v3.tex 453-467; proof C8/p2, Lean attempt C8/a2). The graph model is unchanged, so no radius has to reach every agent. Lean keeps stale-global as radius top, the reading C8/f1/d1 (Scott, 2026-11-14).', '2026-11-13T14:16:11');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F6', 'C1.c', NULL, 'minor', 'Two definitions of admissible rule with no stated link', 'The main text defines an admissible rule as u_i = g_i(Z_i); the appendix as G_i-measurable u_i with G_i = sigma(Z_i), adding ''measurability here means that u_i can be computed from those observations''. C1.c is stated in the appendix form, and C6.c step s1 applies it to radius architectures defined in the main-text form. The link is the Doob-Dynkin lemma. Lean has both definitions (regret, sigmaRegret). Decision needed: treat regret Z = sigmaRegret sigma(Z) as a Routine lemma, or as a one-sentence claim in the appendix with its own step. README open decision 3.', 'resolved', 'Closed by Scott on 2026-11-15. The paper stays as written (disposition F6.1). Lean proves the link as Model.R_eq_sigmaRegret in Routine/RadiusInfo.lean: for the finite-dimensional radius observations, the regret over rules u_i = g_i(Z_i) equals the regret of the architecture G_i = sigma(Z_i) (Doob-Dynkin). No proof uses it: the monotonicity step of C6.c is proved directly in the main text''s form, so no appendix fact is applied to main-text rules there.', '2026-11-13T14:16:11');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F7', 'C4', NULL, 'minor', 'Which stationarity the assumption means, and R(A_{r,tau}) written without the epoch', 'The assumption says ''a stationary state process''. The proof of C7 uses only that theta_{t-tau} and theta_t have the same law (the paper: ''Stationarity supplies the same one-time distribution at the two epochs''). Lean draft assumes equality of one-time laws for all pairs of times, which strict stationarity implies. Under that weaker hypothesis R(A_{r,tau}) can depend on the epoch t when tau > 0 before the theorem is applied, so the Lean statements carry t explicitly. Decision needed: keep the weaker hypothesis (and optionally say so in the paper) or define strict stationarity of the process.', 'resolved', 'Closed 2026-11-14 by Scott. The paper stays: stationarity is read as equality of one-time laws, recorded on the Lean statements (F7.1).', '2026-11-13T14:16:11');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F8', 'C15', NULL, 'minor', 'Continuous-radius results are stated ''under Theorem C7'' but eta_S and tau are functions of a real radius', 'C14 defines G on graph radii. C15, its two remarks (C15.b, C15.c) and C16 then treat eta_S(r) and tau(r) as continuously differentiable functions of r in [0, D] and speak of the ''optimal radius'', while the model of C6/C7 only defines eta_S at integer radii. Lean draft states these four claims as real analysis about G(r) = (1 - eta(r)) exp(-2 tau(r)/T) for given curves eta, tau, with ''optimal'' meaning ''maximizes G''. The paper could say this in one sentence before C15 (e.g. ''for an omission curve eta_S and delay curve tau defined for real r, with R(r) := R_inf [1 - G(r)]''). For the canonical model the paragraph added by upstream 284a0e0 (C17.b) now supplies R(r) = R_inf [1 - G(r)]. Related to F1 (resolved) and F10.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): main-v3.tex 698 opens the section with ''Assume R_inf > 0 throughout this section'', and both propositions open with ''Suppose R(r)=R_inf[1-G(r)] for real r ...'' (733-736, 773-778) in place of ''Under Theorem''. That is the form the Lean statements of C15, C15.b, C15.c and C16 have.', '2026-11-13T14:16:11');
INSERT INTO findings (id, claim_id, step_id, severity, title, body, status, resolution, created) VALUES ('F9', 'C4.b', NULL, 'minor', 'AR(1) remark does not say what the innovations are independent of', '''Independent, mean-zero finite-variance innovations'' can mean an independent sequence, or innovations independent of the past of the state. The prediction coefficient c^k needs each innovation xi_u to be independent of the earlier states theta_s, s < u (true for the causal stationary solution driven by an independent sequence, but that is an argument). Lean draft assumes independence from earlier states directly. Since C4.b has no proof in the paper, the appendix proof to be added should fix the reading.', 'resolved', 'Closed 2026-11-18 by Scott. Settled by arXiv v3 (upstream 12a9b32): the main text says ''finite-variance innovations, each with mean zero conditional on the past states'' (main-v3.tex 359-361); the appendix defines F_{t-1} = sigma(theta_s : s <= t-1), assumes E[eps_t | F_{t-1}] = 0 and gives the argument (technical-appendices-v3.tex 313-320). The Lean statement C4.b/f2 carries that hypothesis.', '2026-11-13T14:16:11');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C1.b/d1', 'C1.b', NULL, 1, 'Q-orthogonality of the projection error and the Pythagorean form have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Derive the identity from the Hilbert-space projection theorem. No new proof in the paper.', 'done', NULL, 'C1.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C1.c/d1', 'C1.c', NULL, 1, 'Information inclusion has no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the feasible-set inclusion once and reuse it. No new proof in the paper.', 'done', NULL, 'C1.c/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C10.b/d1', 'C10.b', NULL, 1, 'The two sentences after the crossover theorem (zero threshold at eta_S(0) = 0, a single crossing otherwise) have no argument.', 'proof', 'lean_supplies', 'Scott', '2026-11-19', 'Both follow from the crossover theorem once its equality case is an equivalence (C10/f2). The paper stays as written.', 'done', NULL, 'C10.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C13.b/d1', 'C13.b', NULL, 1, 'The large-n limit of the threshold and the local share have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove as a limit of the closed forms.', 'done', NULL, 'C13.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C13.c/d1', 'C13.c', NULL, 1, 'The behaviour of the threshold in the coupling strength has no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove from the closed forms, and distinguish strict from weak monotonicity in degenerate cases such as n = 1.', 'done', NULL, 'C13.c/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C13/d1', 'C13', NULL, 1, 'The explicit aggregate-coupling threshold and the equivalence after it have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove as an algebraic corollary of the existing formulas.', 'done', NULL, 'C13/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C15.b/d1', 'C15.b', NULL, 1, 'That single crossing gives the unique optimum has no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the boundary and interior cases on [0, D] from the sign of (log G)''. The present wording already allows the optimum to sit at a boundary.', 'done', NULL, 'C15.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C15.c/d1', 'C15.c', NULL, 1, 'The comparative statics in T and in the latency scale have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the weak movement of the optimum as T or the latency scale changes, from the sign of (log G)''.', 'done', NULL, 'C15.c/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C20/d1', 'C20', NULL, 1, 'The large-l_c limit of the canonical radius has no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove as a limit of the closed form, keeping the paper''s positive-radius condition.', 'done', NULL, 'C20/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C4.b/d1', 'C4.b', NULL, 1, 'That a stationary AR(1) state satisfies the prediction rule has no argument.', 'proof', 'paper_edit', 'Bhaskar (arXiv v3, upstream 12a9b32)', '2026-11-18', 'The paper now gives the argument: arXiv v3 added ''Iterating the recursion over k steps ... by the tower property'' to the appendix (technical-appendices-v3.tex 316-320), recorded as the in-paper proof C4.b/p1. Until then the decision (review relayed 2026-11-14) was that Lean supplies it; no supplement proof had been written.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C4.c/d1', 'C4.c', NULL, 1, 'That the Gaussian Ornstein-Uhlenbeck state satisfies the prediction rule has no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the prediction rule for a jointly Gaussian process with the stated exponential covariance. The paper keeps the stochastic-differential-equation description. If the step from the equation to the covariance stays outside the formalization, that boundary is recorded as a difference on the Lean statement when C4.c is stated.', 'done', NULL, 'C4.c/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C5/d1', 'C5', NULL, 1, 'Completing the square and uniqueness of the minimizer are stated without argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the quadratic identity once and reuse it downstream. It has to be discharged before the aggregate-coupling result (C12) and the projection results (C1, C2) count as complete.', 'done', NULL, 'C5/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C6.b/d1', 'C6.b', NULL, 1, 'That the best no-information action is zero, and the trace formula for R_inf, have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Derive from the centered quadratic model. The paper stays as written.', 'done', NULL, 'C6.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C6.c/d1', 'C6.c', NULL, 0, 'The range 0 <= eta_S(r) <= 1 has no argument (the monotonicity clause has one).', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Derive from the centered quadratic model: regret is nonnegative and the zero rule is admissible. This is a supplied step in the paper''s proof C6.c/p1.', 'done', 'C6.c/p1/s0a', NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C7.b/d1', 'C7.b', NULL, 1, 'The normalized composition law has no argument beyond ''normalization is valid''.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Divide the law by R_inf and substitute the definition of eta_S. The paper stays as written.', 'done', NULL, 'C7.b/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C8.b/d1', 'C8', NULL, 0, 'That the optimal stale-global action is a K theta_{t-tau} has no argument.', 'proof', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Update the stale-global corollary''s proof by one sentence, using the innovation split directly so that it also covers disconnected graphs. This is the same edit as F5.1. Carried out in arXiv v3: the separate sentence ''The optimal global action is a K theta_{t-tau}'' was deleted and the action is the first sentence of the corollary''s proof. On 2026-11-18 Scott merged claim C8.b into C8; this row keeps its id and now points at C8. The fact is stated and proved by the step lemmas of C8/a2: s1_action_feasible (the action is admissible) and s2_half_innovation_energy (its cost is R_glob).', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C8.c/d1', 'C8.c', NULL, 1, 'The small-delay expansion and the large-delay limit of R_glob have no argument.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Derive from the closed form. The paper stays as written.', 'done', NULL, 'C8.c/p1', NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C9/d1', 'C9', NULL, 0, '''Write x* = sum_k x_k*'' is notation: with modes P_k theta and sum_k P_k = 1 it is a one-line fact, which the Lean statement lists as its first conclusion.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-19', '2026-11-19', 'Supplied as step 0: theta = sum_k P_k theta and linearity of K.', 'done', 'C9/p1/s0', 'C9/p1', 'TinaV2/Proofs/C09/A1.lean::s0_decomposition', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C9/d2', 'C9', NULL, 0, 'Step 2 says the complete old snapshot predicts mode k''s contribution as exp(-tau/T_k) x*_{k,t-tau}. That the innovation of mode k has conditional mean zero given the whole snapshot, not only given the mode''s own old value, is not argued.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-19', '2026-11-19', 'Supplied as step 2a: C4.c for the mode, independence of the mode''s path from the other modes'' paths, and the tower property.', 'done', 'C9/p1/s2a', 'C9/p1', 'TinaV2/Proofs/C09/A1.lean::s2a_whole_snapshot', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('C9/d3', 'C9', NULL, 0, '''Captured quadratic gain'' presumes that the regret of the complete old snapshot is R_inf minus half the gain of the conditional-mean prediction. The paper does not say so in this paragraph.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-19', '2026-11-19', 'Supplied as step 2b: the expansion of the proof of the composition theorem (cross term zero for every rule that is a function of the snapshot), applied to the prediction x-hat = E[x*_t | theta_{t-tau}], which is an admissible rule of the complete snapshot.', 'done', 'C9/p1/s2b', 'C9/p1', 'TinaV2/Proofs/C09/A1.lean::s2b_regret_gain', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F1.1', 'C17.b', 'F1', 0, 'The canonical field used the finite-graph composition theorem without an argument of its own.', 'proof', 'paper_edit', 'Bhaskar', '2026-11-12', 'Joint Gaussianity stated and the field derivation added upstream.', 'done', NULL, NULL, NULL, NULL, '284a0e0');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F10.1', 'C19', 'F10', 0, 'The field derivation is an unlabelled paragraph that ends in words, so there is nothing to cite.', 'wording', 'leave', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'A new lemma is optional. The ledger treats the paragraph as claim C17.b with proof C17.b/p1.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F10.2', 'C19', 'F10', 0, 'The theorem''s proof does not say that the field derivation is what licenses the substitution.', 'proof', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Point back to the field derivation in the proof.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F10.3', 'C19', 'F10', 0, 'The lemma and the theorem identify the field only by its covariance; both proofs need joint Gaussianity.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Say ''jointly Gaussian field with sigma^2 > 0'' in the canonical statement (see also F18).', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F10.4', 'C19', 'F10', 0, 'Regret per unit length is said to be ''equal by stationarity to expected pointwise loss'', asserted and not needed.', 'wording', 'reading', 'Scott (not among the agreed edits; the paper stays)', '2026-11-14', 'The reply does not mention it. When the tier D statements are written, regret in the field model is the expected pointwise loss at a location.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F11.1', 'C19.b', 'F11', 0, 'Decrease in l_s: which pairs of points the statement compares.', 'statement', 'reading', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'The manuscript already restricts the strict decrease in l_s to the interior regime. The Lean statement is restricted to pairs that are both in the regime: C19.b/f2 (2026-11-18), with the reading recorded as C19.b/f2/d1. The draft C19.b/f1 stated and proved the wider claim.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F12.1', 'C16', 'F12', 0, 'That the bracket has a zero (''its unique crossing'') is not argued.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Adequate as written: the paper says the bracket decreases strictly to a negative limit. Lean proves existence inside the lemma for that step.', 'done', NULL, NULL, 'TinaV2/Proofs/C16/A1.lean::s4_positive_at_zero', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F12.2', 'C16', 'F12', 0, 'The link between the sign of the bracket at zero, the positive part in the boxed formula and the positivity criterion is not written.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Adequate as written. Lean uses a routine lemma on the closed-form radius.', 'done', NULL, NULL, 'TinaV2/Routine/ExpRadius.lean::expRadius_pos_iff', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F13.1', 'C11', 'F13', 0, 'The step from the conditional mean given one old reading to the best estimate from both does not say that independence of the processes is what allows it.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'The hypothesis in the text is the right one. A sentence would help an introductory reader but is optional.', 'done', NULL, NULL, 'TinaV2/Routine/Estimation.lean::condExp_comap_prodMk_of_indepFun_left', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F13.2', 'C11', 'F13', 0, '''Our best estimate'' uses that the conditional mean has the smallest mean squared error, without pointing to the appendix.', 'proof', 'lean_supplies', 'Scott', '2026-11-14', 'Decided 2026-11-14: treated as a standard fact and kept as a routine lemma; C11 is not rewired to use C3.', 'done', NULL, NULL, 'TinaV2/Routine/Estimation.lean::bestMSE_eq_of_condExp', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F13.3', 'C11', 'F13', 0, 'The error Var(Z_t)(1 - exp(-2 tau/T)) is asserted.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Not addressed in the reply. It follows from orthogonality of the prediction error, stationarity and zero means; Lean proves it inside the lemma for that step.', 'done', NULL, NULL, 'TinaV2/Proofs/C11/A1.lean::s2_old_readings', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F14.1', 'C12', 'F14', 0, '''Subtracting this cost'' turns a difference of expected costs into regret, which is completing the square, uncited.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'The proof is valid as written. The step lists C5 as a dependency, and C5 is proved from the supplement proof C5/p1, so C12 assumes nothing.', 'done', NULL, NULL, 'TinaV2/Proofs/C12/A1.lean::s7_subtract_and_ratio', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F14.2', 'C12', 'F14', 0, '''The full-information expected cost is therefore'' hides three facts between the eigenvalues and the number.', 'proof', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'The proof could be clearer with the single identity E f(x*, theta) = -(sigma^2/2) tr(Q^{-1}); optional. Lean gets the number by splitting theta along the two eigenspaces.', 'done', NULL, NULL, 'TinaV2/Proofs/C12/A1.lean::s6_eigen_full_info_cost', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F14.3', 'C12', 'F14', 0, 'The reason given for the vanishing cross terms between the means and the centered parts is not the one that applies.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Not addressed in the reply. Lean uses E[u~_i] = 0 for those terms, and independence with zero state means for the others.', 'done', NULL, NULL, 'TinaV2/Proofs/C12/A1.lean::s2_centered_cost', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F15.1', 'C2', 'F15', 0, 'The block form of the normal equations is called equivalent with no argument.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'It holds for admissible u by linearity of conditional expectation and E[u_i | G_i] = u_i. Section 8 of the memo was not sent as a request; it goes to the co-author as information only.', 'done', NULL, NULL, 'TinaV2/Routine/NormalEq.lean::normalEquations_iff_block', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F15.2', 'C2', 'F15', 0, '''Conversely, these conditional equations make the linear term vanish'' does not say it is the tower property with the G_i-measurable h_i taken out.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Proved inside the lemma for that step. Section 8 of the memo was not sent as a request; it goes to the co-author as information only.', 'done', NULL, NULL, 'TinaV2/Proofs/C02/A1.lean::s3_linear_term_vanishes', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F15.3', 'C2', 'F15', 0, '''Differentiating expected quadratic cost at the optimum'' uses the expansion displayed two sentences later.', 'wording', 'leave', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Order of presentation only; the memo itself says it may be fine as it is.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F15.4', 'C2', 'F15', 0, '''Conditional expectation then gives'' leaves out that vanishing against every indicator of G_i means the conditional expectation is zero.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Lean uses indicator perturbations on one coordinate, a special case of the paper''s arbitrary square-integrable function. Section 8 of the memo was not sent as a request; it goes to the co-author as information only.', 'done', NULL, NULL, 'TinaV2/Proofs/C02/A1.lean::s2_conditional_equations', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F16.1', 'C3', 'F16', 0, '''The error expansion'' has no stated referent.', 'proof', 'reading', 'Scott', '2026-11-14', 'Decided 2026-11-14: read as the display in the justification of the normal equations, so the paragraph does not depend on completing the square. Section 8 of the memo was not sent as a request; it goes to the co-author as information only.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F16.2', 'C3', 'F16', 0, 'The orthogonality in the preceding sentence and the linear term of that display agree only through Q x* = b, which is not said.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Proved inside the lemma for that step.', 'done', NULL, NULL, 'TinaV2/Proofs/C03/A1.lean::s2_unique_optimum', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F16.3', 'C3', 'F16', 0, 'That m is itself admissible is used and not stated.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Proved in the lemma for the first step and stated as the first part of the Lean statement.', 'done', NULL, NULL, 'TinaV2/Proofs/C03/A1.lean::s1_conditioning', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F17.1', 'C1', 'F17', 0, 'The projection step needs closedness for the Q-norm; the proof shows it for the ordinary L2 norm and does not cite the norm-equivalence remark.', 'proof', 'lean_supplies', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'Lean uses one direction of the equivalence, |v|^2 <= C v''Qv. Section 8 of the memo was not sent as a request; it goes to the co-author as information only.', 'done', NULL, NULL, 'TinaV2/Routine/QHilbert.lean::isClosed_qSubmodule', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F17.2', 'C1', 'F17', 0, '''The unique optimal policy is the projection'' takes for granted that an optimal policy exists.', 'statement', 'reading', 'Scott (rule: proof-level gaps are supplied)', '2026-11-14', 'The Lean statement lists existence as its own part; the projection theorem supplies it.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F18.1', 'C19', 'F18', 0, 'The canonical field statement does not assume sigma^2 > 0.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Say ''jointly Gaussian field with sigma^2 > 0'' (same edit as F10.3).', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F18.2', 'C11', 'F18', 0, 'The two-sensor example''s strict comparison needs variance sigma^2 > 0.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', '''variance sigma^2 > 0'' in the example; the review counts it with the canonical-field edit.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F19.1', 'C17', 'F19', 0, 'The main text does not say which version of the field is integrated and observed on an interval; the appendix says ''a continuous version'', for the lemma''s proof only.', 'statement', 'reading', 'Scott', '2026-11-14', 'Decided 2026-11-14 on Claude''s recommendation: reading. The appendix proof of the lemma already says ''we use a continuous version of the field'', so a reader can find the hypothesis in the manuscript. Lean assumes continuous sample paths in the location throughout the canonical model (CanonicalField.continuous), recorded as the difference C17/f1/d2. One sentence in the model paragraph would make it explicit; that goes to the co-author as an optional suggestion, not a request.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F2.1', 'C12', 'F2', 0, 'The appendix derives the optimal local rule a second time by a different route (coupled normal equations, Pythagorean identity).', 'proof', 'leave', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Both derivations are valid, and the appendix one shows how the general team-optimality conditions recover the explicit rule, so it stays. It is the secondary proof C12/p2; Lean mirrors the main-text proof C12/p1. This supersedes the 2026-11-13 plan to cut the appendix derivation.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F2.2', 'C12', 'F2', 0, 'The state assumptions (independent, mean zero, equal variance) are in the paragraph before the proposition, not in its statement.', 'statement', 'reading', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'They appear immediately before the proposition. The Lean statement takes them as hypotheses.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F20.1', 'C17.b', 'F20', 0, 'Step 3: that the integrated innovation is independent of the observed interval and has mean zero is not argued.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Routine regularity: measurability of an integral for the sigma-algebra of the integrated field (continuous paths), inclusion of sigma-algebras, expectation under the integral sign.', 'done', 'C17.b/p1/s3', NULL, 'TinaV2/Routine/CanonicalTime.lean::CanonicalField.stronglyMeasurable_innovation_integral', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F20.2', 'C17.b', 'F20', 0, 'Step 5: ''By stationarity'' needs equal laws of the spatial field at the two times and a transfer to the joint law of the target and the observation.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Standard: a Gaussian process is determined in law by its mean and covariance, and the target and the observation are one function of the spatial field. Lean proves both as routine lemmas and uses them inside the lemma for the step.', 'done', 'C17.b/p1/s5', NULL, 'TinaV2/Routine/ProcessLaw.lean::identDistrib_integral_prodMk', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F21.1', 'C18', 'F21', 0, 'Step 3: the spatial Markov property is taken from the covariance model without an argument.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Standard for the exponential covariance. Lean proves it from a residual decomposition, written as a supplied step.', 'done', 'C18/p1/s3b', NULL, 'TinaV2/Proofs/C18/A1.lean::s3b_residual_fields', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F21.2', 'C18', 'F21', 0, 'Step 0: ''the conditional variance is a deterministic number'' is cited for a conditioning on a continuum of field values.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Lean''s Step 0 keeps the expectation of the conditional variance, which is what the regret is; that each conditional variance is constant follows from the supplied step where it is used.', 'done', 'C18/p1/s1', NULL, 'TinaV2/Proofs/C18/A1.lean::s1_variance_ratio', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F21.3', 'C18', 'F21', 0, 'Step 4: ''shifting the field by r does not change its law, so Var(Y_r | theta(r)) = C'' is not argued.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Lean shows the conditional variance is the variance of the integrated residual field, whose second moments do not involve the endpoint or the side; no equality of laws is needed.', 'done', 'C18/p1/s5', NULL, 'TinaV2/Routine/CanonicalSpace.lean::CanonicalField.integral_sq_lineE', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F21.4', 'C18', 'F21', 0, 'Step 5: the two-variable Gaussian conditioning formula is applied to x*(0) and theta(0) without saying why they are jointly Gaussian.', 'proof', 'lean_supplies', 'Rule for proof-level gaps (README, ''When Lean cannot follow the paper''); recorded by Claude 2026-11-14', '2026-11-14', 'Lean uses the supplied step at r = 0 instead: x*(0) is a multiple of theta(0) plus an independent term. The step also needs Var x*(0) > 0, which is sigma != 0 (F18).', 'done', 'C18/p1/s6', NULL, 'TinaV2/Proofs/C18/A1.lean::s6_eta_zero', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F3.1', 'C9', 'F3', 1, 'The weights w_k are undefined and the unequal-rate formula has no proof.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Define w_k = E[(x_k*)'' Q x_k*] / E[(x*)'' Q x*] with x_k* = K_k theta^(k), and add a one-sentence derivation: independence and centering kill the cross-mode terms, and mode k''s captured gain scales by exp(-2 tau/T_k). The review calls this the most useful expository edit.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F4.1', 'C10', 'F4', 0, 'The theorem assumes eta_S(0) < 1 and then makes a claim about eta_S(0) = 1, which the proof does not cover.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Assume R_inf > 0 throughout, put eta_S(0) < 1 on the finite-threshold branch, and add the endpoint sentence (at eta_S(0) = 1 fresh-local regret is R_inf and stale-global is strictly smaller at every finite delay). Until the edit is upstream the case is argued inside the main theorem of C10/a1; at realignment it becomes a paper step with its own lemma.', 'done', NULL, NULL, 'TinaV2/Proofs/C10/A1.lean::s3_endpoint', NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F5.1', 'C8', 'F5', 0, 'Stale-global is listed as a case of A_{r,tau}, which needs a radius reaching every agent; on a disconnected graph there is none.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Prove the corollary directly from the innovation split: with a complete old snapshot choose u = a K theta_{t-tau}; the predictable-error term is zero and the innovation term gives the regret. This leaves the graph model unchanged (it is not the r = infinity option the memo recommended). When it is upstream C8 gets a new proof version and the optimal-action remark C8.b is part of it.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F6.1', 'C1.c', 'F6', 0, 'Rules are functions of the observation in the main text and sigma-algebra-measurable random variables in the appendix; the two are never linked.', 'statement', 'lean_supplies', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'For the finite-dimensional observations here the two formulations agree, so the paper stays. Lean proves the link (Doob-Dynkin) as a supplied step where an appendix fact is applied to main-text rules: C1.c and the monotonicity step of C6.c.', 'done', NULL, NULL, 'TinaV2/Routine/RadiusInfo.lean::R_eq_sigmaRegret', NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F7.1', 'C4', 'F7', 0, 'Which stationarity the assumption means, and R(A_{r,tau}) written without the epoch.', 'statement', 'reading', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Stationarity supplies exactly the equality of one-time laws used in the proof. Lean assumes that and carries the epoch t.', 'done', NULL, NULL, NULL, NULL, NULL);
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F8.1', 'C15', 'F8', 0, 'The continuous-radius results open with ''Under Theorem'', but the theorem is about integer graph radii.', 'statement', 'paper_edit', 'Bhaskar (ChatGPT review relayed 2026-11-14)', '2026-11-14', 'Introduce the continuous propositions as results for given curves satisfying R(r) = R_inf [1 - G(r)], and keep the existing integer-radius discussion. This is the form the Lean statements of C15, C15.b, C15.c and C16 already have. R_inf > 0 for the section goes with the F4 edit.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO dispositions (id, claim_id, finding_id, whole_proof, point, level, decision, decided_by, decided_on, rationale, status, step_id, proof_id, lean_ref, edit_id, resolved_commit) VALUES ('F9.1', 'C4.b', 'F9', 0, 'The AR(1) remark does not say what the innovations are independent of.', 'statement', 'paper_edit', 'Bhaskar (arXiv v3, upstream 12a9b32)', '2026-11-18', 'Settled in arXiv v3 without a further message: the main text says ''finite-variance innovations, each with mean zero conditional on the past states'' (main-v3.tex 359-361) and the appendix defines F_{t-1} = sigma(theta_s : s <= t-1) and assumes E[eps_t | F_{t-1}] = 0 (technical-appendices-v3.tex 313-316). This is the second of the two wordings the review had mentioned. The Lean statement C4.b/f2 carries exactly this hypothesis; independence is no longer assumed.', 'done', NULL, NULL, NULL, NULL, '12a9b3265fec20d55c9e630fbeee1016f3fca3c1');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F10.3', 'C18', 'The lemma identifies the field by its covariance only; ''jointly Gaussian'' is to be added to the canonical statement.');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F18.1', 'C18', 'sigma^2 > 0 is to be added to the canonical statement; the Lean lemma already assumes sigma != 0.');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F8.1', 'C14', 'R_inf > 0 for the section goes with the F4 edit (F8.1 rationale); the Lean statement already assumes it.');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F8.1', 'C15.b', 'The edit rewrites the sentence that introduces the continuous-radius results.');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F8.1', 'C15.c', 'The edit rewrites the sentence that introduces the continuous-radius results.');
INSERT INTO disposition_scope (disposition_id, claim_id, note) VALUES ('F8.1', 'C16', 'The proposition opens with ''Under Theorem'', which the edit replaces.');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1.b/f1/d1', 'C1.b/f1', 1, 'form', 'The first sentence of the remark, ''the projection error is Q-orthogonal to every admissible policy'', holds by definition in Lean: the projection is defined as the member of the policy space whose error is Q-orthogonal to it (IsQProjection), not as the nearest point. Only the second sentence, 2 R(A) = ||x*||_Q^2 - ||u*||_Q^2, has content here. That the orthogonal member exists and is the unique minimizer of expected cost, hence the nearest point, is C1. Approved by Scott on 2026-11-14 at the review of Defs/Projection.lean.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1.b/f1/d2', 'C1.b/f1', 2, 'stronger', 'Stated for any square-integrable target x*, not only x* = Q^{-1} b(theta_t); no cost data are needed for the identity. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1.c/f1/d1', 'C1.c/f1', 1, 'restricted', 'Sigma-algebra form; not yet linked to the function-form regret used in the main text. The link is proved on 2026-11-15 as Model.R_eq_sigmaRegret in Routine/RadiusInfo.lean (Doob-Dynkin); no proof uses it, and the statement of C1.c stays in sigma-algebra form.', 'F6.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1/f1/d1', 'C1/f1', 1, 'form', 'Stated in the appendix''s sigma-algebra form. Elements of the policy space are functions, identified when almost surely equal. The cost data are the random variables b(theta_t) in L2 and c(theta_t) in L1, with x* = Q^{-1} b.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1/f1/d2', 'C1/f1', 2, 'reading', '''Closed'' is closed for the ordinary L2 norm; the paper''s norm-equivalence remark makes that the same as closed for the Q-norm.', 'F17.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1/f1/d3', 'C1/f1', 3, 'reading', 'That the projection exists is stated as its own part; the lemma''s wording takes it for granted.', 'F17.2');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1/f1/d4', 'C1/f1', 4, 'reading', 'Optimality, uniqueness and the regret value are stated for every member of the policy space whose error is Q-orthogonal to it, which is the defining property of the projection.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C1/f1/d5', 'C1/f1', 5, 'restricted', 'Regret here is the sigma-algebra form. It is not yet linked to the function-form regret of the main text.', 'F6.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10.b/f1/d1', 'C10.b/f1', 1, 'reading', '''The local view already determines the desired action'' is stated as R_loc = 0: the best rules of the fresh local views come arbitrarily close to the desired action in expected loss. That one rule equals the desired action almost surely is not stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10.b/f1/d2', 'C10.b/f1', 2, 'reading', '''The two losses cross once'' is read as: the threshold rho* is positive, stale-global is strictly better when tau/T < rho*, the regrets are equal when tau/T = rho*, and fresh-local is strictly better when tau/T > rho*. It is stated at one delay tau, like C10, and not as a property of the two losses as functions of the delay.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10.b/f1/d3', 'C10.b/f1', 3, 'reading', '''Every positive global delay makes local information preferable'' is read as a strict inequality, R_loc < R_glob(tau) for tau > 0.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10/f1/d1', 'C10/f1', 1, 'stronger', '0 <= eta_S(0) is not a hypothesis, because it always holds.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10/f1/d2', 'C10/f1', 2, 'reading', 'The eta_S(0) = 1 clause is stated as ''no delay gives R_loc < R_glob''; rho* = +infinity is not represented.', 'F4.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10/f2/d1', 'C10/f2', 1, 'stronger', '0 <= eta_S(0) is not a hypothesis, because it always holds.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10/f2/d2', 'C10/f2', 2, 'reading', 'The eta_S(0) = 1 clause is stated as ''no delay gives R_loc < R_glob''; rho* = +infinity is not represented.', 'F4.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C10/f2/d3', 'C10/f2', 3, 'stronger', 'The equality case is an equivalence: for eta_S(0) < 1 the two regrets are equal exactly when tau/T = rho*. The paper says ''Equality gives equal regret'', one direction. With the first clause the equivalence gives the third case, which the theorem leaves unsaid and the next sentences of the paper use (''the two losses cross once''): below the threshold stale-global is strictly better. The proof''s sentence ''rearranging gives the threshold and equality case'' covers it; no step was added.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C11/f1/d2', 'C11/f1', 2, 'form', 'A standalone statement about two scalar processes, not an instance of the graph model or of the crossover theorem. ''Best estimate'' and ''mean squared error'' are bestMSE: the smallest mean squared error over measurable functions of the observation with finite second moment. For one fresh reading and for both old readings the statement gives the value of that smallest error and says that the estimate the paper names (X_t/2, and exp(-tau/T) Z_{t-tau}) has exactly that error. That no other estimate does as well is not stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C11/f1/d3', 'C11/f1', 3, 'reading', 'All the example''s assumptions are hypotheses of the one statement, including for the first sentence about one fresh reading, where the paper has so far said only ''independent signals''. ''The two signal processes are independent'' is independence of the two whole processes. ''Stationary'' is equality of one-time laws; mean zero and variance sigma^2 are assumed at every time. The prediction rule is assumed at the one epoch t and delay tau. sigma > 0 is the standard deviation; T > 0 and tau >= 0.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C11/f1/d4', 'C11/f1', 4, 'form', '''The fresh reading wins when'' is the displayed equivalence between the two error values, sigma^2/4 < (sigma^2/2)(1 - exp(-2 tau/T)) exactly when tau > T log 2 / 2. With the first two clauses it is the comparison of the two smallest errors themselves (checked in Lean at the review of 2026-11-19). The approximation 0.35 T is not stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C12/f1/d1', 'C12/f1', 1, 'form', 'A model on n agents with Q = qI + gamma 11'', K = Q^{-1}, one scalar state and action per agent, on any graph.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C12/f1/d2', 'C12/f1', 2, 'reading', 'The hypotheses sigma > 0, n >= 2, q > 0, gamma >= 0 and the state assumptions of the preceding paragraph (independent, mean zero, equal variance) are part of the statement.', 'F2.2');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C12/f1/d3', 'C12/f1', 3, 'restricted', 'The optimal local policy is stated as existence of an admissible rule with action theta_i/(q+gamma) that attains R_loc; uniqueness is not stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C12/f1/d4', 'C12/f1', 4, 'stronger', 'The Lean statement also asserts the closed forms of R_inf and R_loc (Appendix Eqs. (aggregate_Rinf), (aggregate_Rloc)). The proposition states only the policy and eta_S(0); the two closed forms are in the last sentence of its proof. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C13.b/f1/d1', 'C13.b/f1', 1, 'reading', '''Local information captures the share q/(q+gamma) of decision variation'' is read as 1 - eta_S(0) tending to q/(q+gamma): the fraction of R_inf that the fresh-local view removes. Both limits are stated for the closed forms aggRhoStar and aggEta with q and gamma fixed and gamma = 0 allowed; the link to the model is C12 and C13. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C13.c/f1/d1', 'C13.c/f1', 1, 'reading', '''Increase'' is read as strictly increasing on gamma >= 0. Approved by Scott on 2026-11-15.', 'C13.c/d1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C13.c/f1/d2', 'C13.c/f1', 2, 'form', 'Stated for the closed forms aggEta and aggRhoStar; the link to the model is C12 and C13. ''Any positive global delay makes the fresh-local architecture preferable'' at gamma = 0 is stated as rho*(0,n) = 0, which gives the sentence through the equivalence of C13; the clause was added at the review. n >= 2 is required: with one agent eta_S(0) is identically zero. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C13/f1/d1', 'C13/f1', 1, 'reading', 'The boxed formula is read as an identity: the crossover threshold rho* = (1/2) log(1/(1 - eta_S(0))) of C10, at this model''s eta_S(0), equals the closed form. Same model and hypotheses as C12 (C12/f1/d1, C12/f1/d2), with the state assumptions at epoch t and the temporal assumption at one epoch and one delay (C7/f1/d2). The equal-regret case at tau/T = rho* is not restated. In this model eta_S(0) < 1 and R_inf > 0 hold, so the endpoint case of the F4.1 edit does not arise and the statement was frozen before that edit. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C14/f1/d1', 'C14/f1', 1, 'form', 'The radius is a graph radius in the naturals with infinity, with one delay tau(r) per radius. The paper writes tau on the real interval [0, D] and then speaks of integer radii ''on a finite graph''. At the top radius, r + 1 is the top radius again, so the one-more-hop clause says nothing there.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C14/f1/d2', 'C14/f1', 2, 'stronger', 'The paper''s ''tau nondecreasing, tau(0) = 0'' and the maximum allowed radius D are not assumed: the three identities hold without them. tau(r) >= 0 is kept, inside the temporal assumption, which is assumed at the delay of every radius.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C14/f1/d3', 'C14/f1', 3, 'reading', '''One more hop improves performance'' is read as strictly lower regret, R(r+1) < R(r).', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C14/f1/d4', 'C14/f1', 4, 'form', '''So the best radius maximizes G(r)'' is not a separate clause. It follows from the first identity because R_inf > 0: R(r) <= R(r'') exactly when G(r'') <= G(r) (checked in Lean at the review of 2026-11-19).', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15.b/f1/d1', 'C15.b/f1', 1, 'form', '''The unique optimum'' is stated as a strict maximizer of the gain G on [0, D], as in C15 (C15/f1/d1): R and R_inf do not appear.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15.b/f1/d2', 'C15.b/f1', 2, 'reading', '''The difference between the left and right sides ... is strictly decreasing in r'' is read as: balanceGap is strictly decreasing on [0, D], with one-sided derivatives at the two endpoints. ''Its sign identifies the unique optimum'' is three clauses: gap nonpositive at 0 gives radius 0; gap nonnegative at D gives radius D; gap positive at 0 and negative at D gives one zero of the gap in (0, D), the only one, and that radius. In each clause the radius is strictly better than every other radius in [0, D]. The three cases cover everything (checked in Lean at the review of 2026-11-19). D > 0 and T > 0 are hypotheses.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15.c/f1/d1', 'C15.c/f1', 1, 'form', '''The preferred radius'' is stated as a maximizer of the gain G on [0, D], as in C15 (C15/f1/d1). The statement holds for any maximizers before and after the change; under single crossing each is unique (C15.b).', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15.c/f1/d2', 'C15.c/f1', 2, 'reading', '''Preserving this single-crossing condition'' is read as: the balance gap is strictly decreasing on [0, D] both before and after the change. ''Increasing T'' and ''increasing the latency scale'' are T <= T'' and alpha <= alpha'', with alpha > 0 and T > 0; ''weakly outward'' and ''weakly inward'' are r <= r'' and r'' <= r. The delay is alpha tau_0 with tau_0 satisfying the hypotheses of the proposition.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15.c/f1/d3', 'C15.c/f1', 3, 'restricted', '''The optimum can stay unchanged at a boundary'' is not stated. It says that the inequalities cannot be made strict in general, which would need an example; the weak inequalities are consistent with it.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15/f1/d1', 'C15/f1', 1, 'form', '''Optimal radius'' is stated as a maximizer of the gain G on [0, D]. The paper''s R(r) = R_inf [1 - G(r)] with R_inf > 0 (assumed for the section) makes that the same as a minimizer of R; R and R_inf do not appear in the Lean statement. Until arXiv v3 this row also said that the graph model does not appear; the proposition is now stated for given curves (F8.1). Checked in Lean at the review of 2026-11-19: for any R and R_inf > 0 with R(r) = R_inf [1 - G(r)] on [0, D], an interior minimizer of R on [0, D] satisfies the stated equality. The paper''s own proof argues about maximizing G.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C15/f1/d2', 'C15/f1', 2, 'form', 'The derivative hypotheses are one-sided at the endpoints; the conclusion uses the ordinary derivative at the interior point. tau'' >= 0, eta'' <= 0 and eta >= 0 are kept as hypotheses although the conclusion does not need them. At an interior point the curves are differentiable in the ordinary sense, so the derivatives in the conclusion are genuine (checked in Lean, 2026-11-19). D > 0 and T > 0 are hypotheses; the paper takes them for granted.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C16/f1/d1', 'C16/f1', 1, 'form', '''Unique global optimal radius'' is stated as a strict maximizer of the gain G over r >= 0, with eta(r) = eta_0 exp(-2r/l_c) and tau(r) = r/v. The paper''s R(r) = R_inf [1 - G(r)] with R_inf > 0 (assumed for the section) makes that the same as a strict minimizer of R; R and R_inf do not appear in the Lean statement. Until arXiv v3 this row also said that the graph model does not appear; the proposition is now stated for given curves (F8.1). Checked in Lean at the review of 2026-11-19: for any R and R_inf > 0 with R(r) = R_inf [1 - G(r)] on r >= 0, the statement gives R(r*) < R(r) for every other r >= 0. The paper''s own proof argues about the maximum of G.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C16/f1/d2', 'C16/f1', 2, 'reading', '''With a continuous radius cap D, r_D* = min{D, r*}'' is read as: for every D >= 0, min{D, r*} is the unique maximizer of G on [0, D]. T > 0 is a hypothesis; in the paper it is the standing assumption on the coherence time.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C17.b/f1/d1', 'C17.b/f1', 1, 'form', 'The paragraph ends in words (''retains a^2 times the gain from a fresh interval of the same radius''). Lean displays it as R_inf - R(r,tau) = a^2 (R_inf - R(r,0)).', 'F10.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C17.b/f1/d2', 'C17.b/f1', 2, 'reading', 'Radius r >= 0 and delay tau >= 0 are hypotheses; the paper takes them for granted.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C17/f1/d1', 'C17/f1', 1, 'reading', 'Regret in the field model is the expected pointwise loss at a location, not a spatial average: the general regret with one agent and one action coordinate. The paper says ''regret per unit length, equal by stationarity to expected pointwise loss''.', 'F10.4');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C17/f1/d2', 'C17/f1', 2, 'extra_hypothesis', 'Every sample path of the field is continuous in the location. The appendix says ''we use a continuous version of the field'' for the lemma''s proof; the main text does not say it. The observation is the path on [-r, r] with the product sigma-algebra.', 'F19.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C17/f1/d3', 'C17/f1', 3, 'stronger', 'sigma^2 > 0 is not part of the definition. Since arXiv v3 the model paragraph says ''variance sigma^2 > 0'' (main-v3.tex 815). CanonicalField has no such field: sigma != 0 is an explicit hypothesis of C18 and C19, as in the lemma and the theorem, and the composition paragraph C17.b is proved without it. Decided by Scott on 2026-11-19: keep it so. Defs/Canonical.lean, frozen before v3, is unchanged and is not refrozen.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C18/f1/d3', 'C18/f1', 3, 'stronger', 'Stated at every location z and time t. The paper''s proof sets z = 0 and suppresses time ''by stationarity''.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C18/f1/d4', 'C18/f1', 4, 'reading', 'Radius r >= 0 is a hypothesis; the paper takes it for granted. l_c > 0 and q > 0 are the model paragraph''s (main-v3.tex 826, 835).', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19.b/f1/d1', 'C19.b/f1', 1, 'stronger', 'The item on l_s compares a point of the interior regime with every larger l_s, including values outside the regime. The paper restricts it to the interior regime.', 'F11.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19.b/f2/d1', 'C19.b/f2', 1, 'reading', '''Within the interior regime, r* decreases with l_s'' is read as: for two values l_s < l_s'' that both satisfy vT > 2 l_s, r* is strictly smaller at l_s''. The other items compare the base point with any larger T, v or l_c, which stays in the regime.', 'F11.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19.b/f2/d2', 'C19.b/f2', 2, 'form', 'The statement is about the closed form r* = (l_c/2)[log((l_c + vT)/(l_c + 2 l_s))]_+ (canonRadius), with l_c, l_s, v, T > 0. That this is the optimal radius of the field model is C19. ''Increases'' and ''decreases'' are strict inequalities between two values of one parameter, the other three fixed.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19/f1/d1', 'C19/f1', 1, 'restricted', 'Algebraic form only: the radius formula, uniqueness and the threshold for the gain function with eta_0 = l_c/(l_c + 2 l_s). The Gaussian field, the integral target and regret do not appear. That this curve is the regret of the field model is C17.b and C18 (tier D), which are not yet stated in Lean.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19/f2/d3', 'C19/f2', 3, 'reading', '''The unique optimal radius'' is read as: the regret at a location, as a function of the radius r >= 0 with delay r/v, is strictly smaller at r* than at any other radius. Stated at every location and time.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C19/f2/d4', 'C19/f2', 4, 'restricted', 'The Lean statement is the radius formula, its uniqueness and the threshold vT > 2 l_s. The theorem''s four comparative statics (''Within the interior regime, r* increases with T ...'') are the separate statement C19.b.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C2/f1/d1', 'C2/f1', 1, 'form', 'Same setting as C1/f1. The equations are stated per action coordinate; an agent''s block is the set of coordinates it acts on.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C2/f1/d2', 'C2/f1', 2, 'reading', '''The unique team optimum in the Lemma'' is any member with the projection property. The block form is stated as equivalent for admissible u only.', 'F15.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C2/f1/d3', 'C2/f1', 3, 'restricted', 'Not stated: ''one generally does not have u_i* = E[x_i* | G_i]'', a statement about what fails in general. The common-information sentence is claim C3.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C20/f1/d1', 'C20/f1', 1, 'form', 'A limit of the closed form canonRadius as l_c tends to infinity with l_s, v, T fixed and positive; that this radius is the optimal one is C19. ''l_c >> vT, l_s'' is not a separate hypothesis. The statement does not depend on the edits C19 waits for (F10.2, F10.3, F18.1), so it was frozen before them. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C3.b/f1/d1', 'C3.b/f1', 1, 'restricted', 'The paragraph''s first sentence, ''the best constant is E[x*]; its regret is half the weighted variance of x*'', is not stated. The Lean statement has three parts under R_inf = 0: x* = 0 almost surely; zero regret for every family of observations (wider than ''every architecture'' of the radius family); the composition identity for every weight a. ''Centered coordinates'' is not a hypothesis, because R_inf is the second moment. ''Normalized shares are undefined'' is not stated. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C3/f1/d1', 'C3/f1', 1, 'form', 'Same cost setting as C1/f1. ''Every agent observes the same Z'' is: Z is a measurable map into any measurable space and every agent''s sigma-algebra is sigma(Z). m = E[x* | Z] is the vector conditional expectation. The statement has three parts: m is admissible (used by the paper, not stated), m has the lowest expected cost over the policy space, and any admissible policy that costs no more is almost surely equal to m. ''Regardless of the off-diagonal entries of Q'' is the quantifier over every positive definite Q. Not stated: the regret value (the next paragraph, claim C3.c) and the closing caution ''for different observations this argument does not apply componentwise''. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.b/f1/d1', 'C4.b/f1', 1, 'reading', '''Independent innovations'' is read as: each innovation is independent of every earlier state. Mutual independence of the innovations is not assumed.', 'F9.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.b/f2/d1', 'C4.b/f2', 1, 'form', 'Time is the integers, as in the recursion, with lag k a natural number. The state is a vector and c a scalar. ''Stationary'' is StationaryState over the integers: measurable, finite second moments, the same one-time law at every time (as for C4, F7). ''Finite variance'' of the innovations is finite second moment.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.b/f2/d2', 'C4.b/f2', 2, 'form', 'F_{t-1} = sigma(theta_s : s <= t-1) is written as the supremum, over the integers u <= s, of the sigma-algebras generated by theta_u, and the hypothesis is E[eps_{s+1} | F_s] = 0 almost surely for every s. The innovations are a second process eps with the recursion holding at every outcome, which is the same as defining eps_{s+1} = theta_{s+1} - c theta_s. Checked in Lean at the review of 2026-11-19: under the statement''s other hypotheses F_s is a sub-sigma-algebra of the ambient one and eps is integrable, so the conditional expectation in the hypothesis is the genuine one and not Lean''s default value 0.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.b/f2/d3', 'C4.b/f2', 3, 'reading', '''The composition weights are 1 - c^(2k) and c^(2k)'' is read as the composition law itself, for every model (graph, cost, desired action) on this state and every radius r: R(A_{r,k}) = (1 - c^(2k)) R_inf + c^(2k) R(A_{r,0}) at each epoch t.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d1', 'C4.c/f1', 1, 'reading', '''The stationary Gaussian Ornstein-Uhlenbeck process'' is read through its law: a jointly Gaussian process on the whole real time line with the mean and covariance the appendix gives. The stochastic differential equation Eq. (OU_process), the Brownian motion W_t and continuity of paths are not stated. So the appendix''s sentence that this equation has covariance exp(-|t-s|/T) Sigma_S is a hypothesis here, not a conclusion: Lean does not check the coefficient sqrt(2/T) Sigma_S^(1/2). (Checked by hand: the stationary covariance P of the equation solves -(2/T) P + (2/T) Sigma_S = 0.) Every conclusion depends only on the law of the process, and a stationary solution of the equation is such a process.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d2', 'C4.c/f1', 2, 'restricted', 'Mean zero. The appendix''s process has mean thetabar and speaks of ''its centered transition''; the main text centers known means throughout (main-v3.tex 214-216) and the temporal assumption is written in centered coordinates. The general case is this statement applied to theta - thetabar.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d3', 'C4.c/f1', 3, 'form', 'Sigma_S is a free matrix S in the covariance hypothesis. The hypothesis forces S to be the second-moment matrix of theta_t at every t, hence symmetric and positive semidefinite; ''Sigma_S >= 0'' is not a separate hypothesis.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d4', 'C4.c/f1', 4, 'extra_hypothesis', 'Each theta_t is measurable: the regularity the paper leaves implicit (as in StationaryState and CanonicalField).', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d5', 'C4.c/f1', 5, 'reading', '''Its centered transition has independent Gaussian innovations'' is read as: for every epoch t and delay tau >= 0 the innovation theta_t - exp(-tau/T) theta_{t-tau} is Gaussian and independent of the family of earlier states (theta_s : s <= t - tau), a random element of the product space with the product sigma-algebra. Independence from the old state theta_{t-tau} alone, and independence of innovations over disjoint intervals, follow. The covariance of the innovation, (1 - exp(-2 tau/T)) Sigma_S, is not stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4.c/f1/d6', 'C4.c/f1', 6, 'reading', '''Is a sufficient example of the main conditional-mean assumption'' is read as TemporalAssumption at every epoch t and every delay tau >= 0. Stationarity is part of that conclusion (equal one-time laws, finding F7); in the hypotheses it appears only as a mean and a covariance that do not depend on the epoch.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C4/f1/d1', 'C4/f1', 1, 'reading', 'Stationarity is equality of one-time laws, at one epoch and one delay.', 'F7.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C5.b/f1/d1', 'C5.b/f1', 1, 'form', '''Without loss'' is stated as two facts: the centered desired action is K theta^c pointwise, and the regret of the uncentered problem (target Q^{-1}(B theta + b_0), observations of the uncentered snapshot) equals the regret of the centered model. The ''bijection of admissible rules'' is the proof, not part of the statement. Stated for radius architectures, with the observed snapshot and the current state allowed to differ. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C5/f1/d1', 'C5/f1', 1, 'form', 'Stated at one fixed state: b and c are the values b(theta) and c(theta), so the identity holds state by state, which is the content of the paper''s display. The second part, that x* = Q^{-1} b is the unique minimizer, is the sentence before Eq. (clairvoyant), stated for the cost at a fixed state. Approved by Scott on 2026-11-14.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C6.b/f1/d1', 'C6.b/f1', 1, 'reading', '''No-information action'' is read as a constant action. ''Best'' is stated as: no constant action costs less than R_inf, and the zero action costs R_inf; that zero is the only best constant is not stated. Zero mean of the state is an explicit hypothesis (see C6/f1/d2). Sigma_S is the covariance matrix of the state. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C6.c/f1/d1', 'C6.c/f1', 1, 'stronger', 'The radius ranges over the naturals and infinity (see C6/f1/d1), so the range and the monotonicity clause also cover the complete view. ''Finite connected graph'' is a finite agent type with G.Connected, and ''at the diameter'' is the radius G.diam. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C6.c/f1/d2', 'C6.c/f1', 2, 'restricted', 'The clause eta_S(0) = R_loc/R_inf is not stated: with the definitions of R_loc and eta_S it holds by unfolding, so a Lean clause would assert nothing. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C6/f1/d1', 'C6/f1', 1, 'reading', 'The radius ranges over the naturals and infinity, and stale-global is radius infinity.', 'F5.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C6/f1/d2', 'C6/f1', 2, 'stronger', 'Zero mean is not a field of the model. The paper centers known means throughout and calls R_inf the loss of the best no-information action; Lean''s Model does not require a zero-mean state, and R_inf is defined by the paper''s first expression, the second moment (1/2) E[x*'' Q x*]. Where the temporal assumption holds with tau > 0, zero mean follows from it (E theta_t = a E theta_{t-tau} with equal one-time laws gives (1 - a) E theta_t = 0), so for C7, C8 and C10 the difference is one of form only. It is a wider claim where there is no temporal assumption: C6.c (range and monotonicity of eta_S) is stated for uncentered states. Zero mean is an explicit hypothesis where it is used without the temporal assumption: C6.b (zero is the best constant action; the trace formula with Sigma_S). Approved by Scott on 2026-11-14 at the review of Defs/Architecture.lean.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C7.b/f1/d1', 'C7.b/f1', 1, 'form', '''Equivalently'' is stated as the normalized law itself, under the hypotheses of C7 plus R_inf > 0, not as an equivalence of the two displays. Snapshot form with the epoch explicit, as in C7/f1/d1: R_inf and eta_S(r) are taken at the current state theta_t; the hypothesis is the temporal assumption at one epoch and one delay, as in C7/f1/d2. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C7/f1/d1', 'C7/f1', 1, 'form', 'Snapshot form: R(A_{r,tau}) at epoch t is the regret for the old snapshot theta_{t-tau} and the current state theta_t; the paper suppresses t. The radius ranges over the naturals and infinity.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C7/f1/d2', 'C7/f1', 2, 'stronger', 'The hypothesis is the temporal assumption at one epoch and one delay, with stationarity as equality of one-time laws. That is weaker than process-level stationarity.', 'F7.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C7/f1/d3', 'C7/f1', 3, 'restricted', 'C7 proves the first boxed equation. C7.b proves its normalized form under the assumption R∞ > 0.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C8.c/f1/d1', 'C8.c/f1', 1, 'reading', '''For every delay analyzed'' is read as every tau >= 0 at the fixed epoch t. ''Grows initially as 2(tau/T)R_inf + o(tau/T)'' is read as R_glob(tau) - 2(tau/T)R_inf = o(tau/T) as tau decreases to 0 from the right; ''tends to R_inf as delay grows'' is the limit as tau tends to infinity. R_inf > 0 is not assumed. Approved by Scott on 2026-11-15.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C8.c/f1/d2', 'C8.c/f1', 2, 'form', '''The regret'' is stated for R_glob, the infimum over admissible rules of the complete old snapshot (radius infinity, see C8/f1/d1). Approved by Scott on 2026-11-15, when the sentence read ''Its regret'', of the action a K theta_{t-tau}, and this row said that the cost of that action equals R_glob by the remark C8.b. arXiv v3 reworded the sentence to ''The regret'' and deleted the remark; that the action attains R_glob is now part of step 2 of the corollary''s proof (C8/p2/s2). The Lean statement and its hash are unchanged.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C8/f1/d1', 'C8/f1', 1, 'reading', 'R_glob is the regret at radius infinity: every agent sees the whole old snapshot. No connectivity is assumed.', 'F5.1');
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d1', 'C9/f1', 1, 'reading', '''Ornstein-Uhlenbeck modes with coherence times T_k'' is read through the law, as in C4.c/f1/d1: mode k is a jointly Gaussian process with mean zero and covariance exp(-|t-s|/T_k) S_k. The per-mode hypotheses are those of C4.c/f1 word for word. No differential equation is stated.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d2', 'C9/f1', 2, 'reading', 'The paper does not define a mode; it writes x_k* = K_k theta^(k). Lean: theta^(k) = P_k theta for matrices P_k with sum_k P_k = 1, finitely many, and K_k theta^(k) = K P_k theta. This contains groups of state coordinates (P_k a diagonal 0/1 matrix) and the total and difference of two loads. The P_k are not required to be projections. ''A complete old snapshot reveals the modes'' holds by construction: each mode is a function of the state. It is a real hypothesis: for a scalar state that is the sum of two independent parts with different rates the formula fails.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d3', 'C9/f1', 3, 'reading', '''Independent'' is read as independence of the mode processes, each taken as a random path s -> P_k theta_s (iIndepFun, product sigma-algebra). Joint Gaussianity across modes is not assumed; it follows.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d4', 'C9/f1', 4, 'form', 'The matrices S_k are free; the covariance hypothesis forces S_k to be the second-moment matrix of mode k.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d5', 'C9/f1', 5, 'extra_hypothesis', 'Each theta_t is measurable: the regularity the paper leaves implicit.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d6', 'C9/f1', 6, 'form', '''Write x* = sum_k x_k*'' is notation in the paper; Lean states it as the first conclusion. It follows from sum_k P_k = 1 alone.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d7', 'C9/f1', 7, 'reading', 'Stated at every epoch t and every delay tau >= 0; R_glob(tau) is M.Rglob mu (theta (t - tau)) (theta t) and R_inf is taken at epoch t. ''For R_inf > 0'' is a hypothesis of all three conclusions; the denominator of w_k is 2 R_inf.', NULL);
INSERT INTO statement_deltas (id, formalization_id, ordinal, kind, text, disposition_id) VALUES ('C9/f1/d8', 'C9/f1', 8, 'reading', 'The sentences after the formula (the two-server illustration, and that the formula applies to a complete old snapshot and its extension to partial observations requires additional assumptions) are not stated.', NULL);
