INSERT INTO notes (id, ts, target, kind, body) VALUES (1, '2026-11-13T13:43:04', 'C12', 'decision', 'F2: main-text derivation C12/p1 is primary; appendix normal-equation derivation C12/p2 to be removed by a tracked edit when C12 is formalized.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (2, '2026-11-13T13:55:41', 'C4.c', 'todo', 'Before attempting: bump Lean and Mathlib to v4.35.0 (about 1 GB download, see README ''Libraries''). atlas-lean MathlibExt/Probability/OrnsteinUhlenbeck.lean at commit 8e813e6 gives the stationary scalar OU process as a Gaussian process with covariance (sigma^2/2theta) exp(-theta|t-s|), with existence, stationarity, condExp_natural and condDistrib_eval; closure is 3 files (plus KolmogorovExtension, GaussianConditioning), which do not compile on Mathlib v4.33.1. Scalar only: the paper''s vector form with Sigma_S is not covered. Also relevant to C9.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (3, '2026-11-13T14:16:11', 'C19', 'done', 'C19/f1 is the algebraic form only. Write the full statement (new formalization version) once tier D definitions for C17 exist and F1 is resolved.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (4, '2026-11-13T14:16:11', 'C6', 'decision', 'Defs take snapshots (random state vectors), not a process and a time; radius is in N union {top}; rules are coordinatewise functions of the agent''s observation. All drafts pending Scott''s review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (5, '2026-11-13T14:16:11', 'C5', 'done', 'C5 has no English proof in the ledger (''Completing the square gives'' is the whole argument). Add a one-step proof row before phase 2, or a short appendix proof through an edit. [Done 2026-11-14: supplement proof C5/p1, proved by C5/a1.]');
INSERT INTO notes (id, ts, target, kind, body) VALUES (6, '2026-11-14T13:50:23', 'C17.b', 'decision', '2026-11-14 (Scott): upstream 284a0e0 added the continuum composition law as a paragraph with an argument. Kept the ID, kind implicit -> remark, added the in-paper proof C17.b/p1 (6 verbatim steps). Removed the edge ''C17.b uses C7'': the paragraph argues directly from the field covariance and does not invoke the finite-graph theorem. ''C17.b setup C17'' and ''C19 uses C17.b'' stay.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (7, '2026-11-14T13:50:23', 'C17', 'insight', 'Realigned to 6454c74. Upstream 284a0e0 changed ''a Gaussian spatial field on a dense one-dimensional network, represented by locations z'' to ''a jointly Gaussian space--time field on the infinite line, with spatial coordinate z''. Ledger statement updated to match (approved by Scott 2026-11-14). No Lean definition of C17 exists yet, so nothing is invalidated.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (8, '2026-11-14T13:50:23', 'C25', 'insight', 'Realigned to 6454c74. Abstract and contribution list rewritten upstream (8d0ac72, 7bace26, d087a87, df99ee3): ''exact rule'' is gone and the composition law is attributed to Marschak-Radner. Ledger statement updated (approved by Scott 2026-11-14). The range is now 46-181 so that it still covers the introductory attribution and literature paragraphs, which moved to after the contribution list. The new explanatory figure fig:snapshot-architectures (propagation cone, lines 102-114, 8d0ac72) lies in this range; it is an illustration and gets no claim ID (Scott 2026-11-14).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (9, '2026-11-14T13:50:23', 'C6', 'insight', 'Realigned to 6454c74. The definition text is identical to 4a9b87e. The new explanatory figure fig:field-and-cost (lines 237-248, upstream 8d0ac72) lies inside this range; it is an illustration and gets no claim ID (Scott 2026-11-14).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (10, '2026-11-14T13:50:23', 'C26', 'insight', 'Realigned to 6454c74. Upstream 284a0e0 added the Marschak-Radner attribution paragraph (Eqs. (6.5), (6.6)) and the Jiang-Zhou and Munari et al. comparison, removed the ''distinctive object'' paragraph and added paragraph headings. Ledger statement updated (approved by Scott 2026-11-14). The two attributions have not been checked against the book.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (11, '2026-11-14T13:50:23', 'C27', 'insight', 'Realigned to 6454c74. Upstream 284a0e0 rewrote the assumptions-per-result paragraph and 886659b the closing design implication. Ledger statement updated (approved by Scott 2026-11-14).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (12, '2026-11-14T13:50:23', 'C12/p2/s6', 'insight', 'Step text updated to the paper as of 6454c74: upstream 886659b renamed ''\emph{Open-loop regret.}'' to ''\emph{No-information regret.}'' (a terminology change made throughout the paper). The mathematics is unchanged. This is the paper changing on its own, not a Lean-driven edit, so there is no edits row. The secondary derivation C12/p2 is still in the paper in full; upstream has not removed or shortened it (see F2).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (13, '2026-11-14T13:50:23', 'C7', 'insight', 'Realigned to 6454c74. Upstream 284a0e0 now introduces the theorem as Marschak and Radner''s delayed-information decomposition (Ch. 7, Sec. 4, Eqs. (4.21)-(4.22), with a notation footnote) at main-v2.tex 367-377, just before this claim''s range. The theorem statement and proof are identical to 4a9b87e, so C7/f1 and C7/p1 are unaffected. This is review item K1 (README open decision 4).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (14, '2026-11-14T13:50:23', 'C3.b', 'insight', 'Realigned to 6454c74. Upstream 886659b split the appendix paragraph ''Common information and degenerate normalization'' into three: ''Common-information optimality'' (C3), ''Delayed common snapshots'' (C3.c) and ''Degenerate normalization'' (C3.b). Both steps of C3.b/p1 are verbatim.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (15, '2026-11-14T13:50:23', 'C11', 'insight', 'Realigned to 6454c74. Upstream 7bace26 rewrote the closing remark of the example (''one current reading predicts the two-sensor average better than both readings once the pair is more than about 0.35T old''). The displayed inequality and the three steps are verbatim; C11/f1 is unaffected.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (16, '2026-11-14T13:50:23', 'C14', 'insight', 'Realigned to 6454c74. Upstream 886659b changed ''open-loop loss'' to ''no-information loss'' in the sentence defining G and replaced the five-line motivating paragraph with one sentence. G, the one-more-hop criterion and the decomposition are verbatim; C14/f1 is unaffected.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (17, '2026-11-14T13:50:24', 'F2', 'insight', 'Rechecked against 6454c74: both derivations are still in the paper. Upstream did not remove or shorten the appendix derivation C12/p2; its only change there is the heading of step s6 (''No-information regret'').');
INSERT INTO notes (id, ts, target, kind, body) VALUES (18, '2026-11-14T16:01:45', 'F4', 'insight', 'C10/a1 is proved. Steps 1 and 2 mirror the two sentences of the proof. The eta_S(0) = 1 clause has no sentence in the paper''s proof; in Lean it is one line in main, read off step 1 (the comparison would be 1 < 1 - e^{-2 tau/T}). When the paper gains the sentence proposed in the findings memo, that line becomes step 3. The Lean statement already has the hypothesis in the reworded form (R_inf > 0, then the two cases).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (19, '2026-11-14T16:01:45', 'C7/a1', 'success', 'Proved 2026-11-14 against the draft statement C7/f1: 7 step lemmas for the 7 paper steps, main is a one-line instantiation. 238 lines, 4.0 s, axioms propext, Classical.choice, Quot.sound. Hypotheses of the statement that the proof never uses: T > 0 and tau >= 0 (a = e^{-tau/T} > 0 is all step 5 needs). Step 4 did not need C6.b: R_inf is by definition (1/2) E[x*'' Q x*]. Step 3 needs step 1 (step_deps corrected).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (20, '2026-11-14T16:01:45', 'C7/a1', 'insight', 'Routine/Regret.lean holds what the paper leaves unsaid here: expansion of the quadratic form, measurability, integrability of products of L2 vectors, the zero rule is admissible, scalar multiples of admissible rules are admissible, admissibility depends only on the law of the snapshot, a constant moves out of an infimum, and linearity of conditional expectation applied coordinatewise to the prediction rule. The pull-out and tower property that make the cross term vanish are inside the step lemma, not in Routine, because they are the content of the paper''s step 2.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (21, '2026-11-14T16:01:45', 'C8/a1', 'success', 'Proved 2026-11-14 against draft C8/f1 with C7 as a hypothesis. 54 lines, 4.0 s. The complete snapshot is radius top (finding F5): the rule u = K theta is admissible there.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (22, '2026-11-14T16:01:45', 'C10/a1', 'success', 'Proved 2026-11-14 against draft C10/f1 with C8 as a hypothesis. 66 lines, 3.9 s. See the note on F4 for the one line in main that has no paper sentence.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (23, '2026-11-14T16:01:45', 'C14/a1', 'success', 'Proved 2026-11-14 against draft C14/f1 with C7 as a hypothesis. 64 lines, 3.8 s.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (24, '2026-11-14T16:01:46', 'C14/p1', 'decision', '2026-11-14: steps s2 (main 698-702, the one-more-hop criterion) and s3 (main 709-716, the loss decomposition) added to the step list. Both sentences are in the paper verbatim and are part of the claim; the first extraction had only the sentence that cites the theorem, which left two conjuncts of the statement with no step. No paper change.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (25, '2026-11-14T16:01:46', 'C5.b/p1', 'decision', '2026-11-14: the proof is now two steps. s1 is the sentence ''Then the centered desired action is x^{*,c} = K theta^c'' (app 90-92), which is the first conjunct of the statement and was not a step; the translation sentence (app 92-95) is s2. Text is verbatim from the paper; no paper change.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (26, '2026-11-14T16:01:46', 'C5.b/a1', 'success', 'Proved 2026-11-14 against draft C5.b/f1. 93 lines, 4.0 s. The paper''s step covers translating both observations and actions, and Lean translates both. Wording to tighten some day: ''each action by its known mean'' means by E[x*], not by the mean of the action. Needs a probability measure and integrable theta; Measurable snap, MemLp snap and Measurable now in the statement are unused.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (27, '2026-11-14T16:01:46', 'C3.b/a1', 'success', 'Proved 2026-11-14 against draft C3.b/f1. 74 lines, 3.7 s. Step 1 needs theta in L2 (so x*'' Q x* is integrable). Step 2 uses Q > 0 a second time, for ''no rule costs less than zero'', which the paper leaves unsaid. The third conjunct is 0 = 0 for every a.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (28, '2026-11-14T16:01:46', 'C15/a1', 'success', 'Proved 2026-11-14 against draft C15/f1. 70 lines, 3.8 s. Hypotheses never used: 0 < T, 0 < D, tau'' >= 0, eta'' <= 0, 0 <= eta. Only C1 on [0, D] and eta < 1 are needed.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (29, '2026-11-14T16:01:46', 'C16/a1', 'success', 'Proved 2026-11-14 against draft C16/f1. 211 lines, 4.8 s. The statement was tested numerically first (4000 random parameter sets with boundary and cap cases, no violation). Steps 3 and 4 need step 1 (step_deps corrected). See F12 for what the paper leaves unsaid.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (30, '2026-11-14T16:01:46', 'C19/a1', 'success', 'Proved 2026-11-14 against draft C19/f1 (algebraic form) with C16 as a hypothesis. 58 lines, 4.2 s. No hypothesis for C18 or C17.b: the algebraic statement fixes eta_0 and does not mention the field model. The full statement still waits on tier D and F10.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (31, '2026-11-14T16:01:46', 'C19.b/a1', 'success', 'Proved 2026-11-14 against draft C19.b/f1. 166 lines, 4.4 s. Items 1-3 through the derivative, item 4 through the integral representation, as in the paper. The paper states only the sign of each derivative; ''hence strictly monotone'' goes through a Routine wrapper around Mathlib''s strictMonoOn_of_deriv_pos. See F11 for the case outside the regime.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (32, '2026-11-14T16:01:46', 'C16/a1', 'todo', 'Routine/ExpRadius.lean and Routine/RadiusCalculus.lean each have a HasDerivAt wrapper for strict monotonicity from the sign of the derivative. Merge them into one file.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (33, '2026-11-14T16:10:38', 'C11/a1', 'success', 'Proved 2026-11-14 against draft C11/f1. 261 lines, 3.7 s; Routine/Estimation.lean is 275 lines and imports Mathlib.Probability.ConditionalExpectation. A Gaussian AR(1) pair simulated at three parameter sets matched the coefficients, both errors, Var(Z) and the crossover. Step 3 carries a middle conjunct comparing the two best errors so that it uses steps 1 and 2 as the ledger lists; main discards it. main has one rewrite (Var(Z_t) = sigma^2/2 from step 3 into step 2''s error). See F13.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (34, '2026-11-14T16:11:09', 'C12/a1', 'success', 'Proved 2026-11-14 against draft C12/f1, with C5 as a hypothesis (C5 has no paper proof yet, so the assembled theorem is conditional on it). 461 lines, 5.2 s; Routine/Aggregate.lean is 217 lines. Closed forms checked in exact rational arithmetic for 8 random (n, q, gamma, sigma^2), n from 2 to 6, before proving. Mirrors the main-text proof only (decision on F2). Step 4 does not use step 2 in Lean; step 5''s clause ''every constant has nonnegative expected cost'' is proved but unused, because R_inf is defined as (1/2) E[x*'' Q x*]. See F14.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (35, '2026-11-14T16:37:06', 'C1', 'insight', 'Statements C1/f1, C1.b/f1, C2/f1, C3/f1 tested numerically before any proof (finite probability space, partitions as sigma-algebras, random Q, b, c, 40 trials, two block layouts): projection exists, costs strictly less than random members of S, regret = (1/2)||x* - p||_Q^2, C1.b Pythagorean form, C2 normal equations and block form at p and violated off p, C3 conditional mean optimal. Agentwise conditional means cost strictly more than the optimum in every trial.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (36, '2026-11-14T16:50:34', 'C2/a1', 'success', 'Proved 2026-11-14 against draft C2/f1, with C1 as a hypothesis of steps 1-2 and of main. 185 lines, 1.9 s; Routine/NormalEq.lean is 147 lines. Step 1 mirrors the paper''s first-order condition (IsLocalMin.hasDerivAt_eq_zero) although the orthogonality in IsQProjection would give the same equation directly. Step 2 uses indicator perturbations on one coordinate, a special case of the paper''s ''arbitrary square-integrable function''. Step 3 does not use C5: the displayed expansion is the routine lemma expectedCost_add. Conjunct 3 (block form) comes from Routine normalEquations_iff_block in main, because the paper''s proof has no step for it. See F15.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (37, '2026-11-14T16:50:34', 'C3/a1', 'success', 'Proved 2026-11-14 against draft C3/f1, unconditionally. 112 lines, 2.4 s; Routine/CommonInfo.lean is 67 lines. Step 1 holds for any matrix Q and any square-integrable target. Step 2 uses the expansion around m (expectedCost_add), not completing the square, so C5 is not used although step_deps lists it. Z enters only through sigma(Z) <= F. See F16.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (38, '2026-11-14T17:54:55', 'C1/a1', 'success', 'Proved 2026-11-14 against draft C1/f1, with C5 as a hypothesis of steps 3-4 and of main (C5 has no paper proof yet, so the assembled theorem is conditional on it). 184 lines, 4.5 s; Routine/QHilbert.lean is 250 lines, Routine/Projection.lean (shared with C2, C3) 226. Existence of the projection is Mathlib''s theorem (Submodule.exists_norm_eq_iInf_of_complete_subspace with norm_eq_iInf_iff_real_inner_eq_zero) in Mathlib''s L2 over R^d with the Q inner product (Matrix.toNormedAddCommGroup, Matrix.toInnerProductSpace on a type synonym), which is complete because R^d is; nothing about the projection theorem is re-proved. The one inequality used from ''the induced norm is equivalent to the ordinary L2 norm'' is sum_c v_c^2 <= C v''Qv. IsProbabilityMeasure is not used by any step. The agent that wrote the files was cut off by a network error after its first draft of the attempt file; the draft compiled unchanged and was reviewed in the main session. See F17.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (39, '2026-11-14T18:07:30', 'C2/p1/s3', 'decision', '2026-11-14, Scott on Claude''s recommendation: C5 removed from this step''s dependencies. The displayed expansion E[f(u*+h) - f(u*)] = E[h''(Qu* - b)] + (1/2) E[h''Qh] is algebra on the quadratic cost, not Eq. (complete_square), and the sentence does not cite that equation. Listing C5 was an over-attribution in the first step extraction. See F15 item 5.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (40, '2026-11-14T18:07:30', 'C3/p1/s2', 'decision', '2026-11-14, Scott on Claude''s recommendation: ''the error expansion'' is read as the display in the justification of the normal equations (appendix 263-266), not as Eq. (complete_square) followed by an expansion around m. C5 removed from this step''s dependencies, and the claim''s dependency on C5 is now ''setup'' (C3 is stated for the quadratic cost). Reasons: the display is four lines above the paragraph; C3 stays unconditional instead of resting on the unproved C5; the Lean proof C3/a1 already follows this reading. The paper still needs the wording fix of F16, preferably by giving that display an equation label that C2''s steps 1 and 3 and this step can cite.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (41, '2026-11-14T18:07:30', 'C11', 'decision', '2026-11-14, Scott on Claude''s recommendation (F13 item 2): ''the conditional mean is the best mean-squared-error estimate'' is treated as a standard fact in the two-sensor example. It stays in Routine/Estimation.lean (bestMSE_eq_of_condExp); C11 is not rewired to use C3 and the example gets no forward pointer to the appendix. Reasons: it is a textbook fact in an introductory example; using C3 in Lean without a citation in the paper would add a dependency the text does not have. Revisit only if the paper''s example comes to cite the common-information paragraph. C3''s natural place to be cited is the optimal stale-global action (C8.b), which has no proof; that route is unchecked in Lean and needs the F6 link between the two definitions of admissible rule. F13 item 1 (the independence sentence) still asks for an edit.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (42, '2026-11-14T18:35:04', 'C5/a1', 'success', 'Proved 2026-11-14 against draft C5/f1. First claim proved from a supplement proof (C5/p1, three supplied steps; the paper gives no argument). With it C1, C2 and C12 no longer assume C5 in the assembly.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (43, '2026-11-14T19:18:58', 'C17.b/a1', 'success', 'Proved 2026-11-14 against draft C17.b/f1, unconditionally, on Mathlib v4.33.1 (no version bump). 192 lines, 1.7 s. Support: Routine/ProcessIntegral.lean (integrals of a process, Fubini), Routine/ProcessLaw.lean (the pair (weighted integral, process) is a function of the law of the process), Routine/Conditioning.lean (conditional variance, regret with one action coordinate, law of a Gaussian process from means and second moments), Routine/Canonical.lean and Routine/CanonicalTime.lean (regularity of the field and of the innovation). 0 <= r is not used by any step.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (44, '2026-11-14T19:33:03', 'C18/a1', 'success', 'Proved 2026-11-14 against draft C18/f1, unconditionally, on Mathlib v4.33.1 (no version bump, no vendored library). 554 lines, 1.8 s; Routine/CanonicalSpace.lean (378 lines) holds the proof''s notation (lineMid, lineTailR, lineTailL, lineY, lineRes, lineE, lineTailConst) and its regularity; Routine/CanonicalIntegrals.lean the covariance integrals, including the equal-length case, by an order of integration that needs no case split. One supplied step (s3b). The formula was checked numerically on a discretized field first (five parameter sets, four digits).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (45, '2026-11-14T19:33:03', 'C19/a2', 'success', 'Proved 2026-11-14 against draft C19/f2 with C16, C17.b and C18 as hypotheses; the assembly supplies all three. The theorem is now about the regret of the field, not only about the gain curve. C19/a1 (algebraic form, against C19/f1) is superseded; its file still builds, with main retargeted to C19.AlgebraicStatement.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (46, '2026-11-14T19:33:03', 'C19', 'decision', '2026-11-14 (Claude, as planned in the todo note of 2026-11-13 and README phase 4): C19/f1 superseded by C19/f2 once the tier D definitions existed. Scott has not reviewed f2.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (47, '2026-11-15T00:07:08', 'C8/f1', 'decision', 'Approval withdrawn, statement back to draft: Scott, 2026-11-15: a statement is frozen only after the agreed paper edits that touch it are upstream. F5.1 rewrites the corollary''s proof and may bring the optimal-action remark C8.b into it.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (48, '2026-11-15T13:35:42', 'C7.b/a1', 'success', 'Proved 2026-11-15 against the frozen statement C7.b/f1, from the supplement proof C7.b/p1 (2 supplied steps; the paper gives no argument). First try, no failed attempt.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (49, '2026-11-15T13:35:42', 'C13.b/a1', 'success', 'Proved 2026-11-15 against the frozen statement C13.b/f1, from the supplement proof C13.b/p1 (3 supplied steps; the paper gives no argument). First try, no failed attempt.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (50, '2026-11-15T13:35:42', 'C13.c/a1', 'success', 'Proved 2026-11-15 against the frozen statement C13.c/f1, from the supplement proof C13.c/p1 (5 supplied steps; the paper gives no argument). First try, no failed attempt.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (51, '2026-11-15T13:54:41', 'C1.c/a1', 'success', 'Proved 2026-11-15 against the frozen statement C1.c/f1, from the supplement proof C1.c/p1 (2 supplied steps; the paper gives no argument).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (52, '2026-11-15T13:54:41', 'C1.b/a1', 'success', 'Proved 2026-11-15 against the frozen statement C1.b/f1, from the supplement proof C1.b/p1 (3 supplied steps; the paper gives no argument).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (53, '2026-11-15T13:54:41', 'C6.b/a1', 'success', 'Proved 2026-11-15 against the frozen statement C6.b/f1, from the supplement proof C6.b/p1 (3 supplied steps; the paper gives no argument).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (54, '2026-11-15T13:54:41', 'C6.c/a1', 'success', 'Proved 2026-11-15 against the frozen statement C6.c/f1: the paper''s two steps plus two supplied steps, s0a (range, C6.c/d1) and s0b (the Doob-Dynkin link between the main text''s rules and the appendix''s sigma-algebra policies, F6.1). Step 1 goes through C1.c and s0b, as the ledger planned.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (55, '2026-11-15T13:58:49', 'C6.c/a1', 'decision', 'Scott, 2026-11-15: the monotonicity step is proved directly, by restricting a rule to the smaller view, as the paper''s sentence says. The first version of this attempt (commit eeb9a96) went through C1.c and a supplied Doob-Dynkin link step s0b; that step is removed, C6.c no longer depends on C1.c, and the link stays as Model.R_eq_sigmaRegret in Routine/RadiusInfo.lean, which backs F6.1. The hypothesis Measurable now of the frozen statement is no longer used by the proof.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (56, '2026-11-19T12:45:00', 'C10', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The statement now reads ''let R_inf > 0. If 0 <= eta_S(0) < 1, ...''. In the proof, step 2 was reworded (''For eta_S(0)<1, rearranging gives the threshold and equality case'') and the endpoint sentence is the new step 3, mapped to the new lemma s3_endpoint; main uses it in place of the line that had no paper sentence. F4.1 done, F4 closed. The Lean statement C10/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (57, '2026-11-19T12:45:00', 'C19', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The theorem says ''jointly Gaussian with covariance ... and sigma^2 > 0''. The proof has a new first sentence citing the field calculation: step C19/p1/s0, which uses C17.b and is mapped to the new lemma s0_field_regret; C17.b reaches step 2 through it. Step 1 was reworded (''The lemma gives ...''). F10.2, F10.3, F18.1 done; the differences C19/f2/d1 (sigma != 0) and C19/f2/d2 (jointly Gaussian) are no longer differences and were removed. The Lean statement C19/f2 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (58, '2026-11-19T12:45:00', 'C18', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The lemma now reads ''For the jointly Gaussian field with covariance ... and sigma^2 > 0''. The differences C18/f1/d1 (sigma != 0) and C18/f1/d2 (jointly Gaussian) are no longer differences and were removed. Proof steps unchanged (lines moved). The Lean statement C18/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (59, '2026-11-19T12:45:00', 'C17', 'todo', 'Realigned to arXiv v3 (upstream 12a9b32): the model paragraph now says ''variance sigma^2 > 0''. Defs/Canonical.lean (frozen) was left as it is and the difference is recorded as C17/f1/d3. The decision of 2026-11-15 says a definition file is reviewed again when an edit lands in a model paragraph: put to Scott whether sigma != 0 stays a hypothesis of C18 and C19 (recommended; no file changes) or moves into CanonicalField (a refreeze of Defs/Canonical.lean and of every statement that imports it).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (60, '2026-11-19T12:45:00', 'C11', 'done', 'Realigned to arXiv v3 (upstream 12a9b32): the example says ''variance sigma^2 > 0''. F18.2 done; the difference C11/f1/d1 is no longer a difference and was removed. The Lean statement C11/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (61, '2026-11-19T12:45:00', 'C14', 'done', 'Realigned to arXiv v3 (upstream 12a9b32): the section opens with ''Assume R_inf > 0 throughout this section'' (main-v3.tex 698), which the Lean statement already assumed. Claim lines 698-731. The Lean statement C14/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (62, '2026-11-19T12:45:00', 'C15', 'done', 'Realigned to arXiv v3 (upstream 12a9b32): the proposition opens with ''Suppose R(r)=R_inf[1-G(r)] for real r in [0,D], with G given by Eq. snapshot_gain'' in place of ''Under the assumptions of Theorem''. F8.1 done, F8 closed. The difference C15/f1/d1 was reworded: what remains is that Lean speaks of a maximizer of G and not of R. The Lean statements C15/f1, C15.b/f1 and C15.c/f1 did not change and are ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (63, '2026-11-19T12:45:00', 'C16', 'done', 'Realigned to arXiv v3 (upstream 12a9b32): the proposition opens with ''Suppose R(r)=R_inf[1-G(r)] for real r >= 0'' and ''For continuous r >= 0'' was dropped. The difference C16/f1/d1 was reworded: what remains is that Lean speaks of a maximizer of G and not of R. The Lean statement C16/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (64, '2026-11-19T12:45:00', 'C19.b', 'done', 'Realigned to arXiv v3 (upstream 12a9b32) (proof lines moved; text unchanged). New statement version C19.b/f2: the item on l_s compares two points that are both in the interior regime (disposition F11.1, now done). C19.b/f1 is superseded. Attempt C19.b/a1 was re-pointed to f2: the lemma for step 2 lost its third conjunct (the larger l_s outside the regime) and main was adjusted; the other lemmas are unchanged. Finding F11 has every point carried out and can be closed by Scott. C19.b/f2 is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (65, '2026-11-19T12:45:00', 'C4.b', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The remark''s hypothesis changed (F9): innovations with mean zero conditional on the past states, in place of ''independent, mean-zero''. The appendix now proves the remark: in-paper proof C4.b/p1, two steps. New statement version C4.b/f2 (C4.b/f1 superseded) and first attempt C4.b/a1, proved; step 2 uses C7, so C4.b now depends on C7. F9.1 and C4.b/d1 done, F9 closed. C4.b/f2 is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (66, '2026-11-19T12:45:00', 'C8', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The corollary is stated ''Under the tracking model and stationary transition'' and has a new proof, C8/p2 (two steps), which cites Eq. innovation_split and Eq. innovation_energy inside the proof of C7. Decision (Scott, 2026-11-18): Lean follows it through a declared cross-proof step dependency, C8/p2/s2 on C7/p1/s3 and C7/p1/s4; the new attempt C8/a2 imports C7''s proof file and its main takes no hypothesis. C8/p1 and C8/a1 are superseded (the file Proofs/C08/A1.lean is kept). The upstream change is recorded as the applied edit E1. F5.1 done, F5 closed. The Lean statement C8/f1 did not change and is ready for review.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (67, '2026-11-19T12:45:00', 'C8', 'decision', '2026-11-18 (Scott): the remark C8.b (''The optimal global action is a K theta_{t-tau}'') is merged into C8. arXiv v3 deleted the sentence and made the action the first sentence of the corollary''s proof. The claim row C8.b, its dependency on C7, the draft statement C8.b/f1 (TinaV2/Statements/C08b.lean, never reviewed, now deleted) and its difference row C8.b/f1/d1 were removed. The decision row C8.b/d1 is kept and points at C8. The draft statement had said: an admissible rule of the complete old snapshot has action a K theta_{t-tau} and its cost equals R_glob, without almost-sure uniqueness; the two step lemmas of C8/a2 state the same, and uniqueness is still not stated.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (68, '2026-11-19T12:45:00', 'C8.c', 'done', 'Realigned to arXiv v3 (upstream 12a9b32): the sentence now starts ''The regret is zero at zero delay'' (it read ''Its regret'', after the deleted sentence about the optimal action); claim lines 468-471. The frozen statement C8.c/f1 is about R_glob and is unaffected; the difference C8.c/f1/d2, which referred to C8.b, was reworded. C8 has a proved attempt against a draft statement, so the supplement proof of C8.c can be written once C8/f1 is frozen.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (69, '2026-11-19T12:45:00', 'C9', 'done', 'Realigned to arXiv v3 (upstream 12a9b32). The weights w_k are defined, the modes are ''centered'', and the paper derives the formula in three sentences: in-paper proof C9/p1 (steps s1-s3, main-v3.tex 483-490). F3.1 done, F3 closed.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (70, '2026-11-19T12:45:00', 'C9', 'todo', 'C9 has no Lean statement. Before anything is proved the statement needs a design Scott approves: how to state ''a complete old snapshot reveals independent centered stationary Ornstein-Uhlenbeck modes with coherence times T_k'' (C4.c, the single-mode case, has no statement either; its decision C4.c/d1 is to prove the prediction rule for a jointly Gaussian process with the stated covariance).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (71, '2026-11-19T13:13:27', 'C10', 'decision', '2026-11-19 (Scott, at the statement review): the equality clause of the Lean statement becomes an equivalence, as the new version C10/f2 (difference C10/f2/d3). C10/f1 said ''tau/T = rho* gives equal regret'', the theorem''s sentence taken literally; from it one gets only R_glob <= R_loc below the threshold. Checked in Lean before the change: the strict inequality below the threshold does not follow from C10/f1 as a statement, and does follow from C10/f2. Attempt C10/a1 re-pointed to f2 (step 2 lemma extended). C10/f1 is superseded. The eta_S(0) = 1 clause stays at the paper''s wording (no strict local advantage), although step 3 proves that stale-global is strictly better there. Also decided: the two sentences after the theorem (main-v3.tex 516-519) become the remark claim C10.b.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (72, '2026-11-19T13:13:27', 'C10.b', 'decision', '2026-11-19 (Scott): the two sentences after the crossover theorem (main-v3.tex 516-519) are tracked as the remark claim C10.b, like the remarks C8.c and C13.c. Until then they had no row. Draft statement C10.b/f1, not reviewed yet; supplement proof C10.b/p1 (3 supplied steps).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (73, '2026-11-19T13:13:27', 'C10.b/a1', 'success', 'Proved 2026-11-19 against the draft statement C10.b/f1, from the supplement proof C10.b/p1 with C10 (statement version f2) as a hypothesis. 77 lines. First try, no failed attempt.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (74, '2026-11-19T13:18:36', 'C17', 'decision', '2026-11-19 (Scott, at the review of C18): sigma^2 > 0 stays a hypothesis of C18 and C19 (as sigma != 0) and does not move into CanonicalField, although arXiv v3 states it in the model paragraph (main-v3.tex 815). The lemma and the theorem each repeat it in their own sentence, and C17.b holds without it. Defs/Canonical.lean and C17.b/f1 keep their approvals of 2026-11-14 and 2026-11-15; nothing is refrozen. This is the look at the definition file that the rule of 2026-11-15 asks for when an edit lands in a model paragraph. Difference C17/f1/d3.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (75, '2026-11-19T13:27:24', 'C15.b', 'insight', 'Tested numerically at the review of 2026-11-19, before any proof: 3000 random parameter sets of eta(r) = eta0 exp(-k r), tau(r) = alpha (r + c r^2) on [0, D], whose balance gap is strictly decreasing (854 with the optimum at 0, 79 at D, 2067 interior). The maximizer of G on a grid agrees with the case the statement names, and a larger T or a larger alpha moves it as C15.c says. No violation.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (76, '2026-11-19T13:27:24', 'C15.c', 'insight', 'Tested numerically at the review of 2026-11-19, before any proof: 3000 random parameter sets of eta(r) = eta0 exp(-k r), tau(r) = alpha (r + c r^2) on [0, D], whose balance gap is strictly decreasing (854 with the optimum at 0, 79 at D, 2067 interior). The maximizer of G on a grid agrees with the case the statement names, and a larger T or a larger alpha moves it as C15.c says. No violation.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (77, '2026-11-19T13:44:09', 'C8.c/a1', 'success', 'Proved 2026-11-19 against the frozen statement C8.c/f1, from the supplement proof C8.c/p1 (3 supplied steps) with C8 as a hypothesis. 89 lines. Typechecked first try, no failed attempt. Tested numerically first: (1 - e^{-2x} - 2x)/x is -0.19, -0.0020, -0.000020 at x = 1e-1, 1e-3, 1e-5.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (78, '2026-11-19T13:44:09', 'C13/a1', 'success', 'Proved 2026-11-19 against the frozen statement C13/f1, from the supplement proof C13/p1 (3 supplied steps) with C12 and C10 (f2) as hypotheses. 81 lines. One build cycle lost to a rewrite lemma (one_div_div), no failed attempt. Tested numerically first: 20000 random (n, q, gamma, sigma, T, tau), no violation of eta_S(0) < 1, R_inf > 0, the threshold identity or the equivalence. The hypothesis eta_S(0) < 1 of C10/f2 comes from step 2, as the handoff expected.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (79, '2026-11-19T13:44:10', 'C20/a1', 'success', 'Proved 2026-11-19 against the frozen statement C20/f1, from the supplement proof C20/p1 (3 supplied steps). 69 lines. One build cycle lost to a composition form, no failed attempt. Tested numerically first: 2000 random (l_s, v, T) with vT > 2 l_s, the error at l_c = 1e3, 1e5, 1e7 decreases to the limit in every case. The positive-radius condition is kept as step 1, as Bhaskar''s reply asked (C20/d1). The hypotheses 0 < v and 0 < T of C20/f1 are not used by any step (added to future-tasks.md, 1b), and C19 is not used as a hypothesis: the claim-graph edge ''C20 uses C19'' records that r* is the radius of that theorem.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (80, '2026-11-19T13:49:06', 'C15.b/a1', 'success', 'Proved 2026-11-19 against the frozen statement C15.b/f1, from the supplement proof C15.b/p1 (5 supplied steps). 141 lines. Typechecked first try, no failed attempt. No step uses C15 (the claim-graph edge records that the remark is about the proposition''s condition). Not used by any step: 0 < T, and of SmoothCurves the hypotheses tau'' >= 0, eta'' <= 0, 0 <= eta (added to future-tasks.md, 1b).');
INSERT INTO notes (id, ts, target, kind, body) VALUES (81, '2026-11-19T13:49:06', 'C15.c/a1', 'success', 'Proved 2026-11-19 against the frozen statement C15.c/f1, from the supplement proof C15.c/p1 (5 supplied steps) with C15.b as a hypothesis. 151 lines. Typechecked first try, no failed attempt. The argument differs from the hand-worked one in paper-findings-2026-11-14.md, section 3 (''G is still increasing on [0, r]''): it compares the signs of the gap at the two maximizers, which uses C15.b only through its statement. tau_0'' >= 0 is the hypothesis that carries the result (step 2); eta'' <= 0 and 0 <= eta are not used.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (82, '2026-11-19T13:54:21', 'C9', 'insight', '2026-11-19: a statement design for C9 and C4.c was put to Scott and is not decided; no Lean statement exists yet. Draft read: ''Ornstein-Uhlenbeck'' as a centered jointly Gaussian process with E[theta_t,j theta_s,l] = exp(-|t-s|/T_mode(j)) S_jl (the reading of C4.c/d1), modes as groups of state coordinates, S zero across modes. Tested before showing it. Numerically (pure Python, Gaussian conditioning formula): 3000 random cases with 1-3 modes, worst error 3e-11 in sum_k w_k = 1 and in 1 - R_glob/R_inf = sum_k w_k exp(-2 tau/T_k). In a scratch Lean file, with both drafts as hypotheses: the C4.c draft feeds C8 (closed form of R_glob for such a state); the matrix S is forced to be the second-moment matrix and symmetric; the covariance formula alone forces S_jl = 0 for two coordinates whose modes have different coherence times, so the cross-mode hypothesis only adds something when two modes share a rate; with one mode the C9 draft gives 1 - R_glob/R_inf = exp(-2 tau/T), the normalized form of C8.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (83, '2026-11-19T14:25:48', 'C9', 'insight', '2026-11-19, later session: Scott answered the six design questions. Decided: hypotheses inline, no Defs/OU.lean (6). On (1) he asked which reading of ''Ornstein-Uhlenbeck'' is more correct mathematically (SDE: vendor; Gaussian process with the covariance: OK); on (2)-(5) he asked for a careful evaluation and advice. Advice given, NOT yet decided by Scott, no statement file exists: (1) Gaussian process with the stated covariance. Every conclusion of C4.c and C9 depends only on the law of the process, and a stationary solution of the SDE is such a process, so this is the weaker hypothesis. What it does not check is the appendix''s sentence that the SDE as displayed has covariance exp(-|t-s|/T) Sigma_S (checked by hand: the stationary covariance P solves -(2/T)P + (2/T)Sigma_S = 0). Vendoring atlas-lean would not state the SDE either: its OU file defines the process by its covariance (scalar) and adds existence. Mathlib v4.33.1 has scalar Brownian motion on [0, inf) (IsBrownianReal) but no stochastic integral, no two-sided and no multivariate Brownian motion. (2) Mean zero: the main text centers known means throughout (main-v3.tex 214-216), TemporalAssumption and Rinf are written in centered coordinates, a process with nonzero mean does not satisfy the assumption, and the general-mean statement is the mean-zero one applied to theta - thetabar. (3) CHANGED from the earlier recommendation: the innovation is Gaussian and independent of the whole earlier history (theta_s : s <= t - tau), plus TemporalAssumption at every t and tau >= 0. The earlier reason for stopping at the old state misread the appendix''s last sentence, which is about neighborhood snapshots. Same proof (Mathlib''s indepFun_of_covariance_eq_zero takes any index type); it implies independence from the old state. (4) CHANGED: mode k is the part P_k theta of the state, with matrices P_k summing to the identity, x_k* = K P_k theta. Contains coordinate groups (P_k a diagonal mask) and covers the two-server example with the two loads as state coordinates (total and difference). Same length as the coordinate-group text. (5) Literal, refined: each mode satisfies exactly C4.c''s hypotheses with its own T_k and S_k, and the mode processes are independent (iIndepFun), in place of one jointly Gaussian state with zero cross-covariance. Then ''independent'', ''centered'', ''OU with coherence time T_k'' each have their own hypothesis, the paper''s first sentence is a real step, and the proof uses C4.c per mode. The version without Gaussianity (each mode satisfies the temporal assumption) is a generalization to park in future-tasks.md. Tests (scratch Lean against import TinaV2.Statements, all pass): the new C4.c implies the old draft; the general-mean form at thetabar = 0 is the mean-zero form; C4.c feeds C8; with one mode (P = 1) the new C9 gives 1 - Rglob/Rinf = exp(-2 tau/T) from exactly C4.c''s hypotheses; the projection form implies the coordinate-group form; the total/difference matrices sum to 1; each S_k is forced to be the second-moment matrix of mode k. Numerics (pure Python, Gaussian conditioning formula): 3000 random cases with theta = B y, y in 1-3 independent blocks, P_k = B mask_k B^-1: worst error 2e-9 in sum w_k = 1 and in the formula. Two servers with the loads as coordinates: both sides 0.58776652. If the snapshot does not reveal the modes (scalar theta = y1 + y2 with different rates) the formula fails (true 0.2276, formula 0.3443), so ''reveals'' is a real hypothesis; both encodings build it in. Drafts as tested:
INSERT INTO notes (id, ts, target, kind, body) VALUES (84, '2026-11-19T14:34:14', 'C4.c', 'done', '2026-11-19: Scott chose the statement design (''Go with your advice on all''): OU read as a Gaussian process with the stated covariance; mean zero; the innovation Gaussian and independent of the whole earlier history; hypotheses inline. Draft statement C4.c/f1 created with six difference rows; it waits for Scott''s review and is not frozen. The old note about bumping to Mathlib v4.35.0 and vendoring atlas-lean is not followed: nothing is vendored.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (85, '2026-11-19T14:34:14', 'C4.c/f1', 'insight', 'Tests of C4.c/f1 before the review (scratch Lean against the built TinaV2.Statements, all pass): the statement gives independence of the innovation from the old state theta_{t-tau} and from any theta_s with s <= t - tau; it feeds C8 (R_glob = (1 - exp(-2 tau/T)) R_inf for such a state); S is forced to be the second-moment matrix and symmetric; the covariance hypothesis cannot hold through the default value of a non-integrable integral, because each product of two coordinates of a Gaussian process is integrable; T <= 0 is excluded by hypothesis. An earlier scratch test showed the general-mean form at thetabar = 0 is this statement.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (86, '2026-11-19T14:34:14', 'C9', 'done', '2026-11-19: Scott chose the statement design (''Go with your advice on all''): modes as parts P_k theta with sum P_k = 1; each mode satisfies C4.c''s hypotheses with its own T_k; the mode processes independent (iIndepFun); hypotheses inline. Draft statement C9/f1 created with eight difference rows; it waits for Scott''s review and is not frozen.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (87, '2026-11-19T14:34:14', 'C9/f1', 'insight', 'Tests of C9/f1 before the review. Scratch Lean against the built TinaV2.Statements, all pass: with one mode (P = 1) it gives 1 - R_glob/R_inf = exp(-2 tau/T) from exactly the hypotheses of C4.c/f1; each mode''s hypotheses are C4.c''s, so C4.c gives TemporalAssumption for the mode with T_k; the first conclusion follows from sum P_k = 1 alone; the denominator of the weights is 2 R_inf, positive by hypothesis; each S_k is forced. An earlier scratch test showed this form implies the coordinate-group form (P_k a diagonal mask). Numerics (pure Python, Gaussian conditioning formula, theta = B y with y in 1-3 independent blocks and P_k = B mask_k B^-1): 3000 random cases, worst error 2e-9 in sum w_k = 1 and in the formula; two servers with the loads as state coordinates give 0.58776652 on both sides; a scalar state that is a sum of two parts with different rates gives 0.2276 against the formula''s 0.3443, so the snapshot must reveal the modes.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (88, '2026-11-19T14:40:30', 'C4.c/a1', 'success', 'Proved 2026-11-19 against the frozen statement C4.c/f1, from the supplement proof C4.c/p1 (4 supplied steps). Typechecked on the second cycle (a missing IsProbabilityMeasure instance on step 2, an eta mismatch in const_smul, one unused section variable). No failed attempt. Numeric check of the two covariance identities (20000 random T, tau, t, s <= t - tau): the innovation''s covariance with theta_s vanishes to 3e-15 and its variance is (1 - a^2) Sigma_S to 5e-15. Hypotheses not used: T > 0 is used only by `main`, for the T_pos field of TemporalAssumption; steps 1-4 hold for any real T.');
INSERT INTO notes (id, ts, target, kind, body) VALUES (89, '2026-11-19T14:57:28', 'C9/a1', 'success', 'Proved 2026-11-19 against the frozen statement C9/f1, from the paper proof C9/p1 (three paper steps, verbatim) with three supplied steps (s0 decomposition, s2a conditioning on the whole snapshot, s2b regret = R_inf minus half the captured gain; dispositions C9/d1-d3) and C4.c as a hypothesis. 520 lines plus Routine/Modes.lean (quadratic form of a finite sum, linearity of conditional expectation for a vector with conditional mean zero, orthogonality to what a sigma-algebra determines). Typechecked on the second cycle; the first cycle''s errors were a missing import, unification of comap_measurable, and a rewrite that also hit the sigma-algebra. No failed attempt. The handoff expected one supplied step (2a); steps 0 and 2b were added because ''main'' may only combine steps and because the paper''s ''captured quadratic gain'' presumes the identity of step 2b. Numerics are in the note on C9/f1. Hypothesis not used by any step: measurability of theta_t is not needed for step 1; the matrices S_k are used only through C4.c.');
